-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_a03744a7bfa6e6', 'subj_math', 'midpoint-formula', 'Midpoint formula', 'M = \left(\frac{x_1 + x_2}{2},\ \frac{y_1 + y_2}{2}\right)', 'The midpoint of the segment joining (x₁, y₁) and (x₂, y₂): the average of the x-coordinates and of the y-coordinates.', '[{"symbol":"(x_1, y_1), (x_2, y_2)","meaning":"endpoints"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_e93ad1840eaca9', 'subj_math', 'polygon-angle-sum', 'Polygon angle sums', 'S = (n - 2) \cdot 180^\circ, \quad \text{each exterior angle of a regular } n\text{-gon} = \frac{360^\circ}{n}', 'Sum of the interior angles of a convex polygon with n sides. The exterior angles (one at each vertex) always sum to 360°.', '[{"symbol":"n","meaning":"number of sides"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_ce103b0d7be6b4', 'subj_math', 'trig-ratios', 'Trigonometric ratios', '\sin\theta = \frac{\text{opp}}{\text{hyp}}, \quad \cos\theta = \frac{\text{adj}}{\text{hyp}}, \quad \tan\theta = \frac{\text{opp}}{\text{adj}}', 'Ratios of side lengths in a right triangle, relative to an acute angle θ.', '[{"symbol":"\\theta","meaning":"acute angle"},{"symbol":"\\text{opp, adj, hyp}","meaning":"opposite leg, adjacent leg, hypotenuse"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1902fc327ff81c', 'subj_math', 'special-right-triangles', 'Special right triangles', '45^\circ\text{-}45^\circ\text{-}90^\circ: \ x : x : x\sqrt{2} \qquad 30^\circ\text{-}60^\circ\text{-}90^\circ: \ x : x\sqrt{3} : 2x', 'Side ratios of the isosceles right triangle and the 30-60-90 triangle (short leg : long leg : hypotenuse).', '[{"symbol":"x","meaning":"length of a leg (45-45-90) or the short leg (30-60-90)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_c96324d9455ca0', 'subj_math', 'arc-length-sector', 'Arc length and sector area', 's = \frac{\theta}{360^\circ} \cdot 2\pi r = r\theta_{\text{rad}}, \qquad A = \frac{\theta}{360^\circ} \cdot \pi r^2 = \tfrac{1}{2} r^2 \theta_{\text{rad}}', 'Length of an arc and area of a sector with central angle θ in a circle of radius r.', '[{"symbol":"\\theta","meaning":"central angle (degrees, or radians where marked)"},{"symbol":"r","meaning":"radius"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1bb37d22b941d4', 'subj_math', 'circle-equation', 'Equation of a circle', '(x - h)^2 + (y - k)^2 = r^2', 'The circle with center (h, k) and radius r > 0: every point at distance r from the center.', '[{"symbol":"(h, k)","meaning":"center"},{"symbol":"r","meaning":"radius"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_2f888f52e9cffc', 'subj_math', 'pyramid-cone-sphere', 'Pyramids, cones and spheres', 'V_{\text{pyramid/cone}} = \tfrac{1}{3}Bh, \quad V_{\text{sphere}} = \tfrac{4}{3}\pi r^3, \quad S_{\text{sphere}} = 4\pi r^2', 'A pyramid or cone has one third the volume of the prism or cylinder with the same base B and height h.', '[{"symbol":"B","meaning":"base area"},{"symbol":"h","meaning":"perpendicular height"},{"symbol":"r","meaning":"radius"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_70fe875641de53', 'subj_math', 'permutations-combinations', 'Permutations and combinations', '{}_nP_r = \frac{n!}{(n - r)!}, \qquad {}_nC_r = \binom{n}{r} = \frac{n!}{r!\,(n - r)!}', 'Number of ordered arrangements (permutations) and unordered selections (combinations) of r items from n distinct items.', '[{"symbol":"n","meaning":"items available"},{"symbol":"r","meaning":"items chosen"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_6193ebe8c598f1', 'subj_math', 'probability-rules', 'Probability rules', 'P(A \text{ or } B) = P(A) + P(B) - P(A \text{ and } B), \quad P(A \text{ and } B) = P(A) \cdot P(B \mid A)', 'Addition rule and general multiplication rule. If A and B are independent, P(B | A) = P(B).', '[{"symbol":"P(B \\mid A)","meaning":"probability of B given that A occurred"}]', 'published');

-- Lesson: angle-pair-relationships
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_558d097bd65439', 'angle-pair-relationships', 'Angle pair relationships', 'Identify adjacent, vertical, complementary and supplementary angles and linear pairs, and use their relationships to find unknown angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4727252ffe1d45', 'les_558d097bd65439', 1, 'Identify adjacent angles, linear pairs and vertical angles in a figure.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ea41295d6f2e2', 'les_558d097bd65439', 2, 'Use complementary and supplementary relationships to write and solve equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f1499cefb8d10', 'les_558d097bd65439', 3, 'Explain why vertical angles are congruent.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4727252ffe1d45', 'les_558d097bd65439', 'learn', 1, 'definition', '{"term":"Complementary and supplementary","body":"Two angles are complementary if their measures sum to $90^\\circ$ and supplementary if they sum to $180^\\circ$. They don''t have to be next to each other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ea41295d6f2e2', 'les_558d097bd65439', 'learn', 2, 'definition', '{"term":"Adjacent angles and linear pairs","body":"Adjacent angles share a vertex and a side but no interior points. A linear pair is two adjacent angles whose outer sides are opposite rays; they are supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f1499cefb8d10', 'les_558d097bd65439', 'learn', 3, 'definition', '{"term":"Vertical angles","body":"The two nonadjacent angles formed when two lines intersect. Vertical angles are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_faac7c181d039d', 'les_558d097bd65439', 'learn', 4, 'text', '{"body":"Why are vertical angles congruent? When two lines cross, label the angles 1, 2, 3, 4 around the point, with 1 and 3 vertical. Angles 1 and 2 form a linear pair, and so do 2 and 3. So $m\\angle 1 + m\\angle 2 = 180^\\circ = m\\angle 2 + m\\angle 3$. Subtracting $m\\angle 2$ gives $m\\angle 1 = m\\angle 3$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_91647760b72bf9', 'les_558d097bd65439', 'learn', 5, 'worked_example', '{"title":"Two lines intersect. One angle measures $(3x + 10)^\\circ$ and its vertical angle measures $(5x - 30)^\\circ$. Find all four angles.","steps":[{"latex":"3x + 10 = 5x - 30 \\Rightarrow x = 20","explanation":"Vertical angles are congruent."},{"latex":"3(20) + 10 = 70^\\circ","explanation":""},{"latex":"70^\\circ, 110^\\circ, 70^\\circ, 110^\\circ","explanation":"Each neighbor forms a linear pair: 180 − 70 = 110."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8608f8e72ff53a', 'les_558d097bd65439', 'learn', 6, 'worked_example', '{"title":"An angle is $12^\\circ$ more than twice its complement. Find it.","steps":[{"latex":"x + (2x + 12) = 90","explanation":"Let x be the complement."},{"latex":"3x = 78 \\Rightarrow x = 26","explanation":""},{"latex":"2(26) + 12 = 64^\\circ","explanation":"Check: $64 + 26 = 90$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9213ede9bb25e', 'les_558d097bd65439', 'learn', 7, 'callout', '{"tone":"warning","title":"Don''t assume from a picture","body":"Diagrams aren''t always drawn to scale. Only use relationships that are marked or follow from given facts, not ones that \"look\" right."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb9d2695933830', 'les_558d097bd65439', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scissors and crossing roads form vertical angles; a ramp meeting flat ground forms a linear pair. Carpenters cut complementary angles to make picture-frame corners fit at $90^\\circ$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4727252ffe1d45', 'les_558d097bd65439', 1, 'practice', 'numeric', 1, 'Find the complement of a $37^\circ$ angle.', '{"answer":53,"unit":"°"}', '[]', '$90 - 37 = 53^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ea41295d6f2e2', 'les_558d097bd65439', 2, 'practice', 'numeric', 1, 'Find the supplement of a $112^\circ$ angle.', '{"answer":68,"unit":"°"}', '[]', '$180 - 112 = 68^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f1499cefb8d10', 'les_558d097bd65439', 3, 'practice', 'numeric', 2, 'Two angles form a linear pair. One is $(4x + 8)^\circ$ and the other is $(2x + 22)^\circ$. Find $x$.', '{"answer":25}', '["They sum to 180."]', '$6x + 30 = 180$, $x = 25$ (angles 108° and 72°).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_faac7c181d039d', 'les_558d097bd65439', 4, 'practice', 'numeric', 2, 'Vertical angles measure $(7x - 12)^\circ$ and $(4x + 27)^\circ$. Find the angle measure.', '{"answer":79,"unit":"°"}', '["Set them equal: x = 13."]', '$7(13) - 12 = 79^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_91647760b72bf9', 'les_558d097bd65439', 5, 'practice', 'multiple_choice', 2, 'Can two acute angles be supplementary?', '{"choices":["Yes, always","No; their sum is less than 180°","Only if both are 90°","Only if they are vertical"],"answer":1}', '["Each acute angle is less than 90°."]', 'Two angles each less than $90^\circ$ sum to less than $180^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8608f8e72ff53a', 'les_558d097bd65439', 6, 'review', 'numeric', 3, 'The supplement of an angle is 4 times its complement. Find the angle.', '{"answer":60,"unit":"°"}', '["$180 - x = 4(90 - x)$."]', '$180 - x = 360 - 4x$, so $3x = 180$ and $x = 60^\circ$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_271efe70aeb910', 'subj_math', 'angle-pairs', 'Angle pairs', 'Adjacent, vertical, complementary, supplementary angles and linear pairs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_558d097bd65439', (SELECT id FROM concepts WHERE slug = 'angle-pairs'));

-- Lesson: angles-elevation-depression
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_14c5313251ad05', 'angles-elevation-depression', 'Angles of elevation and depression', 'Model real situations with angles of elevation and depression, and solve them with right-triangle trigonometry, including two-triangle problems.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d749355a4d2c43', 'les_14c5313251ad05', 1, 'Identify angles of elevation and depression and explain why they are congruent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8761375550df14', 'les_14c5313251ad05', 2, 'Draw a diagram and solve height and distance problems with trig ratios.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_85763569a46d90', 'les_14c5313251ad05', 3, 'Solve problems that involve two right triangles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d749355a4d2c43', 'les_14c5313251ad05', 'learn', 1, 'definition', '{"term":"Elevation and depression","body":"An angle of elevation is measured up from the horizontal to a line of sight. An angle of depression is measured down from the horizontal. The angle of depression from A to B equals the angle of elevation from B to A: they''re alternate interior angles between two horizontal (parallel) lines."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8761375550df14', 'les_14c5313251ad05', 'learn', 2, 'worked_example', '{"title":"From 40 m away from a building, the angle of elevation to its top is $52^\\circ$. How tall is it? (Ignore eye height.)","steps":[{"latex":"\\tan 52^\\circ = \\tfrac{h}{40}","explanation":""},{"latex":"h = 40\\tan 52^\\circ \\approx 51.2 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85763569a46d90', 'les_14c5313251ad05', 'learn', 3, 'worked_example', '{"title":"A lighthouse keeper 30 m above the sea sees a boat at an angle of depression of $8^\\circ$. How far is the boat from the base of the lighthouse?","steps":[{"latex":"\\text{angle of elevation from the boat} = 8^\\circ","explanation":"Alternate interior angles."},{"latex":"\\tan 8^\\circ = \\tfrac{30}{d} \\Rightarrow d = \\tfrac{30}{\\tan 8^\\circ} \\approx 213.5 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfa7e3586072ff', 'les_14c5313251ad05', 'learn', 4, 'worked_example', '{"title":"From a point, the angle of elevation to a tree top is $35^\\circ$. Moving 10 m closer, it becomes $50^\\circ$. How tall is the tree?","steps":[{"latex":"h = x\\tan 50^\\circ = (x + 10)\\tan 35^\\circ","explanation":"x is the closer distance."},{"latex":"x(\\tan 50^\\circ - \\tan 35^\\circ) = 10\\tan 35^\\circ","explanation":""},{"latex":"x = \\tfrac{7.002}{1.1918 - 0.7002} \\approx 14.24,\\ h \\approx 16.97 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df7ede60955505', 'les_14c5313251ad05', 'learn', 5, 'callout', '{"tone":"tip","title":"Always sketch","body":"Draw the horizontal line first, mark the angle from it, then label the right triangle. Most errors come from measuring the angle from the vertical instead of the horizontal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e320b749a81c7', 'les_14c5313251ad05', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pilots use angles of descent, surveyors find heights of cliffs, astronomers measure a star''s altitude, and archers and golfers judge targets uphill or downhill."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d749355a4d2c43', 'les_14c5313251ad05', 1, 'practice', 'numeric', 1, 'From 25 ft away, the angle of elevation to the top of a flagpole is $60^\circ$. How tall is the pole, to the nearest tenth?', '{"answer":43.3,"unit":"ft","tolerance":0.06}', '["$25\\tan 60^\\circ$."]', '$25\sqrt{3} \approx 43.3$ ft.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8761375550df14', 'les_14c5313251ad05', 2, 'practice', 'numeric', 2, 'A plane at 2,000 m altitude sees a runway at an angle of depression of $6^\circ$. What is the horizontal distance to the runway, to the nearest meter?', '{"answer":19029,"unit":"m","tolerance":1}', '["$2000 / \\tan 6^\\circ$."]', '$2000 / 0.10510 \approx 19{,}029$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85763569a46d90', 'les_14c5313251ad05', 3, 'practice', 'numeric', 2, 'A 50 m kite string makes a $40^\circ$ angle with the ground. How high is the kite, to the nearest tenth?', '{"answer":32.1,"unit":"m","tolerance":0.06}', '["$50\\sin 40^\\circ$."]', '$50(0.6428) \approx 32.1$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfa7e3586072ff', 'les_14c5313251ad05', 4, 'practice', 'multiple_choice', 2, 'The angle of depression from a cliff top to a boat is $20^\circ$. What is the angle of elevation from the boat to the cliff top?', '{"choices":["70°","20°","160°","40°"],"answer":1}', '[]', 'They are alternate interior angles, so $20^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df7ede60955505', 'les_14c5313251ad05', 5, 'review', 'numeric', 3, 'A person 1.7 m tall stands 12 m from a tree and sees its top at an angle of elevation of $33^\circ$. How tall is the tree, to the nearest tenth?', '{"answer":9.5,"unit":"m","tolerance":0.06}', '["$12\\tan 33^\\circ$, then add eye height."]', '$12(0.6494) + 1.7 \approx 7.79 + 1.7 = 9.5$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_68e5b8ea0a287f', 'subj_math', 'trigonometric-ratios', 'Trigonometric ratios', 'Sine, cosine and tangent: ratios of sides in a right triangle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_14c5313251ad05', (SELECT id FROM concepts WHERE slug = 'trigonometric-ratios'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_14c5313251ad05', (SELECT id FROM formulas WHERE slug = 'trig-ratios'), 1);

-- Lesson: arc-length-radians
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8911b1d76837a8', 'arc-length-radians', 'Arc length and radian measure', 'Find arc lengths as a fraction of the circumference, define radians from arc length, and convert between degrees and radians.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_84bb445eb2102d', 'les_8911b1d76837a8', 1, 'Compute arc length from the central angle and radius.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_477288237a512e', 'les_8911b1d76837a8', 2, 'Define a radian and explain why 180° = π radians.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_645379bfa8af85', 'les_8911b1d76837a8', 3, 'Convert between degrees and radians and use s = rθ.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84bb445eb2102d', 'les_8911b1d76837a8', 'learn', 1, 'text', '{"body":"An arc is a fraction of the whole circle. A $90^\\circ$ arc is $\\frac{90}{360} = \\frac{1}{4}$ of the circle, so its length is $\\frac{1}{4}$ of the circumference $2\\pi r$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_477288237a512e', 'les_8911b1d76837a8', 'learn', 2, 'formula', '{"latex":"s = \\frac{\\theta}{360^\\circ} \\cdot 2\\pi r","title":"Arc length (degrees)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_645379bfa8af85', 'les_8911b1d76837a8', 'learn', 3, 'worked_example', '{"title":"Find the length of a $150^\\circ$ arc in a circle of radius 6 cm.","steps":[{"latex":"s = \\tfrac{150}{360} \\cdot 2\\pi(6) = \\tfrac{5}{12} \\cdot 12\\pi = 5\\pi","explanation":""},{"latex":"s \\approx 15.71 \\text{ cm}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c3a667c14ac47', 'les_8911b1d76837a8', 'learn', 4, 'definition', '{"term":"Radian","body":"One radian is the central angle whose arc length equals the radius. Since the whole circumference is $2\\pi$ radii, a full turn is $2\\pi$ radians: $360^\\circ = 2\\pi$, so $180^\\circ = \\pi$ radians."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ff2f6d44b8cf3', 'les_8911b1d76837a8', 'learn', 5, 'text', '{"body":"Convert degrees to radians by multiplying by $\\frac{\\pi}{180}$, and radians to degrees by multiplying by $\\frac{180}{\\pi}$. For example $60^\\circ = \\frac{\\pi}{3}$ and $\\frac{3\\pi}{4} = 135^\\circ$. In radians, arc length is simply $s = r\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5471bfc042ef02', 'les_8911b1d76837a8', 'experiment', 6, 'activity', '{"activity":"circle-angles","title":"Degrees, radians and arc length","params":{"arc":60,"p":220,"r":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1eb93b5ec57b57', 'les_8911b1d76837a8', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"With radius 1, the arc length equals the angle in radians. Set the arc to $180^\\circ$: the arc length is $\\pi \\approx 3.14$. Which arc gives an arc length of exactly 1 (about $57.3^\\circ$)?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_99ef5dbec21145', 'les_8911b1d76837a8', 'learn', 8, 'worked_example', '{"title":"A wheel of radius 0.3 m turns through 5 radians. How far does a point on the rim travel?","steps":[{"latex":"s = r\\theta = 0.3 \\cdot 5 = 1.5 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7b281cc5f1478', 'les_8911b1d76837a8', 'learn', 9, 'callout', '{"tone":"warning","title":"Match the units","body":"$s = r\\theta$ works only with $\\theta$ in radians. With degrees, use the fraction-of-circumference formula."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f39d39b3f8973', 'les_8911b1d76837a8', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Radians are the natural unit in calculus, physics (angular speed in rad/s) and programming: most code libraries'' sin and cos functions expect radians."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_84bb445eb2102d', 'les_8911b1d76837a8', 1, 'practice', 'numeric', 1, 'Find the length of a $90^\circ$ arc of a circle with radius 8, to the nearest hundredth.', '{"answer":12.57,"tolerance":0.006}', '["$\\frac{1}{4} \\cdot 16\\pi$."]', '$4\pi \approx 12.57$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_477288237a512e', 'les_8911b1d76837a8', 2, 'practice', 'numeric', 2, 'Convert $225^\circ$ to radians, as a decimal to the nearest hundredth.', '{"answer":3.93,"tolerance":0.006}', '["$225 \\cdot \\frac{\\pi}{180} = \\frac{5\\pi}{4}$."]', '$\frac{5\pi}{4} \approx 3.93$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_645379bfa8af85', 'les_8911b1d76837a8', 3, 'practice', 'numeric', 2, 'Convert $\frac{2\pi}{3}$ radians to degrees.', '{"answer":120,"unit":"°"}', '[]', '$\frac{2\pi}{3} \cdot \frac{180}{\pi} = 120^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c3a667c14ac47', 'les_8911b1d76837a8', 4, 'practice', 'numeric', 2, 'An arc of a circle with radius 4 has length 10. What is the central angle in radians?', '{"answer":2.5}', '["$\\theta = s / r$."]', '$10 / 4 = 2.5$ radians.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ff2f6d44b8cf3', 'les_8911b1d76837a8', 5, 'review', 'multiple_choice', 3, 'About how many degrees is 1 radian?', '{"choices":["1°","3.14°","57.3°","90°"],"answer":2}', '["$\\frac{180}{\\pi}$."]', '$180 / \pi \approx 57.3^\circ$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a6aedb62ecc78a', 'subj_math', 'radian-measure', 'Radian measure', 'Measuring angles by the ratio of arc length to radius; π radians = 180°.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8911b1d76837a8', (SELECT id FROM concepts WHERE slug = 'radian-measure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8911b1d76837a8', (SELECT id FROM formulas WHERE slug = 'arc-length-sector'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8911b1d76837a8', (SELECT id FROM formulas WHERE slug = 'circle-area'), 2);

-- Lesson: arcs-central-angles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1926f9c426d08e', 'arcs-central-angles', 'Arcs and central angles', 'Name and measure minor arcs, major arcs and semicircles, use the Arc Addition Postulate, and relate congruent chords to congruent arcs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b47f2476284d69', 'les_1926f9c426d08e', 1, 'Identify central angles, minor arcs, major arcs and semicircles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c64b1323c71e20', 'les_1926f9c426d08e', 2, 'Find arc measures with central angles and the Arc Addition Postulate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e5a0bf311af3e', 'les_1926f9c426d08e', 3, 'Use the relationships between congruent chords, arcs and central angles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b47f2476284d69', 'les_1926f9c426d08e', 'learn', 1, 'definition', '{"term":"Circle vocabulary","body":"A circle is all points in a plane at distance $r$ (the radius) from a center. A chord joins two points on the circle; a diameter is a chord through the center. A central angle has its vertex at the center."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c64b1323c71e20', 'les_1926f9c426d08e', 'learn', 2, 'definition', '{"term":"Arcs","body":"A minor arc is less than $180^\\circ$ and is named by two endpoints, $\\overset{\\frown}{AB}$. A major arc is more than $180^\\circ$ and is named with three letters, $\\overset{\\frown}{ACB}$. A semicircle is $180^\\circ$. A minor arc''s measure equals its central angle; a major arc measures $360^\\circ$ minus the minor arc."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e5a0bf311af3e', 'les_1926f9c426d08e', 'learn', 3, 'definition', '{"term":"Arc Addition Postulate","body":"The measure of an arc formed by two adjacent arcs is the sum of their measures: $m\\overset{\\frown}{ABC} = m\\overset{\\frown}{AB} + m\\overset{\\frown}{BC}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9031698a9545d', 'les_1926f9c426d08e', 'experiment', 4, 'activity', '{"activity":"circle-angles","title":"Central angle and arc","params":{"arc":100,"p":230,"r":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e99d8f1b3fc37', 'les_1926f9c426d08e', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The central angle readout always matches the arc. Push the arc past $180^\\circ$: now the shaded region is a major arc. What is the measure of the other arc?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_338bfdbb1864f8', 'les_1926f9c426d08e', 'learn', 6, 'worked_example', '{"title":"$\\overline{AC}$ is a diameter of circle $O$, and $m\\angle AOB = 64^\\circ$. Find $m\\overset{\\frown}{BC}$ and the major arc $m\\overset{\\frown}{BAC}$.","steps":[{"latex":"m\\overset{\\frown}{BC} = 180^\\circ - 64^\\circ = 116^\\circ","explanation":"AB and BC together make a semicircle."},{"latex":"m\\overset{\\frown}{BAC} = 360^\\circ - 116^\\circ = 244^\\circ","explanation":"The major arc from B to C through A."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eee45859899f1b', 'les_1926f9c426d08e', 'learn', 7, 'definition', '{"term":"Chords and arcs","body":"In the same circle (or congruent circles), two chords are congruent if and only if their arcs are congruent, if and only if their central angles are congruent. A diameter perpendicular to a chord bisects the chord and its arc."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e083e541045fd9', 'les_1926f9c426d08e', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pie charts turn percentages into central angles (25% → $90^\\circ$), clocks move $30^\\circ$ per hour, and gears and wheels are designed with arc measures."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b47f2476284d69', 'les_1926f9c426d08e', 1, 'practice', 'numeric', 1, 'A central angle measures $72^\circ$. What is the measure of its minor arc?', '{"answer":72,"unit":"°"}', '[]', '$72^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c64b1323c71e20', 'les_1926f9c426d08e', 2, 'practice', 'numeric', 1, 'A minor arc measures $130^\circ$. Find the measure of the corresponding major arc.', '{"answer":230,"unit":"°"}', '[]', '$360 - 130 = 230^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e5a0bf311af3e', 'les_1926f9c426d08e', 3, 'practice', 'numeric', 2, 'In a pie chart, a category is 15% of the total. What central angle does it get?', '{"answer":54,"unit":"°"}', '[]', '$0.15 \cdot 360 = 54^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9031698a9545d', 'les_1926f9c426d08e', 4, 'practice', 'numeric', 2, 'Adjacent arcs $\overset{\frown}{AB}$ and $\overset{\frown}{BC}$ measure $(3x + 10)^\circ$ and $(2x)^\circ$, and $m\overset{\frown}{ABC} = 110^\circ$. Find $m\overset{\frown}{AB}$.', '{"answer":70,"unit":"°"}', '[]', '$5x + 10 = 110$, $x = 20$, so $70^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5e99d8f1b3fc37', 'les_1926f9c426d08e', 5, 'review', 'multiple_choice', 3, 'A diameter is perpendicular to a chord of length 16. What does the diameter do to the chord?', '{"choices":["Nothing","Bisects it into two segments of 8","Makes it a diameter","Doubles it"],"answer":1}', '[]', 'A diameter perpendicular to a chord bisects it, giving two segments of 8.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_021a201c0027d2', 'subj_math', 'circles', 'Circles', 'Sets of points at a fixed distance from a center; arcs, chords and angles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1926f9c426d08e', (SELECT id FROM concepts WHERE slug = 'circles'));

-- Lesson: areas-of-polygons
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_20249b00d6d3c3', 'areas-of-polygons', 'Areas of polygons', 'Use area formulas for triangles, parallelograms, trapezoids, rhombuses and kites, find areas of regular polygons with the apothem, and compute area on the coordinate plane.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1331dcccc16146', 'les_20249b00d6d3c3', 1, 'Apply area formulas for triangles, parallelograms, trapezoids, rhombuses and kites.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35a0fe396b2756', 'les_20249b00d6d3c3', 2, 'Find the area of a regular polygon using A = ½aP.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7da91a99f8dbf7', 'les_20249b00d6d3c3', 3, 'Find areas of polygons on the coordinate plane.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1331dcccc16146', 'les_20249b00d6d3c3', 'learn', 1, 'text', '{"body":"Every polygon area formula comes from cutting and rearranging into rectangles and triangles. Parallelogram: $A = bh$. Triangle: $A = \\frac{1}{2}bh$. Trapezoid: $A = \\frac{1}{2}(b_1 + b_2)h$. Rhombus or kite: $A = \\frac{1}{2}d_1 d_2$, because the perpendicular diagonals split it into four right triangles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35a0fe396b2756', 'les_20249b00d6d3c3', 'experiment', 2, 'activity', '{"activity":"area-volume","title":"Polygon formulas","params":{"shape":"trapezoid"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7da91a99f8dbf7', 'les_20249b00d6d3c3', 'learn', 3, 'definition', '{"term":"Regular polygon area","body":"The apothem $a$ is the perpendicular distance from the center to a side. A regular $n$-gon splits into $n$ congruent triangles of height $a$, so $A = \\frac{1}{2}aP$, where $P$ is the perimeter."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc9bbb10d7c911', 'les_20249b00d6d3c3', 'learn', 4, 'worked_example', '{"title":"Find the area of a regular hexagon with side 10.","steps":[{"latex":"P = 60","explanation":""},{"latex":"a = 5\\sqrt{3}","explanation":"Each of the 6 triangles is equilateral; the apothem is its altitude, the long leg of a 30-60-90 triangle with short leg 5."},{"latex":"A = \\tfrac{1}{2}(5\\sqrt{3})(60) = 150\\sqrt{3} \\approx 259.81","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a2ec8f5b4d79c', 'les_20249b00d6d3c3', 'learn', 5, 'worked_example', '{"title":"Find the area of the triangle with vertices $(1, 1)$, $(7, 1)$, $(4, 6)$.","steps":[{"latex":"b = 6,\\ h = 5","explanation":"The base is horizontal, so the height is the vertical distance to (4, 6)."},{"latex":"A = \\tfrac{1}{2}(6)(5) = 15","explanation":""}],"check":"For a slanted polygon, enclose it in a rectangle and subtract the corner triangles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c60b83084c1d46', 'les_20249b00d6d3c3', 'learn', 6, 'callout', '{"tone":"warning","title":"Height, not slant side","body":"For triangles, parallelograms and trapezoids, use the height perpendicular to the base. A slanted side is longer than the height."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6e3b0cd62730c', 'les_20249b00d6d3c3', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Floor plans, land parcels (often irregular polygons), solar-panel layouts and stop signs (regular octagons) all need these formulas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1331dcccc16146', 'les_20249b00d6d3c3', 1, 'practice', 'numeric', 1, 'Find the area of a kite with diagonals 12 and 9.', '{"answer":54}', '["$\\frac{1}{2}d_1 d_2$."]', '$\frac{1}{2}(12)(9) = 54$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35a0fe396b2756', 'les_20249b00d6d3c3', 2, 'practice', 'numeric', 2, 'A trapezoid has bases 7 and 13 and height 6. Find its area.', '{"answer":60}', '[]', '$\frac{1}{2}(20)(6) = 60$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7da91a99f8dbf7', 'les_20249b00d6d3c3', 3, 'practice', 'numeric', 2, 'A regular pentagon has side 8 and apothem 5.5. Find its area.', '{"answer":110}', '["$P = 40$."]', '$\frac{1}{2}(5.5)(40) = 110$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fc9bbb10d7c911', 'les_20249b00d6d3c3', 4, 'practice', 'numeric', 2, 'Find the area of the parallelogram with vertices $(0, 0)$, $(5, 0)$, $(7, 4)$, $(2, 4)$.', '{"answer":20}', '["Base 5, height 4."]', '$5 \cdot 4 = 20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a2ec8f5b4d79c', 'les_20249b00d6d3c3', 5, 'review', 'numeric', 3, 'Find the area of a regular hexagon with side 6, to the nearest tenth.', '{"answer":93.5,"tolerance":0.06}', '["Apothem $3\\sqrt{3}$, perimeter 36."]', '$\frac{1}{2}(3\sqrt{3})(36) = 54\sqrt{3} \approx 93.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c60b83084c1d46', 'les_20249b00d6d3c3', 6, 'review', 'multiple_choice', 3, 'A rhombus has side 13 and one diagonal 10. What is its area?', '{"choices":["65","120","130","60"],"answer":1}', '["Half-diagonal 5, hypotenuse 13: the other half-diagonal is 12."]', 'The diagonals are 10 and 24, so the area is $\frac{1}{2}(10)(24) = 120$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_20249b00d6d3c3', (SELECT id FROM concepts WHERE slug = 'area'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_20249b00d6d3c3', (SELECT id FROM formulas WHERE slug = 'triangle-area'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_20249b00d6d3c3', (SELECT id FROM formulas WHERE slug = 'trapezoid-area'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_20249b00d6d3c3', (SELECT id FROM formulas WHERE slug = 'special-right-triangles'), 3);

-- Lesson: asa-aas-hl-congruence
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8a23f791e992b1', 'asa-aas-hl-congruence', 'ASA, AAS and HL congruence', 'Prove triangles congruent with Angle-Side-Angle, Angle-Angle-Side and Hypotenuse-Leg, and choose the right criterion from the given information.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ff2c2f808c609', 'les_8a23f791e992b1', 1, 'State and apply the ASA and AAS criteria.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d00708398fca0e', 'les_8a23f791e992b1', 2, 'State and apply the HL criterion for right triangles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d29d4de9fbee7', 'les_8a23f791e992b1', 3, 'Choose a valid criterion, or decide none applies, from given information.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ff2c2f808c609', 'les_8a23f791e992b1', 'learn', 1, 'definition', '{"term":"ASA","body":"If two angles and the included side of one triangle are congruent to those of another, the triangles are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d00708398fca0e', 'les_8a23f791e992b1', 'learn', 2, 'definition', '{"term":"AAS","body":"If two angles and a non-included side are congruent, the triangles are congruent. It follows from ASA: if two angles match, the third angles match too (angle sum $180^\\circ$), so the side is now included between two known angles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d29d4de9fbee7', 'les_8a23f791e992b1', 'learn', 3, 'definition', '{"term":"HL (right triangles only)","body":"If the hypotenuse and one leg of a right triangle are congruent to those of another right triangle, the triangles are congruent. This is the one case where side-side-angle works, because the angle is $90^\\circ$ and the Pythagorean theorem fixes the third side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e82b02d0dbd60c', 'les_8a23f791e992b1', 'learn', 4, 'worked_example', '{"title":"Given $\\angle A \\cong \\angle D$, $\\overline{AC} \\cong \\overline{DC}$, and $C$ is where $\\overline{AE}$ and $\\overline{BD}$ cross. Prove $\\triangle ABC \\cong \\triangle DEC$.","steps":[{"latex":"1.\\ \\angle A \\cong \\angle D","explanation":"Given."},{"latex":"2.\\ \\overline{AC} \\cong \\overline{DC}","explanation":"Given."},{"latex":"3.\\ \\angle ACB \\cong \\angle DCE","explanation":"Vertical angles."},{"latex":"4.\\ \\triangle ABC \\cong \\triangle DEC","explanation":"ASA: side AC is between ∠A and ∠ACB."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b757e6ae69cf8a', 'les_8a23f791e992b1', 'learn', 5, 'worked_example', '{"title":"$\\overline{PS} \\perp \\overline{QR}$ at $S$ and $\\overline{PQ} \\cong \\overline{PR}$. Prove $\\triangle PSQ \\cong \\triangle PSR$.","steps":[{"latex":"\\angle PSQ,\\ \\angle PSR \\text{ are right angles}","explanation":"Perpendicular lines form right angles."},{"latex":"\\overline{PQ} \\cong \\overline{PR}","explanation":"Given: the hypotenuses."},{"latex":"\\overline{PS} \\cong \\overline{PS}","explanation":"Reflexive: a shared leg."},{"latex":"\\triangle PSQ \\cong \\triangle PSR","explanation":"HL."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90094b5634209d', 'les_8a23f791e992b1', 'learn', 6, 'text', '{"body":"Summary of valid criteria: SSS, SAS, ASA, AAS, and HL for right triangles. Not valid: AAA (it proves similarity, not congruence) and SSA in general."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50441eef25d10f', 'les_8a23f791e992b1', 'learn', 7, 'callout', '{"tone":"tip","title":"Mark the diagram first","body":"Before choosing a criterion, mark every given congruence, plus shared sides (reflexive), vertical angles, and right angles from perpendicular lines. Then read the pattern of S''s and A''s around each triangle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc288556aa75c7', 'les_8a23f791e992b1', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Surveyors use ASA to measure across rivers: measure a baseline and two angles on your side, build a congruent triangle on land, and measure its side instead."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ff2c2f808c609', 'les_8a23f791e992b1', 1, 'practice', 'multiple_choice', 1, 'Two angles and the side between them are congruent. Which criterion applies?', '{"choices":["SAS","ASA","AAS","HL"],"answer":1}', '[]', 'Angle-included side-angle: ASA.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d00708398fca0e', 'les_8a23f791e992b1', 2, 'practice', 'multiple_choice', 2, '$\angle A \cong \angle D$, $\angle B \cong \angle E$ and $\overline{BC} \cong \overline{EF}$. Which criterion proves $\triangle ABC \cong \triangle DEF$?', '{"choices":["ASA","AAS","SAS","Not enough information"],"answer":1}', '["Is BC between ∠A and ∠B?"]', '$\overline{BC}$ is not between $\angle A$ and $\angle B$, so it''s AAS.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d29d4de9fbee7', 'les_8a23f791e992b1', 3, 'practice', 'multiple_choice', 2, 'Two right triangles have congruent hypotenuses and one pair of congruent legs. Which criterion applies?', '{"choices":["SSS","HL","SAS","ASA"],"answer":1}', '[]', 'HL.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e82b02d0dbd60c', 'les_8a23f791e992b1', 4, 'practice', 'multiple_choice', 2, 'All three pairs of angles of two triangles are congruent. Are the triangles congruent?', '{"choices":["Yes, by AAA","Not necessarily; they are similar","Yes, by ASA","Only if they''re right triangles"],"answer":1}', '[]', 'AAA only guarantees the same shape; the triangles could be different sizes.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b757e6ae69cf8a', 'les_8a23f791e992b1', 5, 'review', 'multiple_choice', 3, 'Which extra fact would let you prove $\triangle ABC \cong \triangle DEF$ by ASA, given $\angle A \cong \angle D$ and $\angle C \cong \angle F$?', '{"choices":["$\\overline{AB} \\cong \\overline{DE}$","$\\overline{AC} \\cong \\overline{DF}$","$\\overline{BC} \\cong \\overline{EF}$","$\\angle B \\cong \\angle E$"],"answer":1}', '["ASA needs the side between the two angles."]', '$\overline{AC}$ lies between $\angle A$ and $\angle C$. (The other sides would give AAS.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4d1c853f740b75', 'subj_math', 'triangle-congruence', 'Triangle congruence', 'Criteria (SSS, SAS, ASA, AAS, HL) that guarantee two triangles are congruent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8a23f791e992b1', (SELECT id FROM concepts WHERE slug = 'triangle-congruence'));

-- Lesson: bisectors-medians-altitudes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_371712263cca32', 'bisectors-medians-altitudes', 'Bisectors, medians and altitudes', 'Use the perpendicular bisector and angle bisector theorems, and find the centroid, orthocenter, incenter and circumcenter of a triangle.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3c46af5a726ae3', 'les_371712263cca32', 1, 'Apply the Perpendicular Bisector Theorem and the Angle Bisector Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cad9a1bc8d2a52', 'les_371712263cca32', 2, 'Identify medians and altitudes and their points of concurrency.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64849396921fd6', 'les_371712263cca32', 3, 'Use the centroid''s 2 : 1 property to find segment lengths.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c46af5a726ae3', 'les_371712263cca32', 'learn', 1, 'definition', '{"term":"Perpendicular Bisector Theorem","body":"A point is on the perpendicular bisector of a segment if and only if it is equidistant from the segment''s endpoints."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cad9a1bc8d2a52', 'les_371712263cca32', 'learn', 2, 'definition', '{"term":"Angle Bisector Theorem","body":"A point is on the bisector of an angle if and only if it is equidistant from the two sides of the angle (distance measured perpendicular to each side)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64849396921fd6', 'les_371712263cca32', 'learn', 3, 'definition', '{"term":"Special segments","body":"A median joins a vertex to the midpoint of the opposite side. An altitude is the perpendicular segment from a vertex to the line containing the opposite side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0dbec967c1c72', 'les_371712263cca32', 'learn', 4, 'definition', '{"term":"Points of concurrency","body":"Perpendicular bisectors meet at the circumcenter, equidistant from the vertices (center of the circumscribed circle). Angle bisectors meet at the incenter, equidistant from the sides (center of the inscribed circle). Medians meet at the centroid. Altitudes meet at the orthocenter."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0c5230be919a3', 'les_371712263cca32', 'experiment', 5, 'activity', '{"activity":"triangle-explorer","title":"Find the four centers","params":{"show":"medians"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ce1952dc9e038', 'les_371712263cca32', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Switch between medians, altitudes, bisectors and perpendicular bisectors. Drag C to make an obtuse triangle: which centers move outside the triangle? (The centroid and incenter never do.) Then make a right triangle and watch where the circumcenter lands."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71d5b5ea708ef9', 'les_371712263cca32', 'learn', 7, 'definition', '{"term":"Centroid Theorem","body":"The centroid is two thirds of the way from each vertex to the midpoint of the opposite side. So it divides each median in the ratio $2 : 1$. In coordinates, it''s the average of the vertices: $\\left(\\frac{x_1 + x_2 + x_3}{3}, \\frac{y_1 + y_2 + y_3}{3}\\right)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ae8786e9509f8', 'les_371712263cca32', 'learn', 8, 'worked_example', '{"title":"In $\\triangle ABC$, median $\\overline{AD}$ has length 18. $G$ is the centroid. Find $AG$ and $GD$.","steps":[{"latex":"AG = \\tfrac{2}{3} \\cdot 18 = 12","explanation":""},{"latex":"GD = \\tfrac{1}{3} \\cdot 18 = 6","explanation":"AG is twice GD."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c7d168592d0d7', 'les_371712263cca32', 'learn', 9, 'worked_example', '{"title":"Find the centroid of $(0, 0)$, $(6, 0)$, $(3, 9)$","steps":[{"latex":"\\left(\\tfrac{0 + 6 + 3}{3},\\ \\tfrac{0 + 0 + 9}{3}\\right) = (3, 3)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf6d7e436b59c4', 'les_371712263cca32', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"The centroid is the balance point of a triangular plate. The circumcenter answers \"where should a new store go to be equally far from three towns?\" and the incenter gives the largest circle that fits inside a triangular plot."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c46af5a726ae3', 'les_371712263cca32', 1, 'practice', 'numeric', 1, '$P$ is on the perpendicular bisector of $\overline{AB}$, and $PA = 13$. Find $PB$.', '{"answer":13}', '[]', 'Points on the perpendicular bisector are equidistant from A and B: 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cad9a1bc8d2a52', 'les_371712263cca32', 2, 'practice', 'numeric', 2, '$G$ is the centroid of a triangle, and $GD = 7$ along median $\overline{AD}$. Find $AD$.', '{"answer":21}', '["GD is one third of the median."]', '$AD = 3 \cdot 7 = 21$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64849396921fd6', 'les_371712263cca32', 3, 'practice', 'numeric', 2, '$Q$ is on the bisector of $\angle XYZ$. Its distance to $\overrightarrow{YX}$ is $3x + 2$ and to $\overrightarrow{YZ}$ is $5x - 6$. Find $x$.', '{"answer":4}', '["Angle Bisector Theorem."]', '$3x + 2 = 5x - 6$, so $x = 4$ (distance 14).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0dbec967c1c72', 'les_371712263cca32', 4, 'practice', 'multiple_choice', 2, 'Which point is the center of the circle that passes through all three vertices of a triangle?', '{"choices":["Centroid","Incenter","Circumcenter","Orthocenter"],"answer":2}', '[]', 'The circumcenter is equidistant from the vertices.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0c5230be919a3', 'les_371712263cca32', 5, 'practice', 'multiple_choice', 2, 'Where is the orthocenter of a right triangle?', '{"choices":["At the right-angle vertex","At the midpoint of the hypotenuse","Outside the triangle","At the centroid"],"answer":0}', '["The two legs are altitudes."]', 'The legs are perpendicular, so they''re two of the altitudes, meeting at the right angle''s vertex.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ce1952dc9e038', 'les_371712263cca32', 6, 'review', 'numeric', 3, 'Find the y-coordinate of the centroid of $(-2, 5)$, $(4, -1)$, $(7, 8)$.', '{"answer":4}', '["Average the y-coordinates."]', '$\frac{5 - 1 + 8}{3} = 4$. (The centroid is $(3, 4)$.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bb97e906a29bc3', 'subj_math', 'triangle-centers', 'Triangle centers', 'Centroid, orthocenter, incenter and circumcenter: where special segments of a triangle meet.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_371712263cca32', (SELECT id FROM concepts WHERE slug = 'triangle-centers'));

-- Lesson: compass-straightedge-constructions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_271b1f1df7f5bb', 'compass-straightedge-constructions', 'Compass and straightedge constructions', 'Copy segments and angles, bisect segments and angles, and construct perpendicular and parallel lines, explaining why each construction works.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b43afefb7081bf', 'les_271b1f1df7f5bb', 1, 'Copy a segment and an angle with a compass and straightedge.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4faff9a3e21493', 'les_271b1f1df7f5bb', 2, 'Construct a perpendicular bisector and an angle bisector.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4bc596fcb7f0fc', 'les_271b1f1df7f5bb', 3, 'Construct a perpendicular through a point and a line parallel to a given line, and justify each construction.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b43afefb7081bf', 'les_271b1f1df7f5bb', 'learn', 1, 'text', '{"body":"A construction uses only two tools: a straightedge to draw lines (it has no marks, so it can''t measure) and a compass to draw circles and copy distances. Because every step is exact, each construction is really a proof: you can explain why it must work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4faff9a3e21493', 'les_271b1f1df7f5bb', 'learn', 2, 'definition', '{"term":"Copy a segment","body":"To copy $\\overline{AB}$: draw a ray from a new point $C$. Set the compass to length $AB$, place the point at $C$, and mark an arc across the ray at $D$. Then $CD = AB$ because both equal the compass opening."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4bc596fcb7f0fc', 'les_271b1f1df7f5bb', 'learn', 3, 'worked_example', '{"title":"Construct the perpendicular bisector of $\\overline{AB}$","steps":[{"latex":"\\text{1. Open the compass to more than } \\tfrac{1}{2}AB","explanation":""},{"latex":"\\text{2. Draw arcs above and below from } A \\text{ and from } B","explanation":"Keep the same opening."},{"latex":"\\text{3. Join the two intersection points } P, Q","explanation":"$\\overleftrightarrow{PQ}$ is the perpendicular bisector."}],"check":"Why: $P$ and $Q$ are each the same distance from $A$ and $B$. Points equidistant from the endpoints lie on the perpendicular bisector, so the line through them is it. It also gives the midpoint."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04f450c83f3fa5', 'les_271b1f1df7f5bb', 'learn', 4, 'worked_example', '{"title":"Bisect $\\angle ABC$","steps":[{"latex":"\\text{1. Arc from } B \\text{ crossing both rays at } D, E","explanation":""},{"latex":"\\text{2. Equal arcs from } D \\text{ and } E \\text{ meeting at } F","explanation":""},{"latex":"\\text{3. Draw } \\overrightarrow{BF}","explanation":"It bisects the angle."}],"check":"Why: $BD = BE$, $DF = EF$ and $BF = BF$, so triangles $BDF$ and $BEF$ are congruent by SSS, and the angles at $B$ are equal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16567ddb8e0536', 'les_271b1f1df7f5bb', 'learn', 5, 'definition', '{"term":"Copy an angle","body":"Draw an arc across both sides of the given angle and the same arc from the new vertex. Measure the chord between the arc''s crossing points and copy it onto the new arc. The new angle is congruent by SSS."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a98cbcf7faa77', 'les_271b1f1df7f5bb', 'learn', 6, 'definition', '{"term":"Perpendicular through a point; parallel line","body":"From point $P$, arc across the line at two points, then bisect that segment: the bisector passes through $P$ and is perpendicular. For a parallel line through $P$, draw any transversal through $P$ and copy the angle it makes with the line at $P$ (corresponding angles)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_652c0873fa2040', 'les_271b1f1df7f5bb', 'learn', 7, 'callout', '{"tone":"tip","title":"Practice digitally","body":"Free tools like GeoGebra have compass and line tools that behave exactly like the physical ones. Drag the starting points afterwards: a correct construction keeps working."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7edf12b48cdaa', 'les_271b1f1df7f5bb', 'learn', 8, 'callout', '{"tone":"note","title":"What can''t be constructed","body":"Some constructions are impossible with these tools, proved in the 1800s: trisecting an arbitrary angle, doubling a cube and squaring a circle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2808cd5e6dd902', 'les_271b1f1df7f5bb', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Before computers, drafters used these methods for every technical drawing. They still underlie geometry software, and the perpendicular bisector is how cell-tower coverage regions (Voronoi diagrams) are drawn."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b43afefb7081bf', 'les_271b1f1df7f5bb', 1, 'practice', 'multiple_choice', 1, 'Why can''t a straightedge be used to measure a length in a construction?', '{"choices":["It is too short","It has no markings","It only draws curves","It is not allowed at all"],"answer":1}', '[]', 'A straightedge is unmarked; distances are copied with the compass.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4faff9a3e21493', 'les_271b1f1df7f5bb', 2, 'practice', 'multiple_choice', 2, 'In the perpendicular bisector construction, why must the compass opening be more than half of AB?', '{"choices":["So the arcs from A and B intersect","So the line is longer","So the angle is acute","It doesn''t matter"],"answer":0}', '["What happens if the arcs are too small?"]', 'If the radius is half of AB or less, the arcs from A and B don''t meet above and below, so there are no two points to join.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4bc596fcb7f0fc', 'les_271b1f1df7f5bb', 3, 'practice', 'multiple_choice', 2, 'Which congruence criterion justifies the angle-bisector construction?', '{"choices":["SAS","SSS","ASA","AAS"],"answer":1}', '["Which three pairs of sides are equal?"]', '$BD = BE$ and $DF = EF$ by construction and $BF$ is shared, so SSS.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04f450c83f3fa5', 'les_271b1f1df7f5bb', 4, 'practice', 'multiple_choice', 2, 'A point P is equidistant from A and B. Where must P lie?', '{"choices":["On segment AB","On the perpendicular bisector of AB","On a circle centered at A","At the midpoint only"],"answer":1}', '[]', 'The set of all points equidistant from A and B is the perpendicular bisector of $\overline{AB}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16567ddb8e0536', 'les_271b1f1df7f5bb', 5, 'review', 'multiple_choice', 3, 'To construct a line through P parallel to line ℓ, which angle relationship is used?', '{"choices":["Vertical angles","Congruent corresponding angles","Supplementary angles","Complementary angles"],"answer":1}', '["Draw a transversal through P."]', 'Copying the angle so that corresponding angles are congruent guarantees the lines are parallel.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_555e6d52f71063', 'subj_math', 'constructions', 'Geometric constructions', 'Exact drawings made with only a compass and an unmarked straightedge.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_271b1f1df7f5bb', (SELECT id FROM concepts WHERE slug = 'constructions'));

-- Lesson: composite-figures-area
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3d53eb7053052e', 'composite-figures-area', 'Areas of composite figures', 'Find areas of figures made of rectangles, triangles, trapezoids and circle parts by adding and subtracting pieces, and compare areas of similar figures.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f0bc8898fe0ca', 'les_3d53eb7053052e', 1, 'Decompose a composite figure into familiar shapes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb5a369da4bb79', 'les_3d53eb7053052e', 2, 'Find areas by adding pieces or subtracting holes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5ead2f0592ba5', 'les_3d53eb7053052e', 3, 'Use area scaling (k²) for similar composite figures.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f0bc8898fe0ca', 'les_3d53eb7053052e', 'learn', 1, 'text', '{"body":"A composite figure is built from simpler shapes. Find its area by adding the pieces, or by finding a larger simple shape and subtracting the parts that are missing. Choose whichever needs fewer, easier calculations."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb5a369da4bb79', 'les_3d53eb7053052e', 'learn', 2, 'worked_example', '{"title":"An L-shaped room: a 12 ft by 10 ft rectangle with a 5 ft by 4 ft corner removed. Find the floor area.","steps":[{"latex":"12 \\cdot 10 = 120 \\text{ ft}^2","explanation":"Full rectangle."},{"latex":"120 - 5 \\cdot 4 = 100 \\text{ ft}^2","explanation":"Subtract the missing corner."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5ead2f0592ba5', 'les_3d53eb7053052e', 'learn', 3, 'worked_example', '{"title":"A running track: a rectangle 100 m by 60 m with a semicircle on each 60 m end. Find the enclosed area.","steps":[{"latex":"100 \\cdot 60 = 6000","explanation":"Rectangle."},{"latex":"\\pi(30)^2 = 900\\pi \\approx 2827.4","explanation":"Two semicircles of radius 30 make one full circle."},{"latex":"\\approx 8827.4 \\text{ m}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1872a5668d8a81', 'les_3d53eb7053052e', 'learn', 4, 'worked_example', '{"title":"A square of side 8 has a circle of radius 4 cut out. Find the remaining area.","steps":[{"latex":"64 - 16\\pi \\approx 64 - 50.27 = 13.73","explanation":""}],"check":"The circle fits exactly inside the square, touching all four sides."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_545502c8a42700', 'les_3d53eb7053052e', 'learn', 5, 'callout', '{"tone":"tip","title":"Label every dimension","body":"Missing lengths often come from subtracting: in an L-shape, the unlabeled side is a difference of two labeled ones. Write them on the diagram before computing."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ff1f63ba71179f', 'les_3d53eb7053052e', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Flooring estimates, lawn care, painting walls with windows cut out, and fabric patterns are all composite-area problems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f0bc8898fe0ca', 'les_3d53eb7053052e', 1, 'practice', 'numeric', 1, 'A figure is a 10 by 6 rectangle with a triangle of base 6 and height 4 attached to one 6-unit side. Find its area.', '{"answer":72}', '[]', '$60 + \frac{1}{2}(6)(4) = 72$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb5a369da4bb79', 'les_3d53eb7053052e', 2, 'practice', 'numeric', 2, 'A rectangular garden 20 m by 15 m has a circular pond of radius 3 m. Find the area of land, to the nearest tenth.', '{"answer":271.7,"unit":"m²","tolerance":0.06}', '[]', '$300 - 9\pi \approx 271.7$ m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5ead2f0592ba5', 'les_3d53eb7053052e', 3, 'practice', 'numeric', 2, 'A semicircle of diameter 10 sits on top of a 10 by 8 rectangle. Find the total area, to the nearest tenth.', '{"answer":119.3,"tolerance":0.06}', '["Semicircle: $\\frac{1}{2}\\pi(25)$."]', '$80 + 12.5\pi \approx 119.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1872a5668d8a81', 'les_3d53eb7053052e', 4, 'practice', 'numeric', 2, 'A square picture 30 cm on a side has a 5 cm border around it. What is the area of the border alone?', '{"answer":700,"unit":"cm²"}', '["The outer square is 40 by 40."]', '$1600 - 900 = 700$ cm².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_545502c8a42700', 'les_3d53eb7053052e', 5, 'review', 'numeric', 3, 'An annulus (ring) has outer radius 9 and inner radius 5. Find its area to the nearest tenth.', '{"answer":175.9,"tolerance":0.06}', '["$\\pi(81 - 25)$."]', '$56\pi \approx 175.9$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3d53eb7053052e', (SELECT id FROM concepts WHERE slug = 'area'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3d53eb7053052e', (SELECT id FROM formulas WHERE slug = 'circle-area'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3d53eb7053052e', (SELECT id FROM formulas WHERE slug = 'triangle-area'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3d53eb7053052e', (SELECT id FROM formulas WHERE slug = 'trapezoid-area'), 3);

-- Lesson: compositions-transformations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4c387637e1bc4b', 'compositions-transformations', 'Compositions of transformations', 'Perform a sequence of transformations, see that order can matter, and use compositions of reflections to produce translations and rotations and to define congruence.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_486bcc0d1f2836', 'les_4c387637e1bc4b', 1, 'Perform compositions of transformations and find the final image.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b03a48a231111', 'les_4c387637e1bc4b', 2, 'Decide whether the order of two transformations matters.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c7d022b0ea5884', 'les_4c387637e1bc4b', 3, 'Explain that two reflections make a translation or a rotation, and define congruence with rigid motions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_486bcc0d1f2836', 'les_4c387637e1bc4b', 'learn', 1, 'definition', '{"term":"Composition","body":"Applying one transformation and then another to the result. A glide reflection is a translation followed by a reflection across a line parallel to the translation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b03a48a231111', 'les_4c387637e1bc4b', 'learn', 2, 'worked_example', '{"title":"Reflect $P(2, 3)$ across the $y$-axis, then translate by $\\langle 0, -5 \\rangle$","steps":[{"latex":"(2, 3) \\to (-2, 3)","explanation":"Reflection first."},{"latex":"(-2, 3) \\to (-2, -2)","explanation":"Then the translation."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7d022b0ea5884', 'les_4c387637e1bc4b', 'learn', 3, 'worked_example', '{"title":"Does order matter? Reflect $(2, 3)$ across the $x$-axis and rotate $90^\\circ$ about the origin, in both orders.","steps":[{"latex":"\\text{reflect then rotate: } (2, -3) \\to (3, 2)","explanation":""},{"latex":"\\text{rotate then reflect: } (-3, 2) \\to (-3, -2)","explanation":""},{"latex":"(3, 2) \\ne (-3, -2)","explanation":"Order matters here."}],"check":"Two translations, or two rotations about the same center, can be done in either order. In general you can''t assume that."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e61ce73e094c08', 'les_4c387637e1bc4b', 'learn', 4, 'definition', '{"term":"Two reflections","body":"Reflecting across two parallel lines is a translation by twice the distance between the lines, perpendicular to them. Reflecting across two lines that meet at angle $\\theta$ is a rotation about the intersection point by $2\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ebca56d856e8a', 'les_4c387637e1bc4b', 'learn', 5, 'definition', '{"term":"Congruence by rigid motions","body":"Two figures are congruent if and only if a sequence of rigid motions maps one onto the other. This definition works for any shape, not just polygons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b816be46518ec0', 'les_4c387637e1bc4b', 'learn', 6, 'callout', '{"tone":"tip","title":"Check by tracking one point","body":"To test a claimed composition, follow a single point (and maybe a second to check orientation) through every step."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_249d30d5406195', 'les_4c387637e1bc4b', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Footprints form a glide-reflection pattern. Robot arms and animation rigs chain rotations and translations; programmers multiply transformation matrices to compose them, and the order of multiplication matters for exactly the reason shown here."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_486bcc0d1f2836', 'les_4c387637e1bc4b', 1, 'practice', 'short_text', 2, 'Translate $(1, -4)$ by $\langle 3, 2 \rangle$, then reflect across the $x$-axis. Enter as (x,y).', '{"accept":["(4,2)"]}', '["Translate: (4, −2)."]', '$(4, -2) \to (4, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b03a48a231111', 'les_4c387637e1bc4b', 2, 'practice', 'short_text', 2, 'Rotate $(5, 0)$ by $90^\circ$ about the origin, then reflect across $y = x$. Enter as (x,y).', '{"accept":["(5,0)"]}', '["Rotate: (0, 5).","Swap coordinates."]', '$(0, 5) \to (5, 0)$. This composition happens to fix this point.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c7d022b0ea5884', 'les_4c387637e1bc4b', 3, 'practice', 'multiple_choice', 2, 'Reflecting across $x = 1$ and then across $x = 4$ is the same as…', '{"choices":["a translation 3 units right","a translation 6 units right","a rotation of 180°","a reflection across x = 5"],"answer":1}', '["Twice the distance between the lines."]', 'The lines are 3 apart, so the result is a translation of 6 units, in the direction from the first line to the second (right).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e61ce73e094c08', 'les_4c387637e1bc4b', 4, 'practice', 'multiple_choice', 2, 'Two lines meet at a $40^\circ$ angle. Reflecting across one then the other is…', '{"choices":["a rotation of 40°","a rotation of 80°","a translation","a reflection"],"answer":1}', '[]', 'A rotation of $2 \cdot 40^\circ = 80^\circ$ about the intersection point.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4ebca56d856e8a', 'les_4c387637e1bc4b', 5, 'review', 'multiple_choice', 3, 'Which sequence maps $\triangle ABC$ with $A(1, 1)$, $B(3, 1)$, $C(1, 2)$ onto $A''(-1, -1)$, $B''(-3, -1)$, $C''(-1, -2)$?', '{"choices":["Translate ⟨−2, −2⟩","Rotate 180° about the origin","Reflect across the y-axis","Reflect across y = x"],"answer":1}', '["Every coordinate changed sign."]', '$(x, y) \to (-x, -y)$ is a $180^\circ$ rotation (also a reflection across the y-axis followed by one across the x-axis).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2d2b216d5cb495', 'subj_math', 'rigid-motions', 'Rigid motions', 'Transformations that preserve distance and angle measure: translations, reflections and rotations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4c387637e1bc4b', (SELECT id FROM concepts WHERE slug = 'rigid-motions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b7599fc065b0a0', 'subj_math', 'congruence', 'Congruence', 'Figures are congruent if a sequence of rigid motions maps one onto the other.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4c387637e1bc4b', (SELECT id FROM concepts WHERE slug = 'congruence'));

-- Lesson: conditional-probability
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_deec14dde2464d', 'conditional-probability', 'Conditional probability', 'Compute P(B | A) from tables, tree diagrams and the formula, test independence with conditional probabilities, and recognize the difference between P(A | B) and P(B | A).', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e968d2de42156', 'les_deec14dde2464d', 1, 'Compute conditional probabilities from two-way tables and with P(B | A) = P(A and B) / P(A).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52fc6c94cede08', 'les_deec14dde2464d', 2, 'Use tree diagrams for multi-stage experiments.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4e07ca67c6692', 'les_deec14dde2464d', 3, 'Test independence by checking whether P(B | A) = P(B), and avoid confusing P(A | B) with P(B | A).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e968d2de42156', 'les_deec14dde2464d', 'learn', 1, 'definition', '{"term":"Conditional probability","body":"$P(B \\mid A) = \\dfrac{P(A \\text{ and } B)}{P(A)}$, for $P(A) > 0$. It''s the probability of $B$ when you restrict attention to outcomes where $A$ happened."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52fc6c94cede08', 'les_deec14dde2464d', 'learn', 2, 'worked_example', '{"title":"Of 200 students, 120 play a sport; 54 of the athletes and 26 of the non-athletes prefer morning classes. Find $P(\\text{morning} \\mid \\text{athlete})$ and $P(\\text{athlete} \\mid \\text{morning})$.","steps":[{"latex":"P(\\text{morning} \\mid \\text{athlete}) = \\tfrac{54}{120} = 0.45","explanation":"Restrict to the 120 athletes."},{"latex":"P(\\text{athlete} \\mid \\text{morning}) = \\tfrac{54}{80} = 0.675","explanation":"Restrict to the 80 morning-preferrers."}],"check":"Different denominators, different answers: the order in P(A | B) matters."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4e07ca67c6692', 'les_deec14dde2464d', 'learn', 3, 'text', '{"body":"$A$ and $B$ are independent exactly when $P(B \\mid A) = P(B)$: knowing $A$ happened doesn''t change the chances of $B$. Here $P(\\text{morning}) = \\frac{80}{200} = 0.40 \\ne 0.45$, so preferring mornings and playing a sport are not independent in this sample."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5dfc925231381', 'les_deec14dde2464d', 'learn', 4, 'worked_example', '{"title":"A disease affects 1% of people. A test is 95% accurate for people who have it and 90% accurate for people who don''t. If someone tests positive, what''s the probability they have the disease?","steps":[{"latex":"P(\\text{pos and disease}) = 0.01 \\cdot 0.95 = 0.0095","explanation":"Tree: branch for ''has disease''."},{"latex":"P(\\text{pos and healthy}) = 0.99 \\cdot 0.10 = 0.099","explanation":"False positives."},{"latex":"P(\\text{disease} \\mid \\text{pos}) = \\tfrac{0.0095}{0.0095 + 0.099} \\approx 0.088","explanation":"Under 9%!"}],"check":"Because the disease is rare, most positives are false positives. This is why doctors confirm with a second test."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e8c48f94089899', 'les_deec14dde2464d', 'learn', 5, 'callout', '{"tone":"warning","title":"The confusion of the inverse","body":"$P(\\text{positive} \\mid \\text{disease}) = 0.95$ is not $P(\\text{disease} \\mid \\text{positive})$, which here is about 0.088. Mixing them up is one of the most common errors in medicine, law and the news."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68da57307e96c3', 'les_deec14dde2464d', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spam filters, medical diagnosis, insurance pricing and weather forecasts (\"chance of rain given these clouds\") are all conditional probabilities."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e968d2de42156', 'les_deec14dde2464d', 1, 'practice', 'numeric', 1, '$P(A) = 0.5$ and $P(A \text{ and } B) = 0.2$. Find $P(B \mid A)$.', '{"answer":0.4}', '[]', '$0.2 / 0.5 = 0.4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52fc6c94cede08', 'les_deec14dde2464d', 2, 'practice', 'numeric', 2, 'Two dice are rolled. Given that the sum is 8, what is the probability that one die shows 3? Enter a fraction or decimal.', '{"answer":0.4}', '["Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2)."]', '(3,5) and (5,3): $\frac{2}{5} = 0.4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4e07ca67c6692', 'les_deec14dde2464d', 3, 'practice', 'numeric', 2, 'In a class, 60% study Spanish, 30% study French, and 12% study both. What is P(French | Spanish)?', '{"answer":0.2}', '["$0.12 / 0.60$."]', '$0.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c5dfc925231381', 'les_deec14dde2464d', 4, 'practice', 'multiple_choice', 2, '$P(B) = 0.3$ and $P(B \mid A) = 0.3$. What can you conclude?', '{"choices":["A and B are mutually exclusive","A and B are independent","A causes B","P(A) = 0.3"],"answer":1}', '[]', 'Knowing A doesn''t change B''s probability: independent.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e8c48f94089899', 'les_deec14dde2464d', 5, 'review', 'numeric', 3, 'A factory has machines X (60% of output, 2% defective) and Y (40% of output, 5% defective). A random item is defective. What is the probability it came from Y? Round to three decimals.', '{"answer":0.625,"tolerance":0.0006}', '["$P(\\text{def}) = 0.012 + 0.020$."]', '$\frac{0.020}{0.032} = 0.625$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_deec14dde2464d', 'subj_math', 'conditional-probability', 'Conditional probability', 'The probability of an event given that another event has occurred.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_deec14dde2464d', (SELECT id FROM concepts WHERE slug = 'conditional-probability'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6f058999688b1f', 'subj_math', 'independence', 'Independent events', 'Events where one occurring does not change the probability of the other.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_deec14dde2464d', (SELECT id FROM concepts WHERE slug = 'independence'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_deec14dde2464d', (SELECT id FROM formulas WHERE slug = 'probability-rules'), 1);

-- Lesson: conditional-statements
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7ce824de760b3a', 'conditional-statements', 'Conditional statements', 'Write conditionals in if-then form, form the converse, inverse and contrapositive, determine truth values, and write biconditionals and good definitions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7526eb6380b96e', 'les_7ce824de760b3a', 1, 'Identify the hypothesis and conclusion of a conditional statement and rewrite statements in if-then form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ca4967d61d329c', 'les_7ce824de760b3a', 2, 'Write the converse, inverse and contrapositive and decide whether each is true.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ce4aadb16e0d09', 'les_7ce824de760b3a', 3, 'Write a biconditional and recognize when a definition is reversible.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7526eb6380b96e', 'les_7ce824de760b3a', 'learn', 1, 'definition', '{"term":"Conditional","body":"An if-then statement $p \\rightarrow q$: \"If $p$, then $q$.\" $p$ is the hypothesis and $q$ the conclusion. It is false only when $p$ is true and $q$ is false."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca4967d61d329c', 'les_7ce824de760b3a', 'learn', 2, 'definition', '{"term":"Related conditionals","body":"Converse $q \\rightarrow p$ (switch). Inverse $\\sim p \\rightarrow \\sim q$ (negate both). Contrapositive $\\sim q \\rightarrow \\sim p$ (switch and negate). A conditional and its contrapositive always have the same truth value, and so do the converse and the inverse."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce4aadb16e0d09', 'les_7ce824de760b3a', 'learn', 3, 'worked_example', '{"title":"\"If an angle measures $30^\\circ$, then it is acute.\"","steps":[{"latex":"\\text{Converse: if an angle is acute, it measures } 30^\\circ","explanation":"False: a $50^\\circ$ angle is acute."},{"latex":"\\text{Inverse: if an angle doesn''t measure } 30^\\circ\\text{, it isn''t acute}","explanation":"False: same counterexample."},{"latex":"\\text{Contrapositive: if an angle isn''t acute, it doesn''t measure } 30^\\circ","explanation":"True, like the original."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27e8f18674bcf9', 'les_7ce824de760b3a', 'learn', 4, 'text', '{"body":"Rewrite everyday statements in if-then form before analyzing them. \"All squares are rectangles\" becomes \"If a figure is a square, then it is a rectangle.\" \"Vertical angles are congruent\" becomes \"If two angles are vertical, then they are congruent.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87d4c63d405640', 'les_7ce824de760b3a', 'learn', 5, 'definition', '{"term":"Biconditional","body":"When a conditional and its converse are both true, combine them with \"if and only if\": $p \\leftrightarrow q$. Every good definition is a true biconditional: \"An angle is right if and only if it measures $90^\\circ$.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc85a3a71e0454', 'les_7ce824de760b3a', 'learn', 6, 'callout', '{"tone":"warning","title":"A true statement can have a false converse","body":"\"If you live in Dallas, you live in Texas\" is true. Its converse, \"If you live in Texas, you live in Dallas,\" is false. Never assume a converse is true without checking."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f86a5d5e1ae3df', 'les_7ce824de760b3a', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Programming is built on if-then logic. Contracts and rules (\"If you return the item within 30 days, then you get a refund\") are conditionals, and arguing about the converse is a common source of disputes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7526eb6380b96e', 'les_7ce824de760b3a', 1, 'practice', 'multiple_choice', 1, 'What is the hypothesis of "If $x = 4$, then $x^2 = 16$"?', '{"choices":["$x^2 = 16$","$x = 4$","$x = \\pm 4$","If"],"answer":1}', '[]', 'The hypothesis follows "if": $x = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ca4967d61d329c', 'les_7ce824de760b3a', 2, 'practice', 'multiple_choice', 2, 'What is the converse of "If $x = 4$, then $x^2 = 16$," and is it true?', '{"choices":["If $x^2 = 16$, then $x = 4$; false","If $x^2 = 16$, then $x = 4$; true","If $x \\ne 4$, then $x^2 \\ne 16$; false","If $x^2 \\ne 16$, then $x \\ne 4$; true"],"answer":0}', '["Switch hypothesis and conclusion.","Try x = −4."]', '$x = -4$ also gives 16, so the converse is false.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ce4aadb16e0d09', 'les_7ce824de760b3a', 3, 'practice', 'multiple_choice', 2, 'Which statement always has the same truth value as a conditional?', '{"choices":["Its converse","Its inverse","Its contrapositive","Its negation"],"answer":2}', '[]', 'A conditional and its contrapositive are logically equivalent.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_27e8f18674bcf9', 'les_7ce824de760b3a', 4, 'practice', 'multiple_choice', 2, 'Write "Supplementary angles sum to 180°" in if-then form.', '{"choices":["If angles sum to 180°, they are supplementary","If two angles are supplementary, their measures sum to 180°","If angles are 90°, they are supplementary","Angles are supplementary if and only if they are adjacent"],"answer":1}', '["The subject becomes the hypothesis."]', '"If two angles are supplementary, then their measures sum to 180°."');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87d4c63d405640', 'les_7ce824de760b3a', 5, 'review', 'multiple_choice', 3, 'Which is a valid biconditional?', '{"choices":["An angle is acute if and only if it measures 45°","A number is even if and only if it is divisible by 2","A figure is a square if and only if it has four sides","x² = 9 if and only if x = 3"],"answer":1}', '["Check that both directions are true."]', 'Divisible by 2 is exactly the definition of even, so both directions hold.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2a9eb6c24ca3b7', 'subj_math', 'conditionals', 'Conditional statements', 'If-then statements and their converse, inverse and contrapositive.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7ce824de760b3a', (SELECT id FROM concepts WHERE slug = 'conditionals'));

-- Lesson: coordinate-proofs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8a88d8ac95a4ee', 'coordinate-proofs', 'Coordinate proofs', 'Place figures on the coordinate plane with general coordinates and prove properties with the slope, distance and midpoint formulas.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_21aaae519392e6', 'les_8a88d8ac95a4ee', 1, 'Place a figure conveniently on the coordinate plane using variables for coordinates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a18e96a0776cb5', 'les_8a88d8ac95a4ee', 2, 'Use slope, distance and midpoint formulas to prove properties of triangles and quadrilaterals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8fcef9f3694333', 'les_8a88d8ac95a4ee', 3, 'Explain why a proof with variable coordinates covers every case.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21aaae519392e6', 'les_8a88d8ac95a4ee', 'learn', 1, 'text', '{"body":"A coordinate proof translates geometry into algebra. Using letters like $(a, 0)$ and $(b, c)$ instead of specific numbers makes the result hold for every figure of that type, not just one example."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a18e96a0776cb5', 'les_8a88d8ac95a4ee', 'learn', 2, 'definition', '{"term":"Placing figures","body":"Use the origin and the axes to reduce the number of variables: put a vertex at $(0, 0)$ and a side along the $x$-axis. Use coordinates like $2a$ when you''ll need midpoints, to avoid fractions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fcef9f3694333', 'les_8a88d8ac95a4ee', 'learn', 3, 'worked_example', '{"title":"Prove: the midpoint of the hypotenuse of a right triangle is equidistant from all three vertices","steps":[{"latex":"O(0, 0),\\ A(2a, 0),\\ B(0, 2b)","explanation":"Right angle at the origin, legs on the axes."},{"latex":"M = (a, b)","explanation":"Midpoint of the hypotenuse AB."},{"latex":"MO = \\sqrt{a^2 + b^2},\\ MA = \\sqrt{(2a - a)^2 + b^2} = \\sqrt{a^2 + b^2}","explanation":""},{"latex":"MB = \\sqrt{a^2 + (b - 2b)^2} = \\sqrt{a^2 + b^2}","explanation":"All three are equal. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3f8c7f8d614bc', 'les_8a88d8ac95a4ee', 'learn', 4, 'worked_example', '{"title":"Prove: the diagonals of a parallelogram bisect each other","steps":[{"latex":"O(0, 0),\\ A(2a, 0),\\ B(2a + 2b, 2c),\\ C(2b, 2c)","explanation":"A general parallelogram: OA and CB are horizontal and equal."},{"latex":"\\text{midpoint of } \\overline{OB} = (a + b, c)","explanation":""},{"latex":"\\text{midpoint of } \\overline{AC} = (a + b, c)","explanation":"Same point, so the diagonals bisect each other. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f087731b0d35b0', 'les_8a88d8ac95a4ee', 'learn', 5, 'worked_example', '{"title":"Prove: the segment joining midpoints of two sides of a triangle is parallel to the third side and half as long","steps":[{"latex":"A(0, 0),\\ B(2a, 0),\\ C(2b, 2c)","explanation":""},{"latex":"M = (b, c),\\ N = (a + b, c)","explanation":"Midpoints of AC and BC."},{"latex":"m_{MN} = 0 = m_{AB},\\ MN = a = \\tfrac{1}{2}AB","explanation":"Parallel (both horizontal) and half the length. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa3c9fd3558e8c', 'les_8a88d8ac95a4ee', 'learn', 6, 'callout', '{"tone":"warning","title":"Don''t assume extra properties","body":"If the theorem is about any parallelogram, your coordinates must describe a general one. Using a rectangle or square would prove a weaker result."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8148c261d9c7ae', 'les_8a88d8ac95a4ee', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Computer graphics, CAD and robotics do geometry entirely in coordinates. Analytic geometry, Descartes''s idea of merging algebra with geometry, underpins calculus."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21aaae519392e6', 'les_8a88d8ac95a4ee', 1, 'practice', 'multiple_choice', 1, 'Which is the most convenient placement for a general rectangle?', '{"choices":["$(0, 0), (a, 0), (a, b), (0, b)$","$(1, 2), (5, 2), (5, 7), (1, 7)$","$(0, 0), (a, 0), (b, c), (0, c)$","$(a, b), (c, d), (e, f), (g, h)$"],"answer":0}', '[]', 'One vertex at the origin, sides on the axes, only two variables.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a18e96a0776cb5', 'les_8a88d8ac95a4ee', 2, 'practice', 'multiple_choice', 2, 'To prove a quadrilateral is a parallelogram with coordinates, which is sufficient?', '{"choices":["Show one pair of sides are equal","Show both pairs of opposite sides have equal slopes","Show the diagonals are equal","Show one angle is 90°"],"answer":1}', '[]', 'Equal slopes for both pairs of opposite sides means both pairs are parallel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fcef9f3694333', 'les_8a88d8ac95a4ee', 3, 'practice', 'multiple_choice', 2, 'Why use $2a$ and $2b$ instead of $a$ and $b$ as coordinates?', '{"choices":["It makes the figure bigger","Midpoints come out without fractions","It''s required","It makes slopes zero"],"answer":1}', '[]', 'Midpoints are averages, so even coordinates keep them free of fractions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3f8c7f8d614bc', 'les_8a88d8ac95a4ee', 4, 'review', 'multiple_choice', 3, 'With $A(0, 0)$, $B(2a, 0)$, $C(a, b)$, what kind of triangle is $ABC$ for all $a, b > 0$?', '{"choices":["Equilateral","Isosceles","Right","Scalene"],"answer":1}', '["Compare $AC$ and $BC$."]', '$AC = BC = \sqrt{a^2 + b^2}$: always isosceles.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_64eaafaca65525', 'subj_math', 'coordinate-geometry', 'Coordinate geometry', 'Studying geometric figures with coordinates and algebra.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8a88d8ac95a4ee', (SELECT id FROM concepts WHERE slug = 'coordinate-geometry'));
