-- Lesson: cpctc
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_63ebc1ee56eea0', 'cpctc', 'Using congruent triangles (CPCTC)', 'Prove that segments or angles are congruent by first proving triangles congruent, including proofs with overlapping triangles and two-step proofs.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e442ac0988e01', 'les_63ebc1ee56eea0', 1, 'Use CPCTC to conclude that corresponding parts are congruent after proving triangles congruent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b8cf7adb731bc8', 'les_63ebc1ee56eea0', 2, 'Separate overlapping triangles to identify shared parts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fdce8b8987b175', 'les_63ebc1ee56eea0', 3, 'Write proofs that use congruent triangles to establish parallel lines, midpoints or bisectors.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e442ac0988e01', 'les_63ebc1ee56eea0', 'learn', 1, 'definition', '{"term":"CPCTC","body":"Corresponding Parts of Congruent Triangles are Congruent. Once you''ve proved two triangles congruent, every pair of corresponding sides and angles is congruent. It''s the main reason to prove triangles congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b8cf7adb731bc8', 'les_63ebc1ee56eea0', 'learn', 2, 'text', '{"body":"The strategy for proving two segments or angles congruent: find two triangles that contain them as corresponding parts, prove those triangles congruent with SSS, SAS, ASA, AAS or HL, then finish with CPCTC."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fdce8b8987b175', 'les_63ebc1ee56eea0', 'learn', 3, 'worked_example', '{"title":"Given $\\overline{AB} \\parallel \\overline{DC}$ and $\\overline{AB} \\cong \\overline{DC}$ in quadrilateral $ABCD$ with diagonal $\\overline{AC}$. Prove $\\overline{AD} \\cong \\overline{CB}$.","steps":[{"latex":"1.\\ \\overline{AB} \\cong \\overline{DC}","explanation":"Given."},{"latex":"2.\\ \\angle BAC \\cong \\angle DCA","explanation":"Alternate interior angles (AB ∥ DC, transversal AC)."},{"latex":"3.\\ \\overline{AC} \\cong \\overline{CA}","explanation":"Reflexive property."},{"latex":"4.\\ \\triangle BAC \\cong \\triangle DCA","explanation":"SAS."},{"latex":"5.\\ \\overline{CB} \\cong \\overline{AD}","explanation":"CPCTC."}],"check":"This proves a useful fact: if one pair of opposite sides of a quadrilateral is both parallel and congruent, the other pair is congruent too."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32176574eadaef', 'les_63ebc1ee56eea0', 'learn', 4, 'worked_example', '{"title":"Overlapping triangles: $\\overline{AD} \\cong \\overline{BC}$ and $\\overline{AC} \\cong \\overline{BD}$, with $A, B$ on the bottom and $C, D$ above. Prove $\\angle C \\cong \\angle D$.","steps":[{"latex":"\\triangle ABC \\text{ and } \\triangle BAD \\text{ share } \\overline{AB}","explanation":"Redraw the two triangles separately."},{"latex":"\\overline{BC} \\cong \\overline{AD},\\ \\overline{AC} \\cong \\overline{BD},\\ \\overline{AB} \\cong \\overline{BA}","explanation":"Given, given, reflexive."},{"latex":"\\triangle ABC \\cong \\triangle BAD \\Rightarrow \\angle C \\cong \\angle D","explanation":"SSS, then CPCTC."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cee5d7ac1e3472', 'les_63ebc1ee56eea0', 'learn', 5, 'callout', '{"tone":"warning","title":"Prove congruence first","body":"You can''t use CPCTC until the triangles are proved congruent. And the parts must correspond: check the order in your congruence statement."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ca9d85f0ab922d', 'les_63ebc1ee56eea0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers confirm two braces are the same length by showing they belong to congruent triangles. The same reasoning proves most properties of parallelograms, kites and rhombuses in the next unit."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e442ac0988e01', 'les_63ebc1ee56eea0', 1, 'practice', 'multiple_choice', 1, 'What does CPCTC let you conclude?', '{"choices":["That two triangles are congruent","That corresponding parts of congruent triangles are congruent","That angles sum to 180°","That triangles are similar"],"answer":1}', '[]', 'It''s used after congruence is established.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b8cf7adb731bc8', 'les_63ebc1ee56eea0', 2, 'practice', 'multiple_choice', 2, '$\triangle JKL \cong \triangle MNP$. Which must be true by CPCTC?', '{"choices":["$\\overline{JL} \\cong \\overline{MP}$","$\\overline{JK} \\cong \\overline{NP}$","$\\angle K \\cong \\angle P$","$\\angle J \\cong \\angle N$"],"answer":0}', '["Match positions."]', '$J \to M$ and $L \to P$, so $\overline{JL} \cong \overline{MP}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fdce8b8987b175', 'les_63ebc1ee56eea0', 3, 'practice', 'numeric', 2, '$\triangle ABC \cong \triangle DEF$, $AB = 2x + 1$ and $DE = 3x - 6$. Find $AB$.', '{"answer":15}', '["Corresponding sides are equal."]', '$x = 7$, so $AB = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32176574eadaef', 'les_63ebc1ee56eea0', 4, 'practice', 'numeric', 2, '$\triangle PQR \cong \triangle STU$, $m\angle R = (5y - 8)^\circ$ and $m\angle U = (3y + 20)^\circ$. Find $m\angle R$.', '{"answer":62,"unit":"°"}', '[]', '$y = 14$, so $m\angle R = 62^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cee5d7ac1e3472', 'les_63ebc1ee56eea0', 5, 'review', 'multiple_choice', 3, 'To prove that $M$ is the midpoint of $\overline{AB}$ using triangles, what must you show with CPCTC?', '{"choices":["$\\overline{AM} \\cong \\overline{MB}$","$\\angle A \\cong \\angle B$","$\\overline{AB} \\perp$ some line","The triangles are right triangles"],"answer":0}', '[]', 'A midpoint splits the segment into congruent parts, so show $\overline{AM} \cong \overline{MB}$ as corresponding parts.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4d1c853f740b75', 'subj_math', 'triangle-congruence', 'Triangle congruence', 'Criteria (SSS, SAS, ASA, AAS, HL) that guarantee two triangles are congruent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_63ebc1ee56eea0', (SELECT id FROM concepts WHERE slug = 'triangle-congruence'));

-- Lesson: cross-sections-revolution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bb910c2bddcb42', 'cross-sections-revolution', 'Cross sections and solids of revolution', 'Identify the cross sections formed when a plane slices a solid, and the solid formed by rotating a plane figure around a line.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96706a2ce3f381', 'les_bb910c2bddcb42', 1, 'Identify cross sections of prisms, pyramids, cylinders, cones and spheres.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a26d2555fcbf76', 'les_bb910c2bddcb42', 2, 'Identify the solid produced by rotating a two-dimensional figure about an axis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b7c66ca28d0a3c', 'les_bb910c2bddcb42', 3, 'Find the dimensions and volume of a solid of revolution.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96706a2ce3f381', 'les_bb910c2bddcb42', 'learn', 1, 'definition', '{"term":"Cross section","body":"The intersection of a solid and a plane. Slicing a loaf of bread gives cross sections."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a26d2555fcbf76', 'les_bb910c2bddcb42', 'learn', 2, 'text', '{"body":"Common results: slicing a cylinder parallel to its base gives a circle, and perpendicular to the base (through the axis) gives a rectangle. A cone sliced parallel to the base gives a circle; through the apex perpendicular to the base gives a triangle; at a tilt, an ellipse. Every plane section of a sphere is a circle. A cube can give a square, a rectangle, a triangle, or even a regular hexagon if sliced through the midpoints of six edges."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7c66ca28d0a3c', 'les_bb910c2bddcb42', 'learn', 3, 'definition', '{"term":"Solid of revolution","body":"The solid swept out when a plane figure rotates $360^\\circ$ about a line (the axis). A rectangle rotated about one side makes a cylinder; a right triangle rotated about a leg makes a cone; a semicircle rotated about its diameter makes a sphere."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6dbefb548a085e', 'les_bb910c2bddcb42', 'learn', 4, 'worked_example', '{"title":"A right triangle with legs 3 and 4 rotates about the leg of length 4. Describe the solid and find its volume.","steps":[{"latex":"\\text{cone with } r = 3,\\ h = 4","explanation":"The other leg sweeps out the base radius."},{"latex":"V = \\tfrac{1}{3}\\pi(9)(4) = 12\\pi \\approx 37.70","explanation":""}],"check":"Rotating about the leg of length 3 instead gives a cone with $r = 4$, $h = 3$ and volume $16\\pi$, a different solid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a94d53f6a24fb0', 'les_bb910c2bddcb42', 'learn', 5, 'callout', '{"tone":"tip","title":"Visualize with real objects","body":"Cut a potato or clay shape, or spin a paper triangle taped to a pencil. Seeing the cross section once makes these questions much easier."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee7b1adf2dd3c6', 'les_bb910c2bddcb42', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"CT and MRI scans are stacks of cross sections. Pottery wheels and lathes make solids of revolution, and engineers use cross-section areas to compute beam strength and pipe flow."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96706a2ce3f381', 'les_bb910c2bddcb42', 1, 'practice', 'multiple_choice', 1, 'What is the cross section of a sphere cut by any plane through it?', '{"choices":["Square","Circle","Ellipse","Triangle"],"answer":1}', '[]', 'Always a circle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a26d2555fcbf76', 'les_bb910c2bddcb42', 2, 'practice', 'multiple_choice', 2, 'A square pyramid is sliced by a plane parallel to its base. What is the cross section?', '{"choices":["Triangle","Square","Rectangle that isn''t a square","Trapezoid"],"answer":1}', '[]', 'A smaller square, similar to the base.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b7c66ca28d0a3c', 'les_bb910c2bddcb42', 3, 'practice', 'multiple_choice', 2, 'A rectangle 5 by 2 rotates around its side of length 5. What solid forms?', '{"choices":["Cylinder with r = 5, h = 2","Cylinder with r = 2, h = 5","Cone","Sphere"],"answer":1}', '[]', 'The side of length 5 is the axis (height); the side of length 2 sweeps the radius.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6dbefb548a085e', 'les_bb910c2bddcb42', 4, 'practice', 'numeric', 2, 'Find the volume of the solid in the previous question, to the nearest tenth.', '{"answer":62.8,"tolerance":0.06}', '["$\\pi r^2 h = \\pi(4)(5)$."]', '$20\pi \approx 62.8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a94d53f6a24fb0', 'les_bb910c2bddcb42', 5, 'review', 'multiple_choice', 3, 'Which cross section of a cube is NOT possible?', '{"choices":["Equilateral triangle","Regular hexagon","Rectangle","Circle"],"answer":3}', '["Every slice of a cube has straight edges."]', 'A plane meets the cube''s flat faces in segments, so the cross section is a polygon; it can''t be a circle.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_43a5429f4cdd3f', 'subj_math', 'cross-sections', 'Cross sections', 'The two-dimensional shape formed where a plane intersects a solid.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bb910c2bddcb42', (SELECT id FROM concepts WHERE slug = 'cross-sections'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bb910c2bddcb42', (SELECT id FROM formulas WHERE slug = 'pyramid-cone-sphere'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bb910c2bddcb42', (SELECT id FROM formulas WHERE slug = 'prism-cylinder-volume'), 2);

-- Lesson: dilations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dcf984ec3cfe18', 'dilations', 'Dilations and scale factor', 'Dilate figures about the origin or another center, find scale factors, and describe how dilations affect lengths, angles, perimeter and area.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a97bb84461400b', 'les_dcf984ec3cfe18', 1, 'Define a dilation by its center and scale factor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6528a1ae5c75a3', 'les_dcf984ec3cfe18', 2, 'Dilate figures using (x, y) → (kx, ky) and about centers other than the origin.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_561fc6bc1f7934', 'les_dcf984ec3cfe18', 3, 'Describe the effect of a dilation on lengths, angles, perimeter and area.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a97bb84461400b', 'les_dcf984ec3cfe18', 'learn', 1, 'definition', '{"term":"Dilation","body":"A dilation with center $O$ and scale factor $k > 0$ maps each point $P$ to $P''$ on ray $\\overrightarrow{OP}$ with $OP'' = k \\cdot OP$. If $k > 1$ it''s an enlargement; if $0 < k < 1$ it''s a reduction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6528a1ae5c75a3', 'les_dcf984ec3cfe18', 'learn', 2, 'text', '{"body":"With center at the origin, the rule is $(x, y) \\to (kx, ky)$. A dilation is not a rigid motion: lengths are multiplied by $k$. But angles are preserved, and each segment''s image is parallel to it (or on the same line). The image is similar to the preimage."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_561fc6bc1f7934', 'les_dcf984ec3cfe18', 'experiment', 3, 'activity', '{"activity":"transformations","title":"Dilate from the origin","params":{"kind":"dilate"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87bf9cb4c92d05', 'les_dcf984ec3cfe18', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Set $k = 2$ and compare the readout A′B′ ÷ AB with $k$. The dashed rays from O pass through each vertex and its image. Try $k = 0.5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d2e0126ca6cfc', 'les_dcf984ec3cfe18', 'learn', 5, 'worked_example', '{"title":"Dilate $A(4, -2)$ about $C(1, 1)$ with $k = 3$","steps":[{"latex":"A - C = (3, -3)","explanation":"Vector from the center to the point."},{"latex":"3(3, -3) = (9, -9)","explanation":"Scale it."},{"latex":"A'' = C + (9, -9) = (10, -8)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d330fa448f3ab', 'les_dcf984ec3cfe18', 'learn', 6, 'worked_example', '{"title":"A triangle with perimeter 18 cm and area 12 cm² is dilated by $k = \\tfrac{5}{2}$. Find the image''s perimeter and area.","steps":[{"latex":"P'' = \\tfrac{5}{2} \\cdot 18 = 45 \\text{ cm}","explanation":"Lengths scale by k."},{"latex":"A'' = \\left(\\tfrac{5}{2}\\right)^2 \\cdot 12 = 75 \\text{ cm}^2","explanation":"Areas scale by k²."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e8eb80df77a51f', 'les_dcf984ec3cfe18', 'learn', 7, 'callout', '{"tone":"warning","title":"Area scales by k²","body":"Doubling a figure''s dimensions quadruples its area (and, for solids, multiplies volume by 8). Don''t multiply area by $k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb3a08e7042750', 'les_dcf984ec3cfe18', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Zooming in on a photo, projecting a slide, enlarging a blueprint and printing a map at a different scale are all dilations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a97bb84461400b', 'les_dcf984ec3cfe18', 1, 'practice', 'short_text', 1, 'Dilate $(6, -4)$ about the origin with $k = \tfrac{1}{2}$. Enter as (x,y).', '{"accept":["(3,-2)"]}', '[]', '$(3, -2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6528a1ae5c75a3', 'les_dcf984ec3cfe18', 2, 'practice', 'numeric', 2, '$P(2, 5)$ maps to $P''(8, 20)$ under a dilation centered at the origin. Find $k$.', '{"answer":4}', '[]', '$8 \div 2 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_561fc6bc1f7934', 'les_dcf984ec3cfe18', 3, 'practice', 'short_text', 2, 'Dilate $(5, 7)$ about $(1, 3)$ with $k = 2$. Enter as (x,y).', '{"accept":["(9,11)"]}', '["The vector from the center is (4, 4)."]', '$(1, 3) + 2(4, 4) = (9, 11)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87bf9cb4c92d05', 'les_dcf984ec3cfe18', 4, 'practice', 'numeric', 2, 'A rectangle with area 20 m² is dilated by scale factor 3. What is the image''s area, in m²?', '{"answer":180,"unit":"m²"}', '[]', '$3^2 \cdot 20 = 180$ m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d2e0126ca6cfc', 'les_dcf984ec3cfe18', 5, 'practice', 'multiple_choice', 2, 'Which is preserved by every dilation?', '{"choices":["Side lengths","Angle measures","Area","Perimeter"],"answer":1}', '[]', 'Angles are preserved; lengths, perimeter and area change unless $k = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d330fa448f3ab', 'les_dcf984ec3cfe18', 6, 'review', 'numeric', 3, 'A segment of length 12 is dilated to length 8. What is the scale factor? Enter a fraction or decimal.', '{"answer":0.6666666666666666,"tolerance":0.001}', '[]', '$8 \div 12 = \frac{2}{3}$, a reduction.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_dcf984ec3cfe18', 'subj_math', 'dilations', 'Dilations', 'Transformations that enlarge or reduce a figure by a scale factor from a center.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dcf984ec3cfe18', (SELECT id FROM concepts WHERE slug = 'dilations'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dcf984ec3cfe18', (SELECT id FROM concepts WHERE slug = 'scale-factor'));

-- Lesson: equations-of-circles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3c872d7e0d4b85', 'equations-of-circles', 'Equations of circles', 'Derive the equation of a circle from the distance formula, write equations from a center and radius, and find the center and radius by completing the square.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35f857941d7063', 'les_3c872d7e0d4b85', 1, 'Derive (x − h)² + (y − k)² = r² from the distance formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_513fd621d988ac', 'les_3c872d7e0d4b85', 2, 'Write the equation of a circle from its center and radius or from a center and a point.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ac1eceb1f26df', 'les_3c872d7e0d4b85', 3, 'Find the center and radius from general form by completing the square, and decide whether a point lies on a circle.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35f857941d7063', 'les_3c872d7e0d4b85', 'learn', 1, 'text', '{"body":"A point $(x, y)$ is on the circle with center $(h, k)$ and radius $r$ exactly when its distance from the center is $r$: $\\sqrt{(x - h)^2 + (y - k)^2} = r$. Squaring both sides gives the standard equation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_513fd621d988ac', 'les_3c872d7e0d4b85', 'learn', 2, 'formula', '{"latex":"(x - h)^2 + (y - k)^2 = r^2","title":"Circle in center-radius form"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ac1eceb1f26df', 'les_3c872d7e0d4b85', 'learn', 3, 'worked_example', '{"title":"Write the circle with center $(-3, 2)$ through $(1, 5)$","steps":[{"latex":"r = \\sqrt{(1 + 3)^2 + (5 - 2)^2} = 5","explanation":"The radius is the distance from the center to the point."},{"latex":"(x + 3)^2 + (y - 2)^2 = 25","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24fe5abcb13d23', 'les_3c872d7e0d4b85', 'learn', 4, 'worked_example', '{"title":"Find the center and radius of $x^2 + y^2 - 6x + 10y + 9 = 0$","steps":[{"latex":"(x^2 - 6x + 9) + (y^2 + 10y + 25) = -9 + 9 + 25","explanation":"Complete the square in x and in y; add the same amounts to both sides."},{"latex":"(x - 3)^2 + (y + 5)^2 = 25","explanation":""},{"latex":"\\text{center } (3, -5),\\ r = 5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a843b35cbe7450', 'les_3c872d7e0d4b85', 'learn', 5, 'callout', '{"tone":"warning","title":"Signs and the radius","body":"$(x + 3)^2$ means $h = -3$. And the right side is $r^2$: $(x - 1)^2 + y^2 = 49$ has radius 7, not 49."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f35afeb3c909f1', 'les_3c872d7e0d4b85', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"GPS locates you by intersecting circles (spheres in 3D) of known radius around satellites. Phone towers'' coverage areas and earthquake epicenters are found the same way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35f857941d7063', 'les_3c872d7e0d4b85', 1, 'practice', 'short_text', 1, 'Write the equation of the circle with center $(0, 0)$ and radius 6.', '{"accept":["x^2+y^2=36"]}', '[]', '$x^2 + y^2 = 36$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_513fd621d988ac', 'les_3c872d7e0d4b85', 2, 'practice', 'short_text', 2, 'Write the equation of the circle with center $(4, -1)$ and radius 3.', '{"accept":["(x-4)^2+(y+1)^2=9"]}', '[]', '$(x - 4)^2 + (y + 1)^2 = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ac1eceb1f26df', 'les_3c872d7e0d4b85', 3, 'practice', 'short_text', 2, 'Find the center of $(x + 7)^2 + (y - 2)^2 = 10$. Enter as (h,k).', '{"accept":["(-7,2)"]}', '[]', '$(-7, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24fe5abcb13d23', 'les_3c872d7e0d4b85', 4, 'practice', 'numeric', 2, 'Find the radius of $x^2 + y^2 + 4x - 2y - 20 = 0$.', '{"answer":5}', '["$(x + 2)^2 + (y - 1)^2 = 20 + 4 + 1$."]', '$r^2 = 25$, so $r = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a843b35cbe7450', 'les_3c872d7e0d4b85', 5, 'review', 'multiple_choice', 3, 'Is $(5, 3)$ on the circle $(x - 1)^2 + (y + 0)^2 = 25$?', '{"choices":["Yes","No, it''s inside","No, it''s outside","Can''t tell"],"answer":0}', '["Substitute the point."]', '$(4)^2 + 3^2 = 25$, so yes.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_42608bf90da416', 'subj_math', 'circle-equations', 'Equations of circles', 'Center-radius form (x − h)² + (y − k)² = r².');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3c872d7e0d4b85', (SELECT id FROM concepts WHERE slug = 'circle-equations'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3c872d7e0d4b85', (SELECT id FROM concepts WHERE slug = 'completing-the-square'));
