-- Lesson: geometric-mean-right-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0108652c560b58', 'geometric-mean-right-triangles', 'Geometric mean in right triangles', 'Show that the altitude to the hypotenuse forms three similar triangles, and use the geometric mean relationships to find lengths.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_304b985444cdee', 'les_0108652c560b58', 1, 'Prove that the altitude to the hypotenuse creates two triangles similar to the original and to each other.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_19c63ec0fbfb62', 'les_0108652c560b58', 2, 'Find the geometric mean of two numbers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ffc2962cc4ef2', 'les_0108652c560b58', 3, 'Apply the altitude and leg geometric-mean relationships, and derive the Pythagorean theorem from them.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_304b985444cdee', 'les_0108652c560b58', 'learn', 1, 'definition', '{"term":"Geometric mean","body":"The geometric mean of positive numbers $a$ and $b$ is the positive $x$ with $\\frac{a}{x} = \\frac{x}{b}$, so $x = \\sqrt{ab}$. The geometric mean of 4 and 9 is 6."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19c63ec0fbfb62', 'les_0108652c560b58', 'learn', 2, 'text', '{"body":"In right $\\triangle ABC$ with right angle $C$, draw altitude $\\overline{CD}$ to the hypotenuse. Each smaller triangle shares an acute angle with $\\triangle ABC$ and has a right angle, so by AA all three triangles are similar: $\\triangle ACB \\sim \\triangle ADC \\sim \\triangle CDB$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ffc2962cc4ef2', 'les_0108652c560b58', 'learn', 3, 'definition', '{"term":"Geometric mean theorems","body":"Let the altitude split the hypotenuse into $AD = m$ and $DB = n$, with $c = m + n$. Altitude: $CD = \\sqrt{mn}$. Legs: $AC = \\sqrt{m \\cdot c}$ and $BC = \\sqrt{n \\cdot c}$ (each leg is the geometric mean of the hypotenuse and the adjacent segment)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f0a2714ddc40e', 'les_0108652c560b58', 'learn', 4, 'worked_example', '{"title":"The altitude to the hypotenuse splits it into 4 and 9. Find the altitude and both legs.","steps":[{"latex":"h = \\sqrt{4 \\cdot 9} = 6","explanation":""},{"latex":"a = \\sqrt{4 \\cdot 13} = 2\\sqrt{13} \\approx 7.21,\\ b = \\sqrt{9 \\cdot 13} = 3\\sqrt{13} \\approx 10.82","explanation":""}],"check":"Check: $(2\\sqrt{13})^2 + (3\\sqrt{13})^2 = 52 + 117 = 169 = 13^2$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42f30348253113', 'les_0108652c560b58', 'learn', 5, 'text', '{"body":"These relationships prove the Pythagorean theorem: $a^2 = nc$ and $b^2 = mc$, so $a^2 + b^2 = (m + n)c = c^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_38eeb7b96ab94e', 'les_0108652c560b58', 'learn', 6, 'callout', '{"tone":"tip","title":"Draw the three triangles separately","body":"Redraw the two small triangles and the large one in the same orientation, with right angles matching. The proportions are then easy to read off."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_88e790d997d20b', 'les_0108652c560b58', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Geometric means appear in average growth rates (the geometric mean of yearly growth factors), in camera f-stops and in the classic construction of $\\sqrt{n}$ with a semicircle."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_304b985444cdee', 'les_0108652c560b58', 1, 'practice', 'numeric', 1, 'Find the geometric mean of 3 and 27.', '{"answer":9}', '[]', '$\sqrt{81} = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19c63ec0fbfb62', 'les_0108652c560b58', 2, 'practice', 'numeric', 2, 'The altitude to the hypotenuse divides it into segments 2 and 8. Find the altitude.', '{"answer":4}', '[]', '$\sqrt{16} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ffc2962cc4ef2', 'les_0108652c560b58', 3, 'practice', 'numeric', 2, 'The hypotenuse is 25 and the altitude divides it into 9 and 16. Find the leg adjacent to the segment of length 9.', '{"answer":15}', '["$\\sqrt{9 \\cdot 25}$."]', '$15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f0a2714ddc40e', 'les_0108652c560b58', 4, 'review', 'numeric', 3, 'The altitude to the hypotenuse is 12 and one segment of the hypotenuse is 9. Find the other segment.', '{"answer":16}', '["$12^2 = 9x$."]', '$x = 16$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3941da996c7bba', 'subj_math', 'similarity', 'Similarity', 'Figures with the same shape: corresponding angles congruent and corresponding sides proportional.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0108652c560b58', (SELECT id FROM concepts WHERE slug = 'similarity'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_06026986dacc30', 'subj_math', 'geometric-mean', 'Geometric mean', 'For positive a and b, the number x with a/x = x/b, so x = √(ab).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0108652c560b58', (SELECT id FROM concepts WHERE slug = 'geometric-mean'));

-- Lesson: geometric-probability
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1494f864d28f85', 'geometric-probability', 'Geometric probability', 'Find probabilities as ratios of lengths, areas or times when outcomes are spread uniformly over a region.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_44a7e733131842', 'les_1494f864d28f85', 1, 'Compute probability as a ratio of lengths on a segment.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0f3932ea1660f2', 'les_1494f864d28f85', 2, 'Compute probability as a ratio of areas in a region.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_156509121ac936', 'les_1494f864d28f85', 3, 'Model waiting-time problems with lengths.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44a7e733131842', 'les_1494f864d28f85', 'learn', 1, 'definition', '{"term":"Geometric probability","body":"If a point is chosen uniformly at random in a region, the probability it lands in a sub-region is $\\frac{\\text{measure of the sub-region}}{\\text{measure of the whole region}}$, where \"measure\" is length, area or volume."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f3932ea1660f2', 'les_1494f864d28f85', 'learn', 2, 'worked_example', '{"title":"A point is chosen at random on $\\overline{AD}$ from 0 to 12. What is the probability it lies between 3 and 7?","steps":[{"latex":"\\tfrac{7 - 3}{12 - 0} = \\tfrac{4}{12} = \\tfrac{1}{3}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_156509121ac936', 'les_1494f864d28f85', 'learn', 3, 'worked_example', '{"title":"A dart hits a 20 cm by 20 cm board at a random point. The bullseye is a circle of radius 3 cm. Find P(bullseye).","steps":[{"latex":"\\tfrac{\\pi(3)^2}{20^2} = \\tfrac{9\\pi}{400} \\approx 0.0707","explanation":"About 7%."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bc9f86e8a4ee2', 'les_1494f864d28f85', 'learn', 4, 'worked_example', '{"title":"A bus comes every 15 minutes. You arrive at a random time. What is the probability you wait less than 4 minutes?","steps":[{"latex":"\\tfrac{4}{15} \\approx 0.267","explanation":"Waiting time is uniform on the 15-minute interval."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_01dd304744e260', 'les_1494f864d28f85', 'learn', 5, 'callout', '{"tone":"warning","title":"Uniformity is an assumption","body":"These ratios only work if every point is equally likely. A real dart player aims at the center, so a beginner''s darts are closer to uniform than an expert''s."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f28fbe344757bd', 'les_1494f864d28f85', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Estimating π by throwing random points (Monte Carlo methods), the chance a meteor hits land (about 29% of Earth''s surface), and traffic-light waiting times use geometric probability."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44a7e733131842', 'les_1494f864d28f85', 1, 'practice', 'numeric', 1, 'A point is chosen on a segment from 0 to 20. What is P(it is greater than 15)?', '{"answer":0.25}', '[]', '$5 / 20 = 0.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f3932ea1660f2', 'les_1494f864d28f85', 2, 'practice', 'numeric', 2, 'A circle of radius 2 is inside a square of side 8. A random point in the square is chosen. What is P(inside the circle), to three decimals?', '{"answer":0.196,"tolerance":0.0006}', '["$4\\pi / 64$."]', '$\frac{\pi}{16} \approx 0.196$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_156509121ac936', 'les_1494f864d28f85', 3, 'practice', 'numeric', 2, 'A traffic light is green 40 s, yellow 5 s and red 30 s per cycle. What is P(arriving on green)? Round to three decimals.', '{"answer":0.533,"tolerance":0.0006}', '["$40 / 75$."]', '$0.533$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8bc9f86e8a4ee2', 'les_1494f864d28f85', 4, 'review', 'numeric', 3, 'A point is chosen in a circle of radius 10. What is P(it is within 5 of the center)?', '{"answer":0.25}', '["$\\frac{\\pi \\cdot 25}{\\pi \\cdot 100}$."]', '$0.25$: half the radius gives a quarter of the area.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1494f864d28f85', 'subj_math', 'geometric-probability', 'Geometric probability', 'Probability measured as a ratio of lengths, areas or volumes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1494f864d28f85', (SELECT id FROM concepts WHERE slug = 'geometric-probability'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a88397b662aed6', 'subj_math', 'probability', 'Probability', 'A number from 0 to 1 measuring how likely an event is.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1494f864d28f85', (SELECT id FROM concepts WHERE slug = 'probability'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1494f864d28f85', (SELECT id FROM formulas WHERE slug = 'circle-area'), 1);

-- Lesson: independent-dependent-events
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9fa5ba3fc828b8', 'independent-dependent-events', 'Independent and dependent events', 'Find probabilities of compound ''and'' events, distinguish independent from dependent events, and solve ''at least one'' problems with complements.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_62246692eb772f', 'les_9fa5ba3fc828b8', 1, 'Decide whether two events are independent or dependent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5f4afa7d6b225a', 'les_9fa5ba3fc828b8', 2, 'Use P(A and B) = P(A) · P(B) for independent events and P(A) · P(B | A) for dependent events.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f24029653f5bd1', 'les_9fa5ba3fc828b8', 3, 'Compute ''at least one'' probabilities using the complement.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62246692eb772f', 'les_9fa5ba3fc828b8', 'learn', 1, 'definition', '{"term":"Independent events","body":"Events $A$ and $B$ are independent if knowing that one happened doesn''t change the probability of the other. Then $P(A \\text{ and } B) = P(A) \\cdot P(B)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f4afa7d6b225a', 'les_9fa5ba3fc828b8', 'learn', 2, 'definition', '{"term":"Dependent events","body":"If one event affects the other, use $P(A \\text{ and } B) = P(A) \\cdot P(B \\mid A)$, where $P(B \\mid A)$ is the probability of $B$ given that $A$ happened. Drawing without replacement makes events dependent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f24029653f5bd1', 'les_9fa5ba3fc828b8', 'learn', 3, 'worked_example', '{"title":"A bag has 5 red and 3 blue marbles. Draw two. Find P(both red) with and without replacement.","steps":[{"latex":"\\text{with: } \\tfrac{5}{8} \\cdot \\tfrac{5}{8} = \\tfrac{25}{64} \\approx 0.391","explanation":"Independent: the bag is restored."},{"latex":"\\text{without: } \\tfrac{5}{8} \\cdot \\tfrac{4}{7} = \\tfrac{20}{56} = \\tfrac{5}{14} \\approx 0.357","explanation":"Dependent: one red is gone."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cafb68266825a9', 'les_9fa5ba3fc828b8', 'learn', 4, 'text', '{"body":"\"At least one\" problems are easiest with the complement. The opposite of \"at least one success\" is \"no successes,\" which is usually a single product."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_626d56fc2b1f97', 'les_9fa5ba3fc828b8', 'learn', 5, 'worked_example', '{"title":"A free throw goes in 70% of the time, independently. What is P(at least one make in 3 shots)?","steps":[{"latex":"P(\\text{all miss}) = 0.3^3 = 0.027","explanation":""},{"latex":"P(\\text{at least one}) = 1 - 0.027 = 0.973","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5c3e5798c4419', 'les_9fa5ba3fc828b8', 'learn', 6, 'callout', '{"tone":"warning","title":"Independent is not the same as mutually exclusive","body":"Mutually exclusive events can''t happen together, so $P(A \\text{ and } B) = 0$. If both have positive probability, they''re dependent: knowing one happened tells you the other didn''t."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7631ca5df6db78', 'les_9fa5ba3fc828b8', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Reliability engineering (a system with backups fails only if all parts fail), medical testing, and card games all depend on whether events are independent."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62246692eb772f', 'les_9fa5ba3fc828b8', 1, 'practice', 'numeric', 1, 'A coin is flipped and a die is rolled. What is P(heads and a 6)? Enter a fraction or decimal.', '{"answer":0.08333333333333333,"tolerance":0.001}', '[]', '$\frac{1}{2} \cdot \frac{1}{6} = \frac{1}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f4afa7d6b225a', 'les_9fa5ba3fc828b8', 2, 'practice', 'numeric', 2, 'Two cards are drawn without replacement. What is P(both aces)? Enter a fraction or decimal.', '{"answer":0.004524886877828055,"tolerance":0.0001}', '["$\\frac{4}{52} \\cdot \\frac{3}{51}$."]', '$\frac{12}{2652} = \frac{1}{221} \approx 0.0045$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f24029653f5bd1', 'les_9fa5ba3fc828b8', 3, 'practice', 'multiple_choice', 2, 'Which pair of events is independent?', '{"choices":["Drawing two cards without replacement","Rolling a die twice","Picking two students for different roles from one class","Pulling two socks from a drawer without returning the first"],"answer":1}', '[]', 'Die rolls don''t affect each other.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cafb68266825a9', 'les_9fa5ba3fc828b8', 4, 'practice', 'numeric', 2, 'A machine part fails with probability 0.1. Two independent backup parts are installed (3 total). What is the probability all three fail?', '{"answer":0.001}', '[]', '$0.1^3 = 0.001$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_626d56fc2b1f97', 'les_9fa5ba3fc828b8', 5, 'review', 'numeric', 3, 'Each day there''s a 20% chance of rain, independently. What is the probability of at least one rainy day in a 5-day week? Round to three decimals.', '{"answer":0.672,"tolerance":0.0006}', '["$1 - 0.8^5$."]', '$1 - 0.32768 \approx 0.672$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a88397b662aed6', 'subj_math', 'probability', 'Probability', 'A number from 0 to 1 measuring how likely an event is.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9fa5ba3fc828b8', (SELECT id FROM concepts WHERE slug = 'probability'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6f058999688b1f', 'subj_math', 'independence', 'Independent events', 'Events where one occurring does not change the probability of the other.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9fa5ba3fc828b8', (SELECT id FROM concepts WHERE slug = 'independence'));
