-- Lesson: indirect-proof
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2b784e8bacacde', 'indirect-proof', 'Indirect proof', 'Prove statements by contradiction: assume the opposite, reason to an impossibility, and conclude the original statement is true.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_16ae504d439759', 'les_2b784e8bacacde', 1, 'Describe the steps of an indirect proof (proof by contradiction).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96b3f4f0f593fe', 'les_2b784e8bacacde', 2, 'Write the correct temporary assumption, the negation of the conclusion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_11e675511c56cc', 'les_2b784e8bacacde', 3, 'Write indirect proofs in algebra and geometry.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16ae504d439759', 'les_2b784e8bacacde', 'learn', 1, 'definition', '{"term":"Indirect proof","body":"1. Assume temporarily that the conclusion is false. 2. Reason logically from that assumption until you reach a contradiction with a given fact, a definition, or a known theorem. 3. Conclude that the assumption was false, so the original statement is true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96b3f4f0f593fe', 'les_2b784e8bacacde', 'learn', 2, 'text', '{"body":"Indirect proof is useful when the conclusion is a \"not,\" a \"no,\" or an \"at most\" statement, where it''s hard to argue directly. It works because a statement and its negation can''t both be true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_11e675511c56cc', 'les_2b784e8bacacde', 'learn', 3, 'worked_example', '{"title":"Prove: a triangle has at most one obtuse angle","steps":[{"latex":"\\text{Assume } \\triangle ABC \\text{ has two obtuse angles, } \\angle A, \\angle B","explanation":"Negate the conclusion."},{"latex":"m\\angle A + m\\angle B > 90^\\circ + 90^\\circ = 180^\\circ","explanation":""},{"latex":"m\\angle A + m\\angle B + m\\angle C > 180^\\circ","explanation":"Since m∠C > 0."},{"latex":"\\text{Contradicts the Triangle Angle Sum Theorem}","explanation":"So the assumption is false: at most one obtuse angle."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f5bf02e5301702', 'les_2b784e8bacacde', 'learn', 4, 'worked_example', '{"title":"Prove: if $x^2$ is even, then $x$ is even (for integers $x$)","steps":[{"latex":"\\text{Assume } x \\text{ is odd: } x = 2k + 1","explanation":""},{"latex":"x^2 = 4k^2 + 4k + 1 = 2(2k^2 + 2k) + 1","explanation":"That''s odd."},{"latex":"\\text{Contradicts } x^2 \\text{ even}","explanation":"So x is even."}],"check":"This fact is the key step in the classic proof that $\\sqrt{2}$ is irrational, also an indirect proof."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6655d78b1efc25', 'les_2b784e8bacacde', 'learn', 5, 'callout', '{"tone":"warning","title":"Negate carefully","body":"The negation of \"at most one\" is \"two or more.\" The negation of \"$\\overline{AB} \\parallel \\overline{CD}$\" is \"$\\overline{AB}$ is not parallel to $\\overline{CD}$\" (they intersect). A wrong negation makes the whole proof invalid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e277b78bac398', 'les_2b784e8bacacde', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Detectives and doctors reason this way (\"if it were X, we''d see Y, but we don''t, so it isn''t X\"). Computer scientists prove some problems are unsolvable by contradiction."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16ae504d439759', 'les_2b784e8bacacde', 1, 'practice', 'multiple_choice', 1, 'What is the first step of an indirect proof of "∠A is acute"?', '{"choices":["Assume ∠A is acute","Assume ∠A is not acute","Assume ∠A is 90°","Measure ∠A"],"answer":1}', '[]', 'Assume the negation of the conclusion: ∠A is not acute (it''s right or obtuse).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96b3f4f0f593fe', 'les_2b784e8bacacde', 2, 'practice', 'multiple_choice', 2, 'What is the negation of "There are at most two solutions"?', '{"choices":["There are at least two solutions","There are no solutions","There are three or more solutions","There are exactly two solutions"],"answer":2}', '[]', '"At most two" is false exactly when there are three or more.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_11e675511c56cc', 'les_2b784e8bacacde', 3, 'practice', 'multiple_choice', 2, 'In an indirect proof that lines ℓ and m are parallel, what do you assume?', '{"choices":["ℓ and m are parallel","ℓ and m intersect","ℓ and m are perpendicular","ℓ = m"],"answer":1}', '[]', 'In a plane, distinct lines that aren''t parallel intersect.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f5bf02e5301702', 'les_2b784e8bacacde', 4, 'review', 'multiple_choice', 3, 'An indirect proof assumes $x \le 3$ and reaches $5 < 2$. What''s the conclusion?', '{"choices":["$x \\le 3$","$x > 3$","$5 < 2$","Nothing"],"answer":1}', '[]', 'The assumption led to a contradiction, so it''s false: $x > 3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2b784e8bacacde', 'subj_math', 'indirect-proof', 'Indirect proof', 'Proving a statement by showing its negation leads to a contradiction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2b784e8bacacde', (SELECT id FROM concepts WHERE slug = 'indirect-proof'));

-- Lesson: inductive-deductive-reasoning
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8d93d84db2e50b', 'inductive-deductive-reasoning', 'Inductive and deductive reasoning', 'Make conjectures from patterns, test them with counterexamples, and reach certain conclusions with deductive laws (detachment and syllogism).', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d7d4fec618f823', 'les_8d93d84db2e50b', 1, 'Use inductive reasoning to make a conjecture from a pattern.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2668a029118a04', 'les_8d93d84db2e50b', 2, 'Disprove a conjecture with a counterexample.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69722d495a3ddd', 'les_8d93d84db2e50b', 3, 'Apply the Law of Detachment and the Law of Syllogism to draw valid conclusions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7d4fec618f823', 'les_8d93d84db2e50b', 'learn', 1, 'definition', '{"term":"Inductive reasoning","body":"Reasoning from observed patterns to a general conjecture. It suggests what is probably true but can''t guarantee it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2668a029118a04', 'les_8d93d84db2e50b', 'learn', 2, 'worked_example', '{"title":"Make a conjecture: $1 = 1$, $1 + 3 = 4$, $1 + 3 + 5 = 9$, $1 + 3 + 5 + 7 = 16$","steps":[{"latex":"1, 4, 9, 16 \\text{ are perfect squares}","explanation":""},{"latex":"\\text{Conjecture: the sum of the first } n \\text{ odd numbers is } n^2","explanation":"This one is true, but the pattern alone doesn''t prove it."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69722d495a3ddd', 'les_8d93d84db2e50b', 'learn', 3, 'definition', '{"term":"Counterexample","body":"A single case where the hypothesis is true but the conclusion is false. One counterexample proves a conjecture false."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4631bedfafeec', 'les_8d93d84db2e50b', 'learn', 4, 'worked_example', '{"title":"Conjecture: \"The sum of two numbers is always greater than either number.\"","steps":[{"latex":"-3 + 2 = -1","explanation":"−1 is less than 2."},{"latex":"\\text{False}","explanation":"The conjecture fails for negative numbers."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_933119ae48d31e', 'les_8d93d84db2e50b', 'learn', 5, 'definition', '{"term":"Deductive reasoning","body":"Reasoning from facts, definitions, properties and accepted rules to a conclusion that must be true if the starting statements are true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b71f45cc2f35fc', 'les_8d93d84db2e50b', 'learn', 6, 'definition', '{"term":"Law of Detachment","body":"If $p \\rightarrow q$ is true and $p$ is true, then $q$ is true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e0d786eedff3a', 'les_8d93d84db2e50b', 'learn', 7, 'definition', '{"term":"Law of Syllogism","body":"If $p \\rightarrow q$ and $q \\rightarrow r$ are true, then $p \\rightarrow r$ is true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d53edcaf53a46d', 'les_8d93d84db2e50b', 'learn', 8, 'worked_example', '{"title":"Draw conclusions","steps":[{"latex":"\\text{If an angle is right, it measures } 90^\\circ.\\ \\angle A \\text{ is right.}","explanation":"Detachment: m∠A = 90°."},{"latex":"\\text{If } x > 5 \\text{ then } x > 3.\\ \\text{If } x > 3 \\text{ then } x > 0.","explanation":"Syllogism: if x > 5, then x > 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_447a04fa8fcc3b', 'les_8d93d84db2e50b', 'learn', 9, 'callout', '{"tone":"warning","title":"Affirming the conclusion is invalid","body":"\"If it rains, the grass is wet. The grass is wet.\" doesn''t let you conclude it rained; a sprinkler might be on. Detachment works only when the hypothesis is known to be true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cfe35c2718d508', 'les_8d93d84db2e50b', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scientists use induction to form hypotheses and deduction to test their consequences. Lawyers, programmers debugging code and doctors making diagnoses all switch between the two."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d7d4fec618f823', 'les_8d93d84db2e50b', 1, 'practice', 'numeric', 1, 'Find the next term by inductive reasoning: 3, 7, 11, 15, …', '{"answer":19}', '["Add 4 each time."]', '$15 + 4 = 19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2668a029118a04', 'les_8d93d84db2e50b', 2, 'practice', 'numeric', 2, 'Find the next term: 2, 6, 18, 54, …', '{"answer":162}', '["Multiply by 3."]', '$54 \cdot 3 = 162$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69722d495a3ddd', 'les_8d93d84db2e50b', 3, 'practice', 'multiple_choice', 2, 'Which is a counterexample to "Every prime number is odd"?', '{"choices":["3","9","2","15"],"answer":2}', '["Look for an even prime."]', '2 is prime and even.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4631bedfafeec', 'les_8d93d84db2e50b', 4, 'practice', 'multiple_choice', 2, 'Given: "If a polygon is a triangle, its angles sum to 180°." Polygon P is a triangle. What follows?', '{"choices":["P has 3 sides only if it''s equilateral","P''s angles sum to 180°","P is a square","Nothing can be concluded"],"answer":1}', '["Law of Detachment."]', 'The hypothesis is true for P, so the conclusion holds.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_933119ae48d31e', 'les_8d93d84db2e50b', 5, 'practice', 'multiple_choice', 2, 'Given "If I study, I pass" and "If I pass, I graduate." Which follows by the Law of Syllogism?', '{"choices":["If I graduate, I studied","If I study, I graduate","If I pass, I studied","If I don''t study, I don''t graduate"],"answer":1}', '[]', 'Chain the statements: $p \rightarrow q$ and $q \rightarrow r$ give $p \rightarrow r$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b71f45cc2f35fc', 'les_8d93d84db2e50b', 6, 'review', 'multiple_choice', 3, '"If a figure is a square, it has four sides. Figure F has four sides." What can you conclude?', '{"choices":["F is a square","F is not a square","Nothing certain about F being a square","F is a rectangle"],"answer":2}', '["Is this detachment, or affirming the conclusion?"]', 'Many figures have four sides, so F might not be a square. The argument is invalid.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3a4419c2afed0d', 'subj_math', 'logical-reasoning', 'Logical reasoning', 'Inductive reasoning from patterns and deductive reasoning from accepted statements.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8d93d84db2e50b', (SELECT id FROM concepts WHERE slug = 'logical-reasoning'));

-- Lesson: inscribed-angles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_98756a49c327b5', 'inscribed-angles', 'Inscribed angles', 'Use the Inscribed Angle Theorem and its corollaries: angles on the same arc are congruent, an angle in a semicircle is right, and opposite angles of a cyclic quadrilateral are supplementary.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7dba69450c7083', 'les_98756a49c327b5', 1, 'State and use the Inscribed Angle Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6c6420383dfd90', 'les_98756a49c327b5', 2, 'Apply its corollaries about angles intercepting the same arc and angles in a semicircle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6415d5086f7b32', 'les_98756a49c327b5', 3, 'Use the fact that opposite angles of an inscribed quadrilateral are supplementary.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7dba69450c7083', 'les_98756a49c327b5', 'learn', 1, 'definition', '{"term":"Inscribed angle","body":"An angle whose vertex is on the circle and whose sides are chords. The arc inside the angle is its intercepted arc."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c6420383dfd90', 'les_98756a49c327b5', 'learn', 2, 'definition', '{"term":"Inscribed Angle Theorem","body":"An inscribed angle measures half of its intercepted arc: $m\\angle APB = \\frac{1}{2} m\\overset{\\frown}{AB}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6415d5086f7b32', 'les_98756a49c327b5', 'experiment', 3, 'activity', '{"activity":"circle-angles","title":"Move the vertex around the circle","params":{"arc":120,"p":250,"r":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a52819e148735f', 'les_98756a49c327b5', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Slide P anywhere on the major arc: the inscribed angle stays exactly half the central angle. Now set the arc to $180^\\circ$. What is every inscribed angle?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6322b78d64c1f', 'les_98756a49c327b5', 'learn', 5, 'definition', '{"term":"Corollaries","body":"Inscribed angles that intercept the same arc are congruent. An angle inscribed in a semicircle is a right angle. If a quadrilateral is inscribed in a circle, its opposite angles are supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f7d803f6c2659', 'les_98756a49c327b5', 'learn', 6, 'worked_example', '{"title":"An inscribed angle intercepts an arc of $96^\\circ$. Find the angle. Then find the arc intercepted by a $35^\\circ$ inscribed angle.","steps":[{"latex":"\\tfrac{1}{2} \\cdot 96^\\circ = 48^\\circ","explanation":""},{"latex":"2 \\cdot 35^\\circ = 70^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_638b0ef385a643', 'les_98756a49c327b5', 'learn', 7, 'worked_example', '{"title":"Quadrilateral $ABCD$ is inscribed in a circle, $m\\angle A = (2x + 10)^\\circ$ and $m\\angle C = (3x)^\\circ$. Find $m\\angle A$.","steps":[{"latex":"2x + 10 + 3x = 180","explanation":"Opposite angles are supplementary."},{"latex":"x = 34 \\Rightarrow m\\angle A = 78^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30acf6bd91985a', 'les_98756a49c327b5', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"A photographer standing anywhere on a circular arc through two points sees them at the same angle, which is why theater seating and camera placement use circles. Carpenters find a circle''s center by inscribing a right angle (the semicircle corollary)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7dba69450c7083', 'les_98756a49c327b5', 1, 'practice', 'numeric', 1, 'An inscribed angle intercepts a $140^\circ$ arc. Find the angle.', '{"answer":70,"unit":"°"}', '[]', '$70^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c6420383dfd90', 'les_98756a49c327b5', 2, 'practice', 'numeric', 1, 'An inscribed angle measures $28^\circ$. Find its intercepted arc.', '{"answer":56,"unit":"°"}', '[]', '$56^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6415d5086f7b32', 'les_98756a49c327b5', 3, 'practice', 'numeric', 2, '$\triangle ABC$ is inscribed in a circle with $\overline{AB}$ a diameter and $m\angle A = 33^\circ$. Find $m\angle B$.', '{"answer":57,"unit":"°"}', '["Angle C is inscribed in a semicircle."]', '$\angle C = 90^\circ$, so $m\angle B = 90 - 33 = 57^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a52819e148735f', 'les_98756a49c327b5', 4, 'practice', 'numeric', 2, 'A quadrilateral inscribed in a circle has $m\angle B = 104^\circ$. Find $m\angle D$.', '{"answer":76,"unit":"°"}', '[]', '$180 - 104 = 76^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6322b78d64c1f', 'les_98756a49c327b5', 5, 'review', 'multiple_choice', 3, 'Two inscribed angles intercept the same arc. One is $(5x - 4)^\circ$ and the other is $(3x + 16)^\circ$. What is each angle?', '{"choices":["10°","46°","92°","36°"],"answer":1}', '["They are congruent."]', '$x = 10$, so each is $46^\circ$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_021a201c0027d2', 'subj_math', 'circles', 'Circles', 'Sets of points at a fixed distance from a center; arcs, chords and angles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_98756a49c327b5', (SELECT id FROM concepts WHERE slug = 'circles'));

-- Lesson: isosceles-equilateral-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d31ec09e8b1572', 'isosceles-equilateral-triangles', 'Isosceles and equilateral triangles', 'Use the Isosceles Triangle Theorem and its converse, and the equilateral-equiangular corollaries, to find unknown sides and angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e2ea21837196f', 'les_d31ec09e8b1572', 1, 'Name the legs, base, vertex angle and base angles of an isosceles triangle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e24294eb931c06', 'les_d31ec09e8b1572', 2, 'Apply the Isosceles Triangle Theorem and its converse.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0d647500d63e1', 'les_d31ec09e8b1572', 3, 'Use the fact that a triangle is equilateral if and only if it is equiangular.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e2ea21837196f', 'les_d31ec09e8b1572', 'learn', 1, 'definition', '{"term":"Parts of an isosceles triangle","body":"The two congruent sides are the legs; the third side is the base. The angle between the legs is the vertex angle, and the two angles at the base are the base angles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e24294eb931c06', 'les_d31ec09e8b1572', 'learn', 2, 'definition', '{"term":"Isosceles Triangle Theorem and converse","body":"If two sides of a triangle are congruent, the angles opposite them are congruent. Conversely, if two angles are congruent, the sides opposite them are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0d647500d63e1', 'les_d31ec09e8b1572', 'learn', 3, 'text', '{"body":"Proof idea: in $\\triangle ABC$ with $AB = AC$, draw the bisector of $\\angle A$ meeting $\\overline{BC}$ at $D$. Then $\\triangle ABD \\cong \\triangle ACD$ by SAS ($AB = AC$, the bisected angles, and the shared side $AD$). So $\\angle B \\cong \\angle C$. The same bisector is also the perpendicular bisector of the base."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1438a17b1b0520', 'les_d31ec09e8b1572', 'learn', 4, 'definition', '{"term":"Corollaries","body":"A triangle is equilateral if and only if it is equiangular. Each angle of an equilateral triangle measures $60^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f48c39f37e163', 'les_d31ec09e8b1572', 'learn', 5, 'worked_example', '{"title":"An isosceles triangle has vertex angle $48^\\circ$. Find each base angle.","steps":[{"latex":"2x + 48 = 180","explanation":"Base angles are congruent."},{"latex":"x = 66^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_290e4a5c8662b4', 'les_d31ec09e8b1572', 'learn', 6, 'worked_example', '{"title":"In $\\triangle PQR$, $\\angle P \\cong \\angle R$, $PQ = 3x - 4$ and $RQ = x + 10$. Find $PQ$.","steps":[{"latex":"\\text{sides opposite } \\angle R \\text{ and } \\angle P \\text{ are } \\overline{PQ} \\text{ and } \\overline{RQ}","explanation":"Converse of the Isosceles Triangle Theorem."},{"latex":"3x - 4 = x + 10 \\Rightarrow x = 7","explanation":""},{"latex":"PQ = 17","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83363791c84f82', 'les_d31ec09e8b1572', 'learn', 7, 'callout', '{"tone":"warning","title":"Match sides with opposite angles","body":"The congruent base angles are opposite the congruent legs, not next to them. Trace from each angle across the triangle to find its opposite side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46566353209b6f', 'les_d31ec09e8b1572', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Roof gables, A-frame ladders and many bridge trusses are isosceles triangles, so their two slopes match and loads balance. Equilateral triangles tile the plane and make geodesic domes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e2ea21837196f', 'les_d31ec09e8b1572', 1, 'practice', 'numeric', 1, 'The base angles of an isosceles triangle are each $71^\circ$. Find the vertex angle.', '{"answer":38,"unit":"°"}', '[]', '$180 - 2(71) = 38^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e24294eb931c06', 'les_d31ec09e8b1572', 2, 'practice', 'numeric', 2, 'The vertex angle of an isosceles triangle is $(2x)^\circ$ and each base angle is $(x + 20)^\circ$. Find $x$.', '{"answer":35}', '["$2x + 2(x + 20) = 180$."]', '$4x + 40 = 180$, $x = 35$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0d647500d63e1', 'les_d31ec09e8b1572', 3, 'practice', 'numeric', 2, 'An equilateral triangle has sides $4y - 3$ and $2y + 9$. Find the side length.', '{"answer":21}', '["Set them equal."]', '$y = 6$, so the side is $21$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1438a17b1b0520', 'les_d31ec09e8b1572', 4, 'practice', 'multiple_choice', 2, 'A triangle has angles $50^\circ$, $50^\circ$, $80^\circ$. Which is true?', '{"choices":["All sides are equal","The two sides opposite the 50° angles are equal","The side opposite 80° equals another side","It''s a right triangle"],"answer":1}', '[]', 'By the converse, the sides opposite the congruent angles are congruent.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4f48c39f37e163', 'les_d31ec09e8b1572', 5, 'review', 'numeric', 3, 'One base angle of an isosceles triangle is $(3x + 6)^\circ$ and the vertex angle is $(4x)^\circ$. Find the vertex angle.', '{"answer":67.2,"unit":"°","tolerance":0.01}', '["$2(3x + 6) + 4x = 180$."]', '$10x + 12 = 180$, $x = 16.8$, so the vertex angle is $67.2^\circ$ (base angles $56.4^\circ$).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7b73eee2dc851c', 'subj_math', 'isosceles-triangles', 'Isosceles triangles', 'Triangles with two congruent sides, whose base angles are congruent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d31ec09e8b1572', (SELECT id FROM concepts WHERE slug = 'isosceles-triangles'));

-- Lesson: law-of-cosines
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dec595fa5feb1b', 'law-of-cosines', 'The Law of Cosines', 'Derive the Law of Cosines, use it to solve triangles given SAS or SSS, and decide whether to use the Law of Sines or Cosines.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0cd276bddf3a2', 'les_dec595fa5feb1b', 1, 'Derive the Law of Cosines from the Pythagorean theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96407d8fd6f360', 'les_dec595fa5feb1b', 2, 'Solve triangles given two sides and the included angle (SAS) or three sides (SSS).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c164996ba4d682', 'les_dec595fa5feb1b', 3, 'Choose between the Law of Sines and the Law of Cosines, and use Heron''s formula.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0cd276bddf3a2', 'les_dec595fa5feb1b', 'learn', 1, 'formula', '{"latex":"c^2 = a^2 + b^2 - 2ab\\cos C","title":"Law of Cosines","note":"Similarly for a² and b². When C = 90°, cos C = 0 and this is the Pythagorean theorem."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96407d8fd6f360', 'les_dec595fa5feb1b', 'learn', 2, 'text', '{"body":"Derivation: place $C$ at the origin and $B$ at $(a, 0)$. Then $A = (b\\cos C, b\\sin C)$. By the distance formula, $c^2 = (b\\cos C - a)^2 + (b\\sin C)^2 = b^2\\cos^2 C - 2ab\\cos C + a^2 + b^2\\sin^2 C$. Since $\\cos^2 C + \\sin^2 C = 1$, this is $a^2 + b^2 - 2ab\\cos C$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c164996ba4d682', 'les_dec595fa5feb1b', 'learn', 3, 'worked_example', '{"title":"SAS: $a = 9$, $b = 14$, $C = 50^\\circ$. Find $c$.","steps":[{"latex":"c^2 = 81 + 196 - 2(9)(14)\\cos 50^\\circ","explanation":""},{"latex":"c^2 \\approx 277 - 252(0.6428) \\approx 115.02","explanation":""},{"latex":"c \\approx 10.72","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a948a5a09fa78', 'les_dec595fa5feb1b', 'learn', 4, 'worked_example', '{"title":"SSS: sides 7, 8, 13. Find the largest angle.","steps":[{"latex":"\\cos C = \\frac{7^2 + 8^2 - 13^2}{2(7)(8)} = \\frac{-56}{112} = -0.5","explanation":"The largest angle is opposite the longest side."},{"latex":"C = 120^\\circ","explanation":"A negative cosine means an obtuse angle."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97ca3a2e990496', 'les_dec595fa5feb1b', 'learn', 5, 'text', '{"body":"Choosing a law: with SAS or SSS, start with the Law of Cosines. With AAS, ASA or SSA (an angle and its opposite side known), use the Law of Sines. After finding one more part with Cosines, you can switch to Sines, but find the largest angle with Cosines first to avoid the ambiguous case."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de60cba0d92398', 'les_dec595fa5feb1b', 'learn', 6, 'callout', '{"tone":"note","title":"Heron''s formula","body":"From three sides alone: with $s = \\frac{a + b + c}{2}$, $\\text{Area} = \\sqrt{s(s - a)(s - b)(s - c)}$. For 7, 8, 13: $s = 14$, area $= \\sqrt{14 \\cdot 7 \\cdot 6 \\cdot 1} = \\sqrt{588} \\approx 24.25$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9bc0927e495e94', 'les_dec595fa5feb1b', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pilots compute distances when changing heading, robot arms find joint angles from link lengths, and surveyors measure lots with three known sides."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0cd276bddf3a2', 'les_dec595fa5feb1b', 1, 'practice', 'numeric', 2, '$a = 5$, $b = 7$, $C = 60^\circ$. Find $c$ to the nearest hundredth.', '{"answer":6.24,"tolerance":0.006}', '["$c^2 = 25 + 49 - 70(0.5)$."]', '$c^2 = 39$, $c \approx 6.24$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96407d8fd6f360', 'les_dec595fa5feb1b', 2, 'practice', 'numeric', 2, 'A triangle has sides 5, 6, 7. Find the angle opposite the side of length 7, to the nearest tenth of a degree.', '{"answer":78.5,"unit":"°","tolerance":0.06}', '["$\\cos C = \\frac{25 + 36 - 49}{60}$."]', '$\cos C = 0.2$, $C \approx 78.5^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c164996ba4d682', 'les_dec595fa5feb1b', 3, 'practice', 'multiple_choice', 2, 'You know two angles and a non-included side. Which law should you use first?', '{"choices":["Law of Cosines","Law of Sines","Pythagorean theorem","Either one works equally"],"answer":1}', '[]', 'An angle with its opposite side known: Law of Sines.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7a948a5a09fa78', 'les_dec595fa5feb1b', 4, 'review', 'numeric', 3, 'Two ships leave port at the same time. One travels 30 km on one heading, the other 40 km, with $70^\circ$ between their paths. How far apart are they, to the nearest tenth of a km?', '{"answer":41,"unit":"km","tolerance":0.06}', '["$d^2 = 900 + 1600 - 2400\\cos 70^\\circ$."]', '$2400\cos 70^\circ \approx 820.85$, so $d^2 \approx 1679.15$ and $d \approx 41.0$ km.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97ca3a2e990496', 'les_dec595fa5feb1b', 5, 'review', 'numeric', 3, 'Use Heron''s formula to find the area of a triangle with sides 13, 14, 15.', '{"answer":84}', '["$s = 21$."]', '$\sqrt{21 \cdot 8 \cdot 7 \cdot 6} = \sqrt{7056} = 84$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_dec595fa5feb1b', 'subj_math', 'law-of-cosines', 'Law of Cosines', 'c² = a² + b² − 2ab cos C, generalizing the Pythagorean theorem.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dec595fa5feb1b', (SELECT id FROM concepts WHERE slug = 'law-of-cosines'));

-- Lesson: law-of-sines
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7789cf08ba533b', 'law-of-sines', 'The Law of Sines', 'Derive the Law of Sines, use it to solve oblique triangles given AAS, ASA or SSA, analyze the ambiguous case, and find area with ½ab sin C.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1be2ffc727b63b', 'les_7789cf08ba533b', 1, 'Derive the Law of Sines from altitudes and the area formula ½ab sin C.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aedeb08b572302', 'les_7789cf08ba533b', 2, 'Solve triangles given two angles and a side.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9a67e3297068fe', 'les_7789cf08ba533b', 3, 'Analyze the ambiguous SSA case: zero, one or two triangles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1be2ffc727b63b', 'les_7789cf08ba533b', 'learn', 1, 'text', '{"body":"Right-triangle trig doesn''t apply directly to oblique (non-right) triangles. But drop an altitude $h$ from $C$ to side $c$: in the two right triangles formed, $h = b\\sin A$ and $h = a\\sin B$. Setting these equal gives $\\frac{a}{\\sin A} = \\frac{b}{\\sin B}$, and the same argument from another vertex brings in $c$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aedeb08b572302', 'les_7789cf08ba533b', 'learn', 2, 'formula', '{"latex":"\\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C}","title":"Law of Sines","note":"Side a is opposite angle A, and so on."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a67e3297068fe', 'les_7789cf08ba533b', 'learn', 3, 'definition', '{"term":"Area of a triangle","body":"$\\text{Area} = \\frac{1}{2}ab\\sin C$: two sides and the included angle. It comes from area $= \\frac{1}{2}(\\text{base})(\\text{height})$ with height $b\\sin C$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7207fa7f7c15dc', 'les_7789cf08ba533b', 'learn', 4, 'worked_example', '{"title":"Solve $\\triangle ABC$ with $A = 40^\\circ$, $B = 75^\\circ$, $a = 12$","steps":[{"latex":"C = 180^\\circ - 40^\\circ - 75^\\circ = 65^\\circ","explanation":""},{"latex":"b = \\frac{12\\sin 75^\\circ}{\\sin 40^\\circ} \\approx \\frac{12(0.9659)}{0.6428} \\approx 18.03","explanation":""},{"latex":"c = \\frac{12\\sin 65^\\circ}{\\sin 40^\\circ} \\approx 16.92","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_63b06314fd9a85', 'les_7789cf08ba533b', 'learn', 5, 'definition', '{"term":"The ambiguous case (SSA)","body":"Given $a$, $b$ and acute $A$ (with $a$ opposite $A$): let $h = b\\sin A$. If $a < h$: no triangle. If $a = h$: one right triangle. If $h < a < b$: two triangles. If $a \\ge b$: one triangle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd807768295397', 'les_7789cf08ba533b', 'learn', 6, 'worked_example', '{"title":"$A = 30^\\circ$, $a = 7$, $b = 10$. How many triangles?","steps":[{"latex":"h = 10\\sin 30^\\circ = 5","explanation":""},{"latex":"5 < 7 < 10","explanation":"Two triangles."},{"latex":"\\sin B = \\frac{10\\sin 30^\\circ}{7} \\approx 0.7143 \\Rightarrow B \\approx 45.6^\\circ \\text{ or } 134.4^\\circ","explanation":"Both work because 30° + 134.4° < 180°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9021f95180f1e7', 'les_7789cf08ba533b', 'learn', 7, 'callout', '{"tone":"warning","title":"Check the supplement","body":"$\\sin^{-1}$ only returns angles up to $90^\\circ$, but $\\sin B = \\sin(180^\\circ - B)$. In SSA problems always test whether $180^\\circ - B$ also fits in the triangle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_181f5bdb1a9e38', 'les_7789cf08ba533b', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Surveyors and navigators find distances to points they can''t reach by measuring two angles and one baseline (triangulation). GPS and astronomy use the same idea on a larger scale."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1be2ffc727b63b', 'les_7789cf08ba533b', 1, 'practice', 'numeric', 2, 'In $\triangle ABC$, $A = 50^\circ$, $B = 60^\circ$, $a = 10$. Find $b$ to the nearest hundredth.', '{"answer":11.31,"tolerance":0.006}', '["$b = \\frac{10\\sin 60^\\circ}{\\sin 50^\\circ}$."]', '$\frac{8.660}{0.7660} \approx 11.31$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aedeb08b572302', 'les_7789cf08ba533b', 2, 'practice', 'numeric', 2, 'Find the area of a triangle with sides 8 and 11 and included angle $35^\circ$, to the nearest tenth.', '{"answer":25.2,"tolerance":0.06}', '["$\\frac{1}{2}(8)(11)\\sin 35^\\circ$."]', '$44(0.5736) \approx 25.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9a67e3297068fe', 'les_7789cf08ba533b', 3, 'practice', 'multiple_choice', 2, '$A = 40^\circ$, $a = 5$, $b = 10$. How many triangles are possible?', '{"choices":["0","1","2","Infinitely many"],"answer":0}', '["$h = 10\\sin 40^\\circ \\approx 6.43$."]', '$a = 5 < h \approx 6.43$, so the side is too short: no triangle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7207fa7f7c15dc', 'les_7789cf08ba533b', 4, 'review', 'multiple_choice', 3, '$A = 35^\circ$, $a = 8$, $b = 12$. How many triangles?', '{"choices":["0","1","2","3"],"answer":2}', '["$h = 12\\sin 35^\\circ \\approx 6.88$."]', '$6.88 < 8 < 12$: two triangles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_63b06314fd9a85', 'les_7789cf08ba533b', 5, 'review', 'numeric', 3, 'Two observers 500 m apart see a balloon at angles of $62^\circ$ and $71^\circ$ (measured inside the triangle from the baseline). How far is the balloon from the first observer (whose angle is 62°)? Round to the nearest meter.', '{"answer":646,"unit":"m","tolerance":1}', '["The angle at the balloon is 47°.","The side from observer 1 is opposite the 71° angle."]', '$\frac{500\sin 71^\circ}{\sin 47^\circ} \approx \frac{472.8}{0.7314} \approx 646$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7789cf08ba533b', 'subj_math', 'law-of-sines', 'Law of Sines', 'In any triangle, a/sin A = b/sin B = c/sin C.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7789cf08ba533b', (SELECT id FROM concepts WHERE slug = 'law-of-sines'));

-- Lesson: measuring-segments-angles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_94279bb1048142', 'measuring-segments-angles', 'Measuring segments and angles', 'Use the Segment and Angle Addition Postulates, congruence, midpoints and bisectors to set up and solve equations for lengths and angle measures.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d9407facef50e7', 'les_94279bb1048142', 1, 'Find segment lengths on a number line and apply the Segment Addition Postulate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d620d7d24e80e', 'les_94279bb1048142', 2, 'Name and classify angles and apply the Angle Addition Postulate.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9704e2ffe31b04', 'les_94279bb1048142', 3, 'Use midpoints, segment bisectors and angle bisectors to write and solve equations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9407facef50e7', 'les_94279bb1048142', 'learn', 1, 'definition', '{"term":"Length and congruence","body":"The length $AB$ of $\\overline{AB}$ is the distance $|a - b|$ between the coordinates of $A$ and $B$ on a number line. Segments with equal lengths are congruent: $\\overline{AB} \\cong \\overline{CD}$ means $AB = CD$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d620d7d24e80e', 'les_94279bb1048142', 'learn', 2, 'definition', '{"term":"Segment Addition Postulate","body":"If $B$ is between $A$ and $C$, then $AB + BC = AC$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9704e2ffe31b04', 'les_94279bb1048142', 'learn', 3, 'worked_example', '{"title":"$B$ is between $A$ and $C$, $AB = 2x + 3$, $BC = 3x - 1$ and $AC = 32$. Find $x$ and $AB$.","steps":[{"latex":"(2x + 3) + (3x - 1) = 32","explanation":"Segment Addition Postulate."},{"latex":"5x + 2 = 32 \\Rightarrow x = 6","explanation":""},{"latex":"AB = 2(6) + 3 = 15","explanation":"Check: $BC = 17$ and $15 + 17 = 32$. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e12659065143b7', 'les_94279bb1048142', 'learn', 4, 'definition', '{"term":"Angles","body":"An angle is two rays with a common endpoint, the vertex. $\\angle ABC$ has vertex $B$. Its measure $m\\angle ABC$ is in degrees. Acute: between $0^\\circ$ and $90^\\circ$. Right: $90^\\circ$. Obtuse: between $90^\\circ$ and $180^\\circ$. Straight: $180^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6115cdbd6ca75', 'les_94279bb1048142', 'learn', 5, 'definition', '{"term":"Angle Addition Postulate","body":"If $D$ is in the interior of $\\angle ABC$, then $m\\angle ABD + m\\angle DBC = m\\angle ABC$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3275f4c26b23b', 'les_94279bb1048142', 'learn', 6, 'definition', '{"term":"Midpoints and bisectors","body":"The midpoint of a segment divides it into two congruent segments. An angle bisector is a ray that divides an angle into two congruent angles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92ba76d883acfd', 'les_94279bb1048142', 'learn', 7, 'worked_example', '{"title":"$\\overrightarrow{BD}$ bisects $\\angle ABC$, $m\\angle ABD = 4x - 2$ and $m\\angle DBC = 2x + 16$. Find $m\\angle ABC$.","steps":[{"latex":"4x - 2 = 2x + 16","explanation":"A bisector makes the two angles equal."},{"latex":"x = 9","explanation":""},{"latex":"m\\angle ABD = 34^\\circ,\\ m\\angle ABC = 68^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_039593f3e9c8c5', 'les_94279bb1048142', 'learn', 8, 'callout', '{"tone":"warning","title":"Name angles with the vertex in the middle","body":"$\\angle ABC$ and $\\angle CBA$ are the same angle, but $\\angle BAC$ is a different one, with vertex $A$. Use a single letter like $\\angle B$ only when just one angle has that vertex."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ca13046f753d3', 'les_94279bb1048142', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carpenters split boards with segment addition, surveyors measure angles with theodolites, and a protractor works because angle measure behaves like a number line wrapped around the vertex."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9407facef50e7', 'les_94279bb1048142', 1, 'practice', 'numeric', 1, 'On a number line, $P$ is at $-4$ and $Q$ is at $7$. Find $PQ$.', '{"answer":11}', '["Distance is |a − b|."]', '$|-4 - 7| = 11$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d620d7d24e80e', 'les_94279bb1048142', 2, 'practice', 'numeric', 2, '$M$ is the midpoint of $\overline{AB}$, $AM = 3x + 4$ and $MB = 5x - 6$. Find $AB$.', '{"answer":38}', '["Set AM = MB.","x = 5."]', '$3x + 4 = 5x - 6$ gives $x = 5$. $AM = 19$, so $AB = 38$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9704e2ffe31b04', 'les_94279bb1048142', 3, 'practice', 'numeric', 2, '$m\angle PQR = 115^\circ$, $S$ is in its interior, and $m\angle PQS = 48^\circ$. Find $m\angle SQR$.', '{"answer":67,"unit":"°"}', '["Angle Addition Postulate."]', '$115 - 48 = 67^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e12659065143b7', 'les_94279bb1048142', 4, 'practice', 'multiple_choice', 1, 'An angle measures $90^\circ$. It is…', '{"choices":["acute","right","obtuse","straight"],"answer":1}', '[]', 'A $90^\circ$ angle is a right angle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6115cdbd6ca75', 'les_94279bb1048142', 5, 'practice', 'numeric', 2, '$B$ is between $A$ and $C$. $AB = x + 5$, $BC = 2x$, $AC = 5x - 13$. Find $AC$.', '{"answer":32}', '["$x + 5 + 2x = 5x - 13$."]', '$3x + 5 = 5x - 13$, so $x = 9$ and $AC = 45 - 13 = 32$. Check: $14 + 18 = 32$ ✓.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3275f4c26b23b', 'les_94279bb1048142', 6, 'review', 'numeric', 3, '$\overrightarrow{OM}$ bisects $\angle LON$. $m\angle LON = 6x + 10$ and $m\angle LOM = 4x - 5$. Find $m\angle LOM$.', '{"answer":35,"unit":"°"}', '["$m\\angle LON = 2 \\cdot m\\angle LOM$."]', '$6x + 10 = 2(4x - 5) = 8x - 10$, so $x = 10$ and $m\angle LOM = 35^\circ$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5ae0ddd8e28610', 'subj_math', 'segment-angle-measure', 'Segment and angle measure', 'Lengths of segments and measures of angles, and how they add.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_94279bb1048142', (SELECT id FROM concepts WHERE slug = 'segment-angle-measure'));

-- Lesson: midpoint-distance
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d361fda1af3d91', 'midpoint-distance', 'Midpoint and distance in the coordinate plane', 'Find the midpoint and length of a segment from its endpoints, find a missing endpoint, and see how the distance formula comes from the Pythagorean theorem.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5c7e76f8e9ae6', 'les_d361fda1af3d91', 1, 'Find the midpoint of a segment with the midpoint formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d8351e247709ec', 'les_d361fda1af3d91', 2, 'Find a missing endpoint given one endpoint and the midpoint.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aa8814dfc60099', 'les_d361fda1af3d91', 3, 'Derive and use the distance formula from the Pythagorean theorem.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5c7e76f8e9ae6', 'les_d361fda1af3d91', 'learn', 1, 'formula', '{"latex":"M = \\left(\\frac{x_1 + x_2}{2},\\ \\frac{y_1 + y_2}{2}\\right)","title":"Midpoint formula","note":"Average the x-coordinates and average the y-coordinates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8351e247709ec', 'les_d361fda1af3d91', 'learn', 2, 'worked_example', '{"title":"Find the midpoint of $A(-3, 5)$ and $B(7, -1)$","steps":[{"latex":"\\left(\\frac{-3 + 7}{2},\\ \\frac{5 + (-1)}{2}\\right) = (2, 2)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa8814dfc60099', 'les_d361fda1af3d91', 'learn', 3, 'worked_example', '{"title":"$M(1, -2)$ is the midpoint of $\\overline{PQ}$ and $P(-4, 3)$. Find $Q$.","steps":[{"latex":"\\frac{-4 + x}{2} = 1 \\Rightarrow x = 6","explanation":"Solve each coordinate separately."},{"latex":"\\frac{3 + y}{2} = -2 \\Rightarrow y = -7","explanation":""},{"latex":"Q(6, -7)","explanation":"Or think: from P to M is +5, −5, so add that again."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_510d1a2dee1c07', 'les_d361fda1af3d91', 'learn', 4, 'text', '{"body":"To find the distance between two points, draw the right triangle whose legs are horizontal and vertical. The legs have lengths $|x_2 - x_1|$ and $|y_2 - y_1|$, and the segment is the hypotenuse. The Pythagorean theorem gives the distance formula."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5bc450f31a0ab7', 'les_d361fda1af3d91', 'learn', 5, 'formula', '{"latex":"d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}","title":"Distance formula"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1acfbc9feb5a3c', 'les_d361fda1af3d91', 'learn', 6, 'worked_example', '{"title":"Find the distance between $(-2, 1)$ and $(4, 9)$","steps":[{"latex":"d = \\sqrt{(4 - (-2))^2 + (9 - 1)^2} = \\sqrt{36 + 64}","explanation":"Legs of 6 and 8."},{"latex":"d = \\sqrt{100} = 10","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3b54e94b3c1b9', 'les_d361fda1af3d91', 'experiment', 7, 'activity', '{"activity":"coordinate-plane","title":"Count the legs","params":{"x":4,"y":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d24178b85c516', 'les_d361fda1af3d91', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"With P at $(4, 3)$, the dashed lines are legs of length 4 and 3, so P is $\\sqrt{16 + 9} = 5$ units from the origin. Move P to $(-5, 12)$: how far is it from the origin?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fb3713ef8cad1', 'les_d361fda1af3d91', 'learn', 9, 'callout', '{"tone":"warning","title":"Square before adding","body":"$\\sqrt{6^2 + 8^2} \\ne 6 + 8$. And the order of the points doesn''t matter, because squaring removes the sign of each difference."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e6342ed092299', 'les_d361fda1af3d91', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ride-hailing apps compute straight-line distances between GPS coordinates, and game engines use the distance formula to detect collisions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5c7e76f8e9ae6', 'les_d361fda1af3d91', 1, 'practice', 'short_text', 1, 'Find the midpoint of $(2, 8)$ and $(6, -4)$. Enter as (x,y).', '{"accept":["(4,2)"]}', '["Average each coordinate."]', '$(4, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d8351e247709ec', 'les_d361fda1af3d91', 2, 'practice', 'numeric', 1, 'Find the distance between $(0, 0)$ and $(5, 12)$.', '{"answer":13}', '["$\\sqrt{25 + 144}$."]', '$\sqrt{169} = 13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aa8814dfc60099', 'les_d361fda1af3d91', 3, 'practice', 'numeric', 2, 'Find the distance between $(-3, 4)$ and $(1, 1)$.', '{"answer":5}', '["Legs 4 and 3."]', '$\sqrt{16 + 9} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_510d1a2dee1c07', 'les_d361fda1af3d91', 4, 'practice', 'short_text', 2, '$M(3, 0)$ is the midpoint of $\overline{AB}$ and $A(-1, 5)$. Find $B$. Enter as (x,y).', '{"accept":["(7,-5)"]}', '["From A to M is +4, −5."]', '$B = (3 + 4, 0 - 5) = (7, -5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5bc450f31a0ab7', 'les_d361fda1af3d91', 5, 'practice', 'numeric', 2, 'Find the distance between $(2, -1)$ and $(5, 3)$.', '{"answer":5}', '[]', '$\sqrt{9 + 16} = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1acfbc9feb5a3c', 'les_d361fda1af3d91', 6, 'review', 'numeric', 3, 'Find the perimeter of the triangle with vertices $(0, 0)$, $(6, 0)$ and $(6, 8)$.', '{"answer":24}', '["Two sides are horizontal or vertical.","The third side is a hypotenuse."]', '$6 + 8 + 10 = 24$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3b54e94b3c1b9', 'les_d361fda1af3d91', 7, 'review', 'multiple_choice', 3, 'Which point is equidistant from $(0, 0)$ and $(8, 0)$?', '{"choices":["$(4, 7)$","$(3, 3)$","$(5, 0)$","$(8, 4)$"],"answer":0}', '["Points equidistant from two points lie on the perpendicular bisector."]', 'The perpendicular bisector is $x = 4$, so $(4, 7)$: both distances are $\sqrt{65}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_64eaafaca65525', 'subj_math', 'coordinate-geometry', 'Coordinate geometry', 'Studying geometric figures with coordinates and algebra.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d361fda1af3d91', (SELECT id FROM concepts WHERE slug = 'coordinate-geometry'));
