-- Lesson: parabola-focus-directrix
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cef2e285df0920', 'parabola-focus-directrix', 'Equations of parabolas from focus and directrix', 'Define a parabola as the points equidistant from a focus and a directrix, derive its equation with the distance formula, and find the focus and directrix from an equation.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_92410115d23ddc', 'les_cef2e285df0920', 1, 'Define a parabola geometrically using a focus and directrix.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d64734a3af8620', 'les_cef2e285df0920', 2, 'Derive the equation of a parabola from its focus and directrix.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_41e9cb1292a44d', 'les_cef2e285df0920', 3, 'Find the vertex, focus and directrix of (x − h)² = 4p(y − k).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92410115d23ddc', 'les_cef2e285df0920', 'learn', 1, 'definition', '{"term":"Parabola","body":"The set of all points in a plane that are the same distance from a fixed point (the focus) and a fixed line (the directrix). The vertex is halfway between them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d64734a3af8620', 'les_cef2e285df0920', 'learn', 2, 'worked_example', '{"title":"Find the equation of the parabola with focus $(0, 2)$ and directrix $y = -2$","steps":[{"latex":"\\sqrt{x^2 + (y - 2)^2} = |y + 2|","explanation":"Distance to focus = distance to directrix."},{"latex":"x^2 + y^2 - 4y + 4 = y^2 + 4y + 4","explanation":"Square both sides."},{"latex":"x^2 = 8y \\Rightarrow y = \\tfrac{1}{8}x^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_41e9cb1292a44d', 'les_cef2e285df0920', 'learn', 3, 'definition', '{"term":"Standard form","body":"With vertex $(h, k)$ and directed distance $p$ from the vertex to the focus: $(x - h)^2 = 4p(y - k)$ opens up if $p > 0$ and down if $p < 0$. The focus is $(h, k + p)$ and the directrix is $y = k - p$. Equivalently $y = \\frac{1}{4p}(x - h)^2 + k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad29ef8e07770f', 'les_cef2e285df0920', 'experiment', 4, 'activity', '{"activity":"vertex-explorer","title":"Narrow and wide parabolas","params":{"a":0.5,"h":0,"k":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1aa196e09ff22', 'les_cef2e285df0920', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"For $y = ax^2$, $a = \\frac{1}{4p}$, so $p = \\frac{1}{4a}$. With $a = 0.5$, the focus is at $(0, 0.5)$. Make the parabola wider (smaller $a$): does the focus move away from the vertex or toward it?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d8ad08347fa16', 'les_cef2e285df0920', 'learn', 6, 'worked_example', '{"title":"Find the vertex, focus and directrix of $(x + 1)^2 = -12(y - 3)$","steps":[{"latex":"h = -1,\\ k = 3,\\ 4p = -12 \\Rightarrow p = -3","explanation":""},{"latex":"\\text{vertex } (-1, 3),\\ \\text{focus } (-1, 0),\\ \\text{directrix } y = 6","explanation":"Opens down because p < 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a835f12ddef333', 'les_cef2e285df0920', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Satellite dishes, car headlights and solar cookers are parabolic because every ray parallel to the axis reflects through the focus (and vice versa). The receiver or bulb sits at the focus."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92410115d23ddc', 'les_cef2e285df0920', 1, 'practice', 'short_text', 2, 'Write the equation of the parabola with focus $(0, 3)$ and directrix $y = -3$, in the form x^2=…y.', '{"accept":["x^2=12y"]}', '["$p = 3$, so $4p = 12$."]', '$x^2 = 12y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d64734a3af8620', 'les_cef2e285df0920', 2, 'practice', 'short_text', 2, 'Find the focus of $x^2 = 20y$. Enter as (x,y).', '{"accept":["(0,5)"]}', '["$4p = 20$."]', '$p = 5$: focus $(0, 5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_41e9cb1292a44d', 'les_cef2e285df0920', 3, 'practice', 'numeric', 2, 'What is the directrix of $(x - 2)^2 = 8(y + 1)$? Enter the value c in y = c.', '{"answer":-3}', '["Vertex $(2, -1)$, $p = 2$."]', '$y = -1 - 2 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad29ef8e07770f', 'les_cef2e285df0920', 4, 'practice', 'multiple_choice', 2, 'Which way does $(x - 4)^2 = -6(y - 1)$ open?', '{"choices":["Up","Down","Left","Right"],"answer":1}', '["Sign of p."]', '$4p = -6 < 0$: down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1aa196e09ff22', 'les_cef2e285df0920', 5, 'review', 'numeric', 3, 'A satellite dish has cross-section $y = \frac{1}{16}x^2$ (in inches). How far above the vertex should the receiver be placed?', '{"answer":4,"unit":"in"}', '["$\\frac{1}{4p} = \\frac{1}{16}$."]', '$p = 4$ inches.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_91f78d2159ea83', 'subj_math', 'conic-parabola', 'Parabola (conic section)', 'The set of points equidistant from a focus point and a directrix line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cef2e285df0920', (SELECT id FROM concepts WHERE slug = 'conic-parabola'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cef2e285df0920', (SELECT id FROM formulas WHERE slug = 'distance-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cef2e285df0920', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 2);

-- Lesson: paragraph-flow-proofs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_422c554f16329d', 'paragraph-flow-proofs', 'Paragraph and flow proofs', 'Write the same argument as a two-column proof, a flow proof and a paragraph proof, and choose the clearest format for a given theorem.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10be4172e3573e', 'les_422c554f16329d', 1, 'Write a flow proof with boxes for statements and reasons underneath.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ef1ade2042550c', 'les_422c554f16329d', 2, 'Write a paragraph proof that justifies each step in complete sentences.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68b71dc1bffff2', 'les_422c554f16329d', 3, 'Convert between proof formats and judge which communicates best.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10be4172e3573e', 'les_422c554f16329d', 'learn', 1, 'text', '{"body":"A proof is an argument, not a format. Two-column proofs make every reason explicit. Flow proofs show how statements depend on each other, which is clearer when several facts feed into one conclusion. Paragraph proofs read like ordinary mathematical writing and are what you''ll see in textbooks and papers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ef1ade2042550c', 'les_422c554f16329d', 'learn', 2, 'definition', '{"term":"Flow proof","body":"Each statement goes in a box with its reason written below. Arrows show which statements lead to which. Independent facts can sit side by side and then join."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68b71dc1bffff2', 'les_422c554f16329d', 'learn', 3, 'definition', '{"term":"Paragraph proof","body":"A written argument in complete sentences. Every claim still needs a reason, introduced by words like \"because,\" \"by,\" or \"since.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52f0cc463cd515', 'les_422c554f16329d', 'learn', 4, 'worked_example', '{"title":"Vertical Angles Theorem, as a paragraph proof","steps":[{"latex":"\\text{Let } \\angle 1, \\angle 3 \\text{ be vertical, with } \\angle 2 \\text{ adjacent to both}","explanation":"Set up the situation."},{"latex":"m\\angle 1 + m\\angle 2 = 180^\\circ,\\ m\\angle 2 + m\\angle 3 = 180^\\circ","explanation":"Each pair is a linear pair, so the angles are supplementary."},{"latex":"m\\angle 1 = m\\angle 3","explanation":"By substitution and the subtraction property, so ∠1 ≅ ∠3."}],"check":"Written out: \"Angles 1 and 2 form a linear pair, so they are supplementary; likewise angles 2 and 3. Therefore $m\\angle 1 + m\\angle 2 = m\\angle 2 + m\\angle 3$, and subtracting $m\\angle 2$ gives $m\\angle 1 = m\\angle 3$. So $\\angle 1 \\cong \\angle 3$.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a39b443d5c2419', 'les_422c554f16329d', 'learn', 5, 'worked_example', '{"title":"Flow proof: if $M$ is the midpoint of $\\overline{AB}$ and of $\\overline{CD}$, then $\\triangle AMC \\cong \\triangle BMD$","steps":[{"latex":"\\boxed{\\overline{AM} \\cong \\overline{BM}} \\quad \\boxed{\\overline{CM} \\cong \\overline{DM}} \\quad \\boxed{\\angle AMC \\cong \\angle BMD}","explanation":"Def. of midpoint, def. of midpoint, vertical angles: three independent boxes."},{"latex":"\\searrow \\quad \\downarrow \\quad \\swarrow","explanation":"All three arrows lead to the conclusion."},{"latex":"\\boxed{\\triangle AMC \\cong \\triangle BMD}","explanation":"SAS."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54e078e890507b', 'les_422c554f16329d', 'learn', 6, 'callout', '{"tone":"tip","title":"Write the plan first","body":"For any format, start with a one-sentence plan: \"Show the triangles are congruent by SAS, then use CPCTC.\" The plan becomes the skeleton of a paragraph proof."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aaad4ace82b1e9', 'les_422c554f16329d', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Paragraph proofs are how mathematicians, scientists and lawyers argue in writing. Flowcharts of dependencies are how engineers plan projects and how programmers trace a bug back to its cause."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10be4172e3573e', 'les_422c554f16329d', 1, 'practice', 'multiple_choice', 1, 'In a flow proof, what goes under each box?', '{"choices":["A diagram","The reason for that statement","The next statement","A question"],"answer":1}', '[]', 'Each box holds a statement, and its reason is written below it.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ef1ade2042550c', 'les_422c554f16329d', 2, 'practice', 'multiple_choice', 2, 'Which format best shows that several independent facts combine into one conclusion?', '{"choices":["Two-column","Flow","Paragraph","They''re identical"],"answer":1}', '[]', 'A flow proof shows parallel branches joining.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68b71dc1bffff2', 'les_422c554f16329d', 3, 'practice', 'multiple_choice', 2, 'Which sentence is a properly justified step in a paragraph proof?', '{"choices":["AB = CD.","Since M is the midpoint of AB, AM = MB.","It''s obvious that the angles are equal.","The triangles look congruent."],"answer":1}', '["Every claim needs a reason."]', 'It states the claim and the reason (the definition of midpoint).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52f0cc463cd515', 'les_422c554f16329d', 4, 'review', 'multiple_choice', 3, 'A paragraph proof says: "∠A and ∠B are both complementary to ∠C, so ∠A ≅ ∠B." Which theorem justifies this?', '{"choices":["Vertical Angles Theorem","Congruent Complements Theorem","Linear Pair Postulate","Triangle Sum Theorem"],"answer":1}', '[]', 'Angles complementary to the same angle are congruent.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0ec7ceb9331d7a', 'subj_math', 'geometric-proof', 'Geometric proof', 'Justifying geometric statements with definitions, postulates and theorems.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_422c554f16329d', (SELECT id FROM concepts WHERE slug = 'geometric-proof'));

-- Lesson: parallel-lines-transversals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e10af7c55770ff', 'parallel-lines-transversals', 'Angles formed by parallel lines and a transversal', 'Name corresponding, alternate interior, alternate exterior and same-side interior angles, and use the parallel-line angle relationships to find unknown angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b651f691f42da8', 'les_e10af7c55770ff', 1, 'Identify angle pairs formed by two lines and a transversal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8fbefd301c44ca', 'les_e10af7c55770ff', 2, 'State the postulate and theorems relating these angles when the lines are parallel.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3596c8481f5df9', 'les_e10af7c55770ff', 3, 'Write and solve equations using these angle relationships.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b651f691f42da8', 'les_e10af7c55770ff', 'learn', 1, 'definition', '{"term":"Transversal","body":"A line that crosses two or more lines at different points. Two lines cut by a transversal make eight angles: four at each intersection."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fbefd301c44ca', 'les_e10af7c55770ff', 'learn', 2, 'definition', '{"term":"Angle pairs","body":"Corresponding angles are in matching positions at the two intersections. Alternate interior angles are between the lines on opposite sides of the transversal. Alternate exterior angles are outside the lines on opposite sides. Same-side (consecutive) interior angles are between the lines on the same side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3596c8481f5df9', 'les_e10af7c55770ff', 'learn', 3, 'definition', '{"term":"When the lines are parallel","body":"Corresponding Angles Postulate: corresponding angles are congruent. From it follow: alternate interior angles are congruent, alternate exterior angles are congruent, and same-side interior angles are supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65af06f48651a3', 'les_e10af7c55770ff', 'learn', 4, 'text', '{"body":"Why are alternate interior angles congruent? Let $\\angle 3$ and $\\angle 6$ be alternate interior angles. $\\angle 3$ corresponds to $\\angle 7$ at the other intersection, so $\\angle 3 \\cong \\angle 7$. And $\\angle 7$ and $\\angle 6$ are vertical angles, so $\\angle 7 \\cong \\angle 6$. By the transitive property, $\\angle 3 \\cong \\angle 6$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_07c17813b61ef7', 'les_e10af7c55770ff', 'learn', 5, 'worked_example', '{"title":"Parallel lines are cut by a transversal. Alternate interior angles measure $(5x - 12)^\\circ$ and $(3x + 20)^\\circ$. Find both angles.","steps":[{"latex":"5x - 12 = 3x + 20","explanation":"Alternate interior angles are congruent."},{"latex":"x = 16 \\Rightarrow 5(16) - 12 = 68^\\circ","explanation":"Both measure 68°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30189d49aa35b1', 'les_e10af7c55770ff', 'learn', 6, 'worked_example', '{"title":"Same-side interior angles measure $(2x + 15)^\\circ$ and $(4x - 9)^\\circ$. Find $x$.","steps":[{"latex":"(2x + 15) + (4x - 9) = 180","explanation":"Same-side interior angles are supplementary."},{"latex":"6x + 6 = 180 \\Rightarrow x = 29","explanation":"The angles are 73° and 107°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_39a2883094b765', 'les_e10af7c55770ff', 'learn', 7, 'callout', '{"tone":"tip","title":"Only two sizes","body":"When a transversal crosses two parallel lines, all eight angles come in just two sizes: four acute angles that are equal and four obtuse angles that are equal (unless the transversal is perpendicular, when all eight are 90°). Any acute one and any obtuse one are supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36594ecaee049b', 'les_e10af7c55770ff', 'learn', 8, 'callout', '{"tone":"warning","title":"The lines must be parallel","body":"These congruences and supplements hold only when the lines are parallel. If they aren''t marked or given as parallel, you can''t use them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b725b533415e93', 'les_e10af7c55770ff', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Railroad tracks, lane markings and staircase railings use parallel lines. Carpenters cut stair stringers using alternate interior angles so every step is level."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b651f691f42da8', 'les_e10af7c55770ff', 1, 'practice', 'multiple_choice', 1, 'Two angles lie between two parallel lines on opposite sides of the transversal. They are…', '{"choices":["Corresponding","Alternate interior","Alternate exterior","Same-side interior"],"answer":1}', '[]', 'Between the lines and on opposite sides: alternate interior.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fbefd301c44ca', 'les_e10af7c55770ff', 2, 'practice', 'numeric', 1, 'Parallel lines are cut by a transversal. One angle is $63^\circ$. What is the measure of its corresponding angle?', '{"answer":63,"unit":"°"}', '[]', 'Corresponding angles are congruent: $63^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3596c8481f5df9', 'les_e10af7c55770ff', 3, 'practice', 'numeric', 2, 'Same-side interior angles measure $3x^\circ$ and $(x + 40)^\circ$. Find $x$.', '{"answer":35}', '["They are supplementary."]', '$4x + 40 = 180$, $x = 35$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_65af06f48651a3', 'les_e10af7c55770ff', 4, 'practice', 'numeric', 2, 'Alternate exterior angles measure $(6x + 4)^\circ$ and $(8x - 18)^\circ$. Find the angle.', '{"answer":70,"unit":"°"}', '["Set them equal: x = 11."]', '$6(11) + 4 = 70^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_07c17813b61ef7', 'les_e10af7c55770ff', 5, 'practice', 'numeric', 2, 'A transversal makes a $118^\circ$ angle with one of two parallel lines. What is the measure of each acute angle formed?', '{"answer":62,"unit":"°"}', '["Acute and obtuse angles are supplementary."]', '$180 - 118 = 62^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30189d49aa35b1', 'les_e10af7c55770ff', 6, 'review', 'multiple_choice', 3, 'Which reasoning shows that alternate interior angles are congruent?', '{"choices":["Linear pair + definition of parallel","Corresponding Angles Postulate + Vertical Angles Theorem","Angle Addition only","Triangle angle sum"],"answer":1}', '[]', 'Each alternate interior angle is vertical to an angle that corresponds to the other.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2a1d821979eb41', 'subj_math', 'parallel-lines', 'Parallel lines and transversals', 'Angle relationships formed when a transversal crosses two parallel lines.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e10af7c55770ff', (SELECT id FROM concepts WHERE slug = 'parallel-lines'));

-- Lesson: partitioning-segment
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f4edecf48df921', 'partitioning-segment', 'Partitioning a segment', 'Find the point that divides a directed segment in a given ratio, using fractions of the run and rise.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_27e72ddc730bb5', 'les_f4edecf48df921', 1, 'Interpret a ratio a : b along a directed segment as a fraction a/(a + b) of the way.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4fc7deccef8030', 'les_f4edecf48df921', 2, 'Find the partition point with P = A + k(B − A).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_372869adfb1f43', 'les_f4edecf48df921', 3, 'Solve for an endpoint given the partition point and ratio.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27e72ddc730bb5', 'les_f4edecf48df921', 'learn', 1, 'text', '{"body":"The midpoint splits a segment in the ratio $1 : 1$. More generally, a point $P$ that divides directed segment $\\overline{AB}$ in the ratio $a : b$ is $\\frac{a}{a + b}$ of the way from $A$ to $B$. Direction matters: \"from A to B\" and \"from B to A\" give different points unless the ratio is 1 : 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fc7deccef8030', 'les_f4edecf48df921', 'learn', 2, 'formula', '{"latex":"P = \\left(x_1 + k(x_2 - x_1),\\ y_1 + k(y_2 - y_1)\\right), \\quad k = \\frac{a}{a + b}","title":"Partition formula"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_372869adfb1f43', 'les_f4edecf48df921', 'learn', 3, 'worked_example', '{"title":"Find $P$ on $\\overline{AB}$ from $A(-2, 1)$ to $B(10, 7)$ so that $AP : PB = 1 : 2$","steps":[{"latex":"k = \\tfrac{1}{3}","explanation":"One third of the way from A."},{"latex":"\\text{run} = 12,\\ \\text{rise} = 6","explanation":""},{"latex":"P = (-2 + 4,\\ 1 + 2) = (2, 3)","explanation":""}],"check":"Check: $AP = \\sqrt{16 + 4} = 2\\sqrt{5}$ and $PB = \\sqrt{64 + 16} = 4\\sqrt{5}$, ratio $1 : 2$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_793ee6e348dfc5', 'les_f4edecf48df921', 'learn', 4, 'worked_example', '{"title":"Same segment, ratio $3 : 1$","steps":[{"latex":"k = \\tfrac{3}{4}","explanation":""},{"latex":"P = (-2 + 9,\\ 1 + 4.5) = (7, 5.5)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ea77e16c75b89', 'les_f4edecf48df921', 'learn', 5, 'callout', '{"tone":"warning","title":"Ratio vs fraction","body":"A ratio of $2 : 3$ means $\\frac{2}{5}$ of the way, not $\\frac{2}{3}$. Add the parts to get the denominator."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab31d367aba6c2', 'les_f4edecf48df921', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Animation interpolates positions between keyframes this way, and maps place a point a given fraction along a road. The centroid of a triangle is the point $2 : 1$ along each median."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_27e72ddc730bb5', 'les_f4edecf48df921', 1, 'practice', 'short_text', 1, 'Find the point $\frac{1}{4}$ of the way from $(0, 0)$ to $(8, 12)$. Enter as (x,y).', '{"accept":["(2,3)"]}', '[]', '$(2, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fc7deccef8030', 'les_f4edecf48df921', 2, 'practice', 'short_text', 2, 'Find $P$ on directed segment $A(1, 2)$ to $B(11, 7)$ with $AP : PB = 2 : 3$. Enter as (x,y).', '{"accept":["(5,4)"]}', '["$k = \\frac{2}{5}$."]', '$(1 + 4, 2 + 2) = (5, 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_372869adfb1f43', 'les_f4edecf48df921', 3, 'practice', 'short_text', 2, 'Find $P$ on directed segment $A(-4, 6)$ to $B(8, -3)$ with $AP : PB = 1 : 2$. Enter as (x,y).', '{"accept":["(0,3)"]}', '["$k = \\frac{1}{3}$; run 12, rise −9."]', '$(-4 + 4, 6 - 3) = (0, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_793ee6e348dfc5', 'les_f4edecf48df921', 4, 'review', 'short_text', 3, '$P(4, 1)$ divides directed segment $A(-2, -2)$ to $B$ in the ratio $3 : 1$. Find $B$. Enter as (x,y).', '{"accept":["(6,2)"]}', '["$P$ is $\\frac{3}{4}$ of the way, so $B - A = \\frac{4}{3}(P - A)$."]', '$P - A = (6, 3)$, so $B - A = (8, 4)$ and $B = (6, 2)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_64eaafaca65525', 'subj_math', 'coordinate-geometry', 'Coordinate geometry', 'Studying geometric figures with coordinates and algebra.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f4edecf48df921', (SELECT id FROM concepts WHERE slug = 'coordinate-geometry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f4edecf48df921', (SELECT id FROM formulas WHERE slug = 'midpoint-formula'), 1);

-- Lesson: permutations-combinations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_70fe875641de53', 'permutations-combinations', 'Permutations and combinations', 'Count arrangements with factorials and permutations, count selections with combinations, decide whether order matters, and use counting to find probabilities.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_280c7d8b26be52', 'les_70fe875641de53', 1, 'Use factorials and the counting principle to count arrangements.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_701e3a979df342', 'les_70fe875641de53', 2, 'Distinguish permutations (order matters) from combinations (order doesn''t) and compute each.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc8c06172d3ce6', 'les_70fe875641de53', 3, 'Use permutations and combinations to compute probabilities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_280c7d8b26be52', 'les_70fe875641de53', 'learn', 1, 'definition', '{"term":"Factorial","body":"$n! = n(n - 1)(n - 2)\\cdots 1$, the number of ways to arrange $n$ distinct items in a row. $5! = 120$, and by definition $0! = 1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_701e3a979df342', 'les_70fe875641de53', 'learn', 2, 'definition', '{"term":"Permutations","body":"Ordered arrangements of $r$ items chosen from $n$: $ {}_nP_r = \\frac{n!}{(n - r)!}$. Choosing a president, vice president and secretary from 10 people: $ {}_{10}P_3 = 10 \\cdot 9 \\cdot 8 = 720$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc8c06172d3ce6', 'les_70fe875641de53', 'learn', 3, 'definition', '{"term":"Combinations","body":"Unordered selections: $ {}_nC_r = \\frac{n!}{r!(n - r)!}$. Choosing a 3-person committee from 10: $ {}_{10}C_3 = \\frac{720}{3!} = 120$. Each committee corresponds to $3! = 6$ ordered lists, so we divide by 6."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1727b356981ee4', 'les_70fe875641de53', 'learn', 4, 'text', '{"body":"The key question is: would swapping two chosen items give a different result? Race finishes, passwords and officer roles: yes, so permutations. Teams, pizza toppings and lottery picks: no, so combinations."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83ed30ed7e4269', 'les_70fe875641de53', 'learn', 5, 'worked_example', '{"title":"How many 4-digit PINs have no repeated digits?","steps":[{"latex":"{}_{10}P_4 = 10 \\cdot 9 \\cdot 8 \\cdot 7 = 5040","explanation":"Order matters: 1234 and 4321 are different PINs."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9786b30caf43a', 'les_70fe875641de53', 'learn', 6, 'worked_example', '{"title":"A 5-card hand is dealt from 52 cards. What is the probability all 5 are hearts?","steps":[{"latex":"{}_{13}C_5 = 1287","explanation":"Ways to choose 5 hearts."},{"latex":"{}_{52}C_5 = 2{,}598{,}960","explanation":"All possible hands."},{"latex":"P = \\tfrac{1287}{2598960} \\approx 0.000495","explanation":"About 1 in 2,020."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3cc5d70a759800', 'les_70fe875641de53', 'learn', 7, 'callout', '{"tone":"warning","title":"Repetition changes things","body":"The formulas assume no repetition. If repetition is allowed (like a PIN where digits may repeat), use the counting principle: $10^4 = 10{,}000$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_511a4ae3e5e66d', 'les_70fe875641de53', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Password strength, lottery odds, scheduling tournaments, and genetics (combinations of alleles) all rely on counting."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_280c7d8b26be52', 'les_70fe875641de53', 1, 'practice', 'numeric', 1, 'Evaluate $6!$.', '{"answer":720}', '[]', '$720$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_701e3a979df342', 'les_70fe875641de53', 2, 'practice', 'numeric', 2, 'In how many ways can 1st, 2nd and 3rd place be awarded among 8 runners?', '{"answer":336}', '["Order matters."]', '$ {}_8P_3 = 8 \cdot 7 \cdot 6 = 336$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc8c06172d3ce6', 'les_70fe875641de53', 3, 'practice', 'numeric', 2, 'How many ways can 4 toppings be chosen from 9?', '{"answer":126}', '["Order doesn''t matter."]', '$ {}_9C_4 = \frac{9 \cdot 8 \cdot 7 \cdot 6}{24} = 126$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1727b356981ee4', 'les_70fe875641de53', 4, 'practice', 'multiple_choice', 2, 'Choosing a team captain and co-captain from 15 players is a…', '{"choices":["Combination","Permutation","Neither","Factorial only"],"answer":1}', '["Are the roles different?"]', 'The roles differ, so order matters: a permutation ($ {}_{15}P_2 = 210$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83ed30ed7e4269', 'les_70fe875641de53', 5, 'review', 'numeric', 3, 'A committee of 3 is chosen at random from 5 girls and 4 boys. What is the probability all 3 are girls? Enter a fraction or decimal.', '{"answer":0.11904761904761904,"tolerance":0.001}', '["$ {}_5C_3 / {}_9C_3$."]', '$\frac{10}{84} = \frac{5}{42} \approx 0.119$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a9786b30caf43a', 'les_70fe875641de53', 6, 'review', 'numeric', 3, 'How many different arrangements of the letters in LEVEL are there?', '{"answer":30}', '["Divide 5! by the arrangements of the repeated letters: 2! for L and 2! for E."]', '$\frac{5!}{2!\,2!} = \frac{120}{4} = 30$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4ac32f433e991f', 'subj_math', 'counting', 'Counting principles', 'Factorials, permutations and combinations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_70fe875641de53', (SELECT id FROM concepts WHERE slug = 'counting'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_70fe875641de53', (SELECT id FROM formulas WHERE slug = 'permutations-combinations'), 1);

-- Lesson: points-lines-planes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ba34588db7e3a7', 'points-lines-planes', 'Points, lines and planes', 'Use the undefined terms point, line and plane, name figures with correct notation, and apply the basic postulates about how they intersect.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08a251f4bf4c81', 'les_ba34588db7e3a7', 1, 'Describe points, lines and planes and name them with standard notation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dd7c3a8d9c7b11', 'les_ba34588db7e3a7', 2, 'Distinguish lines, segments and rays, and identify collinear and coplanar points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b243039287e570', 'les_ba34588db7e3a7', 3, 'Apply postulates about intersections of lines and planes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08a251f4bf4c81', 'les_ba34588db7e3a7', 'learn', 1, 'text', '{"body":"Every definition uses other words, so some words must be left undefined. Geometry starts with three: point, line and plane. We describe them instead. A point is an exact location with no size. A line is a straight path of points extending forever in both directions with no thickness. A plane is a flat surface extending forever in every direction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd7c3a8d9c7b11', 'les_ba34588db7e3a7', 'learn', 2, 'definition', '{"term":"Notation","body":"A point is named by a capital letter, $A$. A line through $A$ and $B$ is $\\overleftrightarrow{AB}$ or a lowercase letter such as $\\ell$. A plane is named by a script capital, plane $\\mathcal{M}$, or by three noncollinear points, plane $ABC$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b243039287e570', 'les_ba34588db7e3a7', 'learn', 3, 'definition', '{"term":"Segments and rays","body":"Segment $\\overline{AB}$ is $A$, $B$ and all points between them. Ray $\\overrightarrow{AB}$ starts at endpoint $A$ and goes through $B$ forever. Opposite rays share an endpoint and point in opposite directions, forming a line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1f34523930403', 'les_ba34588db7e3a7', 'learn', 4, 'definition', '{"term":"Collinear and coplanar","body":"Points are collinear if one line contains them all, and coplanar if one plane contains them all. Any two points are collinear; any three points are coplanar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90d3fe6f18181a', 'les_ba34588db7e3a7', 'learn', 5, 'text', '{"body":"Postulates are statements accepted without proof. Through any two points there is exactly one line. Through any three noncollinear points there is exactly one plane. If two lines intersect, they meet in exactly one point. If two planes intersect, they meet in exactly one line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3fc0f0eb0037d', 'les_ba34588db7e3a7', 'learn', 6, 'worked_example', '{"title":"Name the figure in several ways","steps":[{"latex":"\\overrightarrow{PQ} \\ne \\overrightarrow{QP}","explanation":"Rays are named endpoint first, so these point in opposite directions."},{"latex":"\\overline{PQ} = \\overline{QP},\\quad \\overleftrightarrow{PQ} = \\overleftrightarrow{QP}","explanation":"Segments and lines can be named in either order."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffd68e08e35ad5', 'les_ba34588db7e3a7', 'learn', 7, 'worked_example', '{"title":"Two walls of a room meet the floor. Describe the intersections.","steps":[{"latex":"\\text{wall} \\cap \\text{floor} = \\text{a line}","explanation":"Two planes meet in a line, the edge where they meet."},{"latex":"\\text{wall}_1 \\cap \\text{wall}_2 \\cap \\text{floor} = \\text{a point}","explanation":"The corner of the room."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08428b80d6f6c7', 'les_ba34588db7e3a7', 'learn', 8, 'callout', '{"tone":"tip","title":"Why a three-legged stool doesn''t wobble","body":"Three noncollinear points determine exactly one plane, so the three feet always rest on the floor''s plane. A four-legged chair wobbles when its four feet don''t all lie in one plane."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d89339be6c11cc', 'les_ba34588db7e3a7', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Architects, video-game engines and CAD software describe every surface as pieces of planes and every edge as a segment. A 3D model is built from points (vertices), segments (edges) and plane regions (faces)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08a251f4bf4c81', 'les_ba34588db7e3a7', 1, 'practice', 'multiple_choice', 1, 'How many lines pass through two distinct points?', '{"choices":["None","Exactly one","Exactly two","Infinitely many"],"answer":1}', '["This is a postulate."]', 'Through any two points there is exactly one line.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd7c3a8d9c7b11', 'les_ba34588db7e3a7', 2, 'practice', 'multiple_choice', 1, 'Which name refers to a ray starting at $K$?', '{"choices":["$\\overrightarrow{JK}$","$\\overrightarrow{KJ}$","$\\overline{KJ}$","$\\overleftrightarrow{KJ}$"],"answer":1}', '["The endpoint is written first."]', '$\overrightarrow{KJ}$ starts at $K$ and passes through $J$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b243039287e570', 'les_ba34588db7e3a7', 3, 'practice', 'multiple_choice', 2, 'Two different planes intersect. What is their intersection?', '{"choices":["A point","A line","A plane","A segment"],"answer":1}', '["Think of two walls meeting."]', 'Two distinct intersecting planes meet in exactly one line.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1f34523930403', 'les_ba34588db7e3a7', 4, 'practice', 'multiple_choice', 2, 'Points $A$, $B$, $C$ lie on line $\ell$, and $D$ is not on $\ell$. Which statement is true?', '{"choices":["A, B, C, D are collinear","A, B, D are collinear","A, B, C, D are coplanar","No plane contains A, B and D"],"answer":2}', '["A line and a point not on it determine a plane."]', 'Line $\ell$ and point $D$ lie in exactly one plane, so all four points are coplanar. They are not collinear.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90d3fe6f18181a', 'les_ba34588db7e3a7', 5, 'practice', 'numeric', 2, 'How many planes contain three given noncollinear points?', '{"answer":1}', '["Postulate about three noncollinear points."]', 'Exactly one.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3fc0f0eb0037d', 'les_ba34588db7e3a7', 6, 'review', 'short_text', 3, 'What is the intersection of opposite rays $\overrightarrow{QP}$ and $\overrightarrow{QR}$? Enter the single letter of the point.', '{"accept":["Q","q"]}', '["Opposite rays share their endpoint."]', 'They share only their common endpoint, $Q$. Together they form line $PR$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffd68e08e35ad5', 'les_ba34588db7e3a7', 7, 'review', 'multiple_choice', 3, 'Is it possible for three planes to intersect in a single point?', '{"choices":["No, never","Yes, like two walls and a floor meeting at a corner","Only if they are parallel","Only if they are the same plane"],"answer":1}', '["Picture a corner of a room."]', 'Yes. Two walls and the floor meet at a corner point.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0c55256ee06e3b', 'subj_math', 'undefined-terms', 'Undefined terms', 'Point, line and plane: the basic objects that all other geometric definitions are built from.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ba34588db7e3a7', (SELECT id FROM concepts WHERE slug = 'undefined-terms'));

-- Lesson: points-of-concurrency
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_76c8096b0f9011', 'points-of-concurrency', 'Points of concurrency', 'Prove that a triangle''s perpendicular bisectors, angle bisectors, medians and altitudes are concurrent, locate the centers by coordinates, and explore the Euler line.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b75dd2e8767b79', 'les_76c8096b0f9011', 1, 'Prove the circumcenter and incenter theorems using the bisector theorems.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_62a16440922f64', 'les_76c8096b0f9011', 2, 'Find the circumcenter and centroid of a triangle in the coordinate plane.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_87baae6f3d6515', 'les_76c8096b0f9011', 3, 'Describe where each center lies for acute, right and obtuse triangles, and the Euler line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b75dd2e8767b79', 'les_76c8096b0f9011', 'learn', 1, 'text', '{"body":"Why should three lines meet at one point? For perpendicular bisectors: let the bisectors of $\\overline{AB}$ and $\\overline{BC}$ meet at $P$. Then $PA = PB$ and $PB = PC$, so $PA = PC$, which puts $P$ on the perpendicular bisector of $\\overline{AC}$ too. All three pass through $P$, the circumcenter, which is equidistant from all three vertices. The same argument with the Angle Bisector Theorem shows the angle bisectors meet at the incenter, equidistant from all three sides."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62a16440922f64', 'les_76c8096b0f9011', 'learn', 2, 'definition', '{"term":"Locations","body":"Centroid and incenter: always inside. Circumcenter and orthocenter: inside for acute triangles, on the triangle for right triangles (circumcenter at the midpoint of the hypotenuse, orthocenter at the right-angle vertex), outside for obtuse triangles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87baae6f3d6515', 'les_76c8096b0f9011', 'experiment', 3, 'activity', '{"activity":"triangle-explorer","title":"Compare all four centers","params":{"show":"perpendicular"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61ab00087e4fea', 'les_76c8096b0f9011', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Note the circumcenter''s coordinates, then switch to medians and altitudes and note those centers. The centroid always lies on the segment from the circumcenter to the orthocenter, one third of the way along it. That segment is the Euler line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d143700b66637', 'les_76c8096b0f9011', 'learn', 5, 'worked_example', '{"title":"Find the circumcenter of $A(0, 0)$, $B(8, 0)$, $C(0, 6)$","steps":[{"latex":"\\text{bisector of } \\overline{AB}: x = 4;\\ \\text{of } \\overline{AC}: y = 3","explanation":"These two sides are on the axes."},{"latex":"(4, 3)","explanation":"That''s the midpoint of the hypotenuse BC, as expected for a right triangle."},{"latex":"r = \\sqrt{16 + 9} = 5","explanation":"Circumradius: half the hypotenuse (10)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5f3a0c9954cc6', 'les_76c8096b0f9011', 'learn', 6, 'definition', '{"term":"Euler line","body":"In any non-equilateral triangle, the orthocenter $H$, centroid $G$ and circumcenter $O$ are collinear, with $HG = 2 \\cdot GO$. (The incenter generally isn''t on this line.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bfe6a870ce36e', 'les_76c8096b0f9011', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Circumcenters solve \"equidistant from three locations\" problems (placing a cell tower or a fire station); incenters find the largest circular fountain that fits a triangular plaza; centroids balance triangular plates."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b75dd2e8767b79', 'les_76c8096b0f9011', 1, 'practice', 'short_text', 2, 'Find the centroid of $(2, 1)$, $(8, 1)$, $(5, 7)$. Enter as (x,y).', '{"accept":["(5,3)"]}', '[]', '$\left(\frac{15}{3}, \frac{9}{3}\right) = (5, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62a16440922f64', 'les_76c8096b0f9011', 2, 'practice', 'short_text', 2, 'Find the circumcenter of the right triangle $(0, 0)$, $(10, 0)$, $(0, 4)$. Enter as (x,y).', '{"accept":["(5,2)"]}', '["Midpoint of the hypotenuse."]', '$(5, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87baae6f3d6515', 'les_76c8096b0f9011', 3, 'practice', 'multiple_choice', 2, 'Which center is always equidistant from the three sides?', '{"choices":["Centroid","Circumcenter","Incenter","Orthocenter"],"answer":2}', '[]', 'The incenter.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_61ab00087e4fea', 'les_76c8096b0f9011', 4, 'practice', 'multiple_choice', 2, 'For an obtuse triangle, which center lies outside?', '{"choices":["Centroid","Incenter","Circumcenter","None"],"answer":2}', '[]', 'The circumcenter (and the orthocenter) lie outside an obtuse triangle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3d143700b66637', 'les_76c8096b0f9011', 5, 'review', 'numeric', 3, 'On an Euler line, the distance from the orthocenter to the circumcenter is 12. How far is the centroid from the circumcenter?', '{"answer":4}', '["$HG = 2\\,GO$ and $HG + GO = 12$."]', '$3\,GO = 12$, so $GO = 4$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bb97e906a29bc3', 'subj_math', 'triangle-centers', 'Triangle centers', 'Centroid, orthocenter, incenter and circumcenter: where special segments of a triangle meet.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_76c8096b0f9011', (SELECT id FROM concepts WHERE slug = 'triangle-centers'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_76c8096b0f9011', (SELECT id FROM formulas WHERE slug = 'midpoint-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_76c8096b0f9011', (SELECT id FROM formulas WHERE slug = 'distance-formula'), 2);

-- Lesson: polygon-angle-sums
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7f5d8208a0fe55', 'polygon-angle-sums', 'Polygon angle sums', 'Find the sum of the interior angles of any polygon, the measure of each angle of a regular polygon, and use the fact that exterior angles sum to 360°.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4d6b83efa53cf', 'les_7f5d8208a0fe55', 1, 'Derive the interior angle sum (n − 2) · 180° by dividing a polygon into triangles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_14de5e73074d46', 'les_7f5d8208a0fe55', 2, 'Find each interior and exterior angle of a regular polygon.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f78407c890efa', 'les_7f5d8208a0fe55', 3, 'Find the number of sides of a regular polygon from an angle measure.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4d6b83efa53cf', 'les_7f5d8208a0fe55', 'learn', 1, 'definition', '{"term":"Polygon vocabulary","body":"A polygon is a closed plane figure made of segments. It is convex if no segment between two of its points goes outside it. A regular polygon has all sides congruent and all angles congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14de5e73074d46', 'les_7f5d8208a0fe55', 'learn', 2, 'text', '{"body":"Pick one vertex of a convex $n$-gon and draw every diagonal from it. That cuts the polygon into $n - 2$ triangles, and their angles together make up exactly the polygon''s angles. Each triangle contributes $180^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f78407c890efa', 'les_7f5d8208a0fe55', 'learn', 3, 'formula', '{"latex":"S = (n - 2) \\cdot 180^\\circ","title":"Interior angle sum"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1c594c30f75b4', 'les_7f5d8208a0fe55', 'learn', 4, 'text', '{"body":"Walk around a convex polygon, turning at each corner by its exterior angle. After one full lap you face your starting direction, having turned exactly $360^\\circ$. So the exterior angles (one per vertex) always sum to $360^\\circ$, for any number of sides."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce33dcb910e29d', 'les_7f5d8208a0fe55', 'learn', 5, 'worked_example', '{"title":"Find the interior angle sum of a decagon and each angle of a regular decagon","steps":[{"latex":"S = (10 - 2) \\cdot 180^\\circ = 1440^\\circ","explanation":""},{"latex":"1440^\\circ \\div 10 = 144^\\circ","explanation":"Or: each exterior angle is $360 \\div 10 = 36^\\circ$, and $180 - 36 = 144^\\circ$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22c9b720018508', 'les_7f5d8208a0fe55', 'learn', 6, 'worked_example', '{"title":"Each interior angle of a regular polygon is $156^\\circ$. How many sides does it have?","steps":[{"latex":"180 - 156 = 24^\\circ","explanation":"Each exterior angle."},{"latex":"n = 360 \\div 24 = 15","explanation":"A 15-gon."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56a533355e18ef', 'les_7f5d8208a0fe55', 'learn', 7, 'callout', '{"tone":"tip","title":"Use exterior angles","body":"Questions about regular polygons are usually fastest with exterior angles: each is $\\frac{360^\\circ}{n}$, and the interior angle is $180^\\circ$ minus that."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1bd36bf248ce1', 'les_7f5d8208a0fe55', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Only equilateral triangles, squares and regular hexagons tile a floor by themselves, because only their interior angles (60°, 90°, 120°) divide $360^\\circ$ evenly. Honeycombs use hexagons for this reason."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4d6b83efa53cf', 'les_7f5d8208a0fe55', 1, 'practice', 'numeric', 1, 'Find the interior angle sum of a hexagon.', '{"answer":720,"unit":"°"}', '["$(6 - 2) \\cdot 180$."]', '$720^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14de5e73074d46', 'les_7f5d8208a0fe55', 2, 'practice', 'numeric', 1, 'Find each exterior angle of a regular octagon.', '{"answer":45,"unit":"°"}', '[]', '$360 \div 8 = 45^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f78407c890efa', 'les_7f5d8208a0fe55', 3, 'practice', 'numeric', 2, 'Find each interior angle of a regular pentagon.', '{"answer":108,"unit":"°"}', '[]', '$540 \div 5 = 108^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1c594c30f75b4', 'les_7f5d8208a0fe55', 4, 'practice', 'numeric', 2, 'Each exterior angle of a regular polygon is $20^\circ$. How many sides does it have?', '{"answer":18}', '[]', '$360 \div 20 = 18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ce33dcb910e29d', 'les_7f5d8208a0fe55', 5, 'practice', 'numeric', 2, 'Four angles of a pentagon measure $100^\circ$, $115^\circ$, $96^\circ$ and $120^\circ$. Find the fifth.', '{"answer":109,"unit":"°"}', '["The sum is 540°."]', '$540 - 431 = 109^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22c9b720018508', 'les_7f5d8208a0fe55', 6, 'review', 'multiple_choice', 3, 'Can a regular polygon have interior angles of $130^\circ$?', '{"choices":["Yes, with 8 sides","Yes, with 9 sides","No","Yes, with 7 sides"],"answer":2}', '["Find 360 divided by the exterior angle."]', 'The exterior angle would be $50^\circ$, and $360 \div 50 = 7.2$ isn''t a whole number, so no.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_56a533355e18ef', 'les_7f5d8208a0fe55', 7, 'review', 'numeric', 3, 'The interior angle sum of a polygon is $2340^\circ$. How many sides does it have?', '{"answer":15}', '["$(n - 2) \\cdot 180 = 2340$."]', '$n - 2 = 13$, so $n = 15$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_276e9c42fa9d7f', 'subj_math', 'polygon-angles', 'Polygon angles', 'Interior angles of an n-gon sum to (n − 2)·180°; exterior angles sum to 360°.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7f5d8208a0fe55', (SELECT id FROM concepts WHERE slug = 'polygon-angles'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7f5d8208a0fe55', (SELECT id FROM formulas WHERE slug = 'polygon-angle-sum'), 1);

-- Lesson: properties-of-parallelograms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c9805cdd355857', 'properties-of-parallelograms', 'Properties of parallelograms', 'Use the side, angle and diagonal properties of parallelograms, and prove that a quadrilateral is a parallelogram.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f2767b0e8ea133', 'les_c9805cdd355857', 1, 'State and use the properties of parallelograms: opposite sides and angles congruent, consecutive angles supplementary, diagonals bisect each other.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e1a4f29af94b4b', 'les_c9805cdd355857', 2, 'Solve for unknowns using these properties.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a16e690d635ff', 'les_c9805cdd355857', 3, 'Prove a quadrilateral is a parallelogram using one of the standard tests.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f2767b0e8ea133', 'les_c9805cdd355857', 'learn', 1, 'definition', '{"term":"Parallelogram","body":"A quadrilateral with both pairs of opposite sides parallel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1a4f29af94b4b', 'les_c9805cdd355857', 'learn', 2, 'definition', '{"term":"Properties","body":"In a parallelogram: opposite sides are congruent; opposite angles are congruent; consecutive angles are supplementary; the diagonals bisect each other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a16e690d635ff', 'les_c9805cdd355857', 'learn', 3, 'text', '{"body":"Why? Draw diagonal $\\overline{AC}$ in parallelogram $ABCD$. The parallel sides give two pairs of congruent alternate interior angles, and $\\overline{AC}$ is shared, so $\\triangle ABC \\cong \\triangle CDA$ by ASA. By CPCTC, opposite sides and opposite angles are congruent. Consecutive angles are same-side interior angles between parallel lines, so they''re supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_813ce141471108', 'les_c9805cdd355857', 'learn', 4, 'worked_example', '{"title":"In parallelogram $ABCD$, $m\\angle A = (3x + 15)^\\circ$ and $m\\angle B = (5x - 3)^\\circ$. Find each angle.","steps":[{"latex":"3x + 15 + 5x - 3 = 180","explanation":"Consecutive angles are supplementary."},{"latex":"8x + 12 = 180 \\Rightarrow x = 21","explanation":""},{"latex":"m\\angle A = 78^\\circ,\\ m\\angle B = 102^\\circ","explanation":""},{"latex":"m\\angle C = 78^\\circ,\\ m\\angle D = 102^\\circ","explanation":"Opposite angles are congruent."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13e4600a7b9d95', 'les_c9805cdd355857', 'learn', 5, 'worked_example', '{"title":"The diagonals of parallelogram $PQRS$ meet at $T$. $PT = 2y + 1$ and $TR = 4y - 7$. Find $PR$.","steps":[{"latex":"2y + 1 = 4y - 7 \\Rightarrow y = 4","explanation":"Diagonals bisect each other."},{"latex":"PT = 9,\\ PR = 18","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c89d16be16c0cb', 'les_c9805cdd355857', 'learn', 6, 'definition', '{"term":"Proving a quadrilateral is a parallelogram","body":"It''s enough to show any one of: both pairs of opposite sides parallel; both pairs of opposite sides congruent; both pairs of opposite angles congruent; the diagonals bisect each other; or one pair of opposite sides both parallel and congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e1c19fc8a9222', 'les_c9805cdd355857', 'learn', 7, 'callout', '{"tone":"warning","title":"One pair isn''t enough (usually)","body":"One pair of parallel sides makes a trapezoid. One pair of congruent sides proves nothing by itself. The exception: one pair that is both parallel and congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0b70df2fdbb39', 'les_c9805cdd355857', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scissor lifts, folding gates and car-jack linkages are parallelograms: as they move, opposite sides stay parallel, which keeps a platform level."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f2767b0e8ea133', 'les_c9805cdd355857', 1, 'practice', 'numeric', 1, 'In a parallelogram one angle measures $65^\circ$. What is the measure of a consecutive angle?', '{"answer":115,"unit":"°"}', '[]', '$180 - 65 = 115^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1a4f29af94b4b', 'les_c9805cdd355857', 2, 'practice', 'numeric', 2, 'In parallelogram $ABCD$, $AB = 3x - 2$ and $CD = x + 12$. Find $AB$.', '{"answer":19}', '["Opposite sides are congruent."]', '$x = 7$, so $AB = 19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a16e690d635ff', 'les_c9805cdd355857', 3, 'practice', 'numeric', 2, 'The diagonals of a parallelogram meet at $M$. One diagonal has halves $5n$ and $n + 12$. Find the length of that diagonal.', '{"answer":30}', '[]', '$5n = n + 12$, $n = 3$, halves are 15, so the diagonal is 30.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_813ce141471108', 'les_c9805cdd355857', 4, 'practice', 'multiple_choice', 2, 'Which is NOT always true of a parallelogram?', '{"choices":["Opposite sides are congruent","Diagonals bisect each other","Diagonals are congruent","Opposite angles are congruent"],"answer":2}', '[]', 'Congruent diagonals happen only in rectangles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13e4600a7b9d95', 'les_c9805cdd355857', 5, 'review', 'multiple_choice', 3, 'Which information proves $ABCD$ is a parallelogram?', '{"choices":["$AB = CD$ and $BC \\parallel AD$","$AB \\parallel CD$ and $AB = CD$","$\\angle A \\cong \\angle C$ only","$AC = BD$"],"answer":1}', '[]', 'One pair of opposite sides that is both parallel and congruent is enough. Option A can describe an isosceles trapezoid.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c3728e59bab7b0', 'subj_math', 'parallelograms', 'Parallelograms', 'Quadrilaterals with both pairs of opposite sides parallel.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c9805cdd355857', (SELECT id FROM concepts WHERE slug = 'parallelograms'));

-- Lesson: proportions-in-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d0961b0a5339e7', 'proportions-in-triangles', 'Proportions in triangles', 'Use the Triangle Proportionality Theorem, the Triangle Midsegment Theorem, parallel lines cutting transversals proportionally, and the Triangle Angle Bisector Theorem.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ac944de41745d', 'les_d0961b0a5339e7', 1, 'Apply the Triangle Proportionality Theorem and its converse.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c61a66c8faafb', 'les_d0961b0a5339e7', 2, 'Use the Triangle Midsegment Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ae6e17c4c8e728', 'les_d0961b0a5339e7', 3, 'Apply the Triangle Angle Bisector Theorem and proportional segments formed by parallel lines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ac944de41745d', 'les_d0961b0a5339e7', 'learn', 1, 'definition', '{"term":"Triangle Proportionality Theorem","body":"If a line parallel to one side of a triangle meets the other two sides, it divides them proportionally: if $\\overline{DE} \\parallel \\overline{BC}$, then $\\frac{AD}{DB} = \\frac{AE}{EC}$. The converse is also true."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c61a66c8faafb', 'les_d0961b0a5339e7', 'learn', 2, 'worked_example', '{"title":"$\\overline{DE} \\parallel \\overline{BC}$, $AD = 6$, $DB = 4$, $AE = 9$. Find $EC$.","steps":[{"latex":"\\tfrac{6}{4} = \\tfrac{9}{EC}","explanation":""},{"latex":"EC = 6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ae6e17c4c8e728', 'les_d0961b0a5339e7', 'learn', 3, 'definition', '{"term":"Triangle Midsegment Theorem","body":"The segment joining the midpoints of two sides of a triangle is parallel to the third side and half as long."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f51f7c4bebe197', 'les_d0961b0a5339e7', 'learn', 4, 'definition', '{"term":"Parallel lines and transversals","body":"If three or more parallel lines cut two transversals, they divide the transversals proportionally."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd8a1d68494fb6', 'les_d0961b0a5339e7', 'learn', 5, 'definition', '{"term":"Triangle Angle Bisector Theorem","body":"An angle bisector of a triangle divides the opposite side into segments proportional to the other two sides: if $\\overline{AD}$ bisects $\\angle A$ in $\\triangle ABC$, then $\\frac{BD}{DC} = \\frac{AB}{AC}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_846c0e17804d65', 'les_d0961b0a5339e7', 'learn', 6, 'worked_example', '{"title":"In $\\triangle ABC$, $AB = 12$, $AC = 18$ and $BC = 20$. The bisector of $\\angle A$ meets $\\overline{BC}$ at $D$. Find $BD$.","steps":[{"latex":"\\tfrac{BD}{DC} = \\tfrac{12}{18} = \\tfrac{2}{3}","explanation":""},{"latex":"BD = \\tfrac{2}{5} \\cdot 20 = 8,\\ DC = 12","explanation":"20 splits in the ratio 2 : 3."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf34790ce29595', 'les_d0961b0a5339e7', 'learn', 7, 'callout', '{"tone":"warning","title":"Segments of a side, not the whole side","body":"The proportion $\\frac{AD}{DB} = \\frac{AE}{EC}$ uses the pieces of each side. If you want $DE$ itself, use similar triangles: $\\frac{DE}{BC} = \\frac{AD}{AB}$, with whole sides."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c35c8db989542c', 'les_d0961b0a5339e7', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Parallel streets crossing two avenues divide the blocks proportionally, which surveyors use to split land. Artists use these proportions in perspective drawing."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ac944de41745d', 'les_d0961b0a5339e7', 1, 'practice', 'numeric', 1, '$\overline{DE} \parallel \overline{BC}$, $AD = 5$, $DB = 10$, $AE = 4$. Find $EC$.', '{"answer":8}', '[]', '$\frac{5}{10} = \frac{4}{EC}$ gives $EC = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c61a66c8faafb', 'les_d0961b0a5339e7', 2, 'practice', 'numeric', 2, 'A midsegment of a triangle is parallel to a side of length 26. How long is the midsegment?', '{"answer":13}', '[]', 'Half: 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ae6e17c4c8e728', 'les_d0961b0a5339e7', 3, 'practice', 'numeric', 2, 'The bisector of $\angle A$ in $\triangle ABC$ splits $\overline{BC}$ into $BD = 6$ and $DC = 9$. If $AB = 10$, find $AC$.', '{"answer":15}', '["$\\frac{6}{9} = \\frac{10}{AC}$."]', '$AC = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f51f7c4bebe197', 'les_d0961b0a5339e7', 4, 'practice', 'numeric', 2, 'Three parallel lines cut one transversal into segments 4 and 6, and another transversal into segments 10 and $x$. Find $x$.', '{"answer":15}', '[]', '$\frac{4}{6} = \frac{10}{x}$, $x = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd8a1d68494fb6', 'les_d0961b0a5339e7', 5, 'review', 'multiple_choice', 3, 'In $\triangle ABC$, $D$ is on $\overline{AB}$ with $AD = 3$, $DB = 5$, and $E$ is on $\overline{AC}$ with $AE = 4.5$, $EC = 7.5$. Is $\overline{DE} \parallel \overline{BC}$?', '{"choices":["Yes","No","Cannot tell","Only if ABC is isosceles"],"answer":0}', '["Compare $\\frac{3}{5}$ and $\\frac{4.5}{7.5}$."]', 'Both equal 0.6, so by the converse, $\overline{DE} \parallel \overline{BC}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3941da996c7bba', 'subj_math', 'similarity', 'Similarity', 'Figures with the same shape: corresponding angles congruent and corresponding sides proportional.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d0961b0a5339e7', (SELECT id FROM concepts WHERE slug = 'similarity'));

-- Lesson: proving-lines-parallel
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_97ffb9f3d840ae', 'proving-lines-parallel', 'Proving lines parallel', 'Use the converses of the parallel-line angle theorems to prove two lines are parallel, and find values that make lines parallel.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_36783b3dc6297a', 'les_97ffb9f3d840ae', 1, 'State the converses of the corresponding, alternate interior, alternate exterior and same-side interior angle theorems.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d13ecbdc124b25', 'les_97ffb9f3d840ae', 2, 'Decide which lines in a figure are parallel from given angle measures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8dd6d36bb26adb', 'les_97ffb9f3d840ae', 3, 'Find the value of a variable that makes two lines parallel, and prove lines parallel.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36783b3dc6297a', 'les_97ffb9f3d840ae', 'learn', 1, 'text', '{"body":"The previous lesson started with parallel lines and concluded things about angles. Now go the other way: if the angles have the right relationship, the lines must be parallel. These converses are how you prove lines are parallel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d13ecbdc124b25', 'les_97ffb9f3d840ae', 'learn', 2, 'definition', '{"term":"Converses","body":"If two lines are cut by a transversal so that any of these hold, the lines are parallel: corresponding angles are congruent; alternate interior angles are congruent; alternate exterior angles are congruent; same-side interior angles are supplementary."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8dd6d36bb26adb', 'les_97ffb9f3d840ae', 'learn', 3, 'definition', '{"term":"Other parallel theorems","body":"Two lines parallel to the same line are parallel to each other. Two lines perpendicular to the same line (in a plane) are parallel to each other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f26f732fa46cca', 'les_97ffb9f3d840ae', 'learn', 4, 'worked_example', '{"title":"Find $x$ so that lines $\\ell$ and $m$ are parallel, if corresponding angles measure $(4x - 7)^\\circ$ and $(2x + 31)^\\circ$.","steps":[{"latex":"4x - 7 = 2x + 31","explanation":"Converse of the Corresponding Angles Postulate."},{"latex":"x = 19","explanation":"Both angles are 69°, so ℓ ∥ m."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f8f8f076b1e5e', 'les_97ffb9f3d840ae', 'learn', 5, 'worked_example', '{"title":"Two lines are cut by a transversal, and same-side interior angles measure $75^\\circ$ and $105^\\circ$. Are the lines parallel?","steps":[{"latex":"75 + 105 = 180","explanation":"Same-side interior angles are supplementary."},{"latex":"\\text{yes, the lines are parallel}","explanation":"Converse of the Same-Side Interior Angles Theorem."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f37d9bec9dfe5', 'les_97ffb9f3d840ae', 'learn', 6, 'callout', '{"tone":"warning","title":"Pick the right pair of lines","body":"In a figure with several lines, congruent angles prove parallel only the two lines that the transversal crosses to form those angles. Trace the angle''s sides to see which lines they lie on."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0fae67bf375a4c', 'les_97ffb9f3d840ae', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Builders check that walls are parallel by measuring the angles a crossing beam makes with each. Surveyors verify that property lines are parallel the same way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36783b3dc6297a', 'les_97ffb9f3d840ae', 1, 'practice', 'numeric', 1, 'Alternate interior angles measure $(3x + 12)^\circ$ and $(5x - 20)^\circ$. What value of $x$ makes the lines parallel?', '{"answer":16}', '["Set the angles equal."]', '$2x = 32$, $x = 16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d13ecbdc124b25', 'les_97ffb9f3d840ae', 2, 'practice', 'numeric', 2, 'Same-side interior angles measure $(2x + 10)^\circ$ and $(3x - 5)^\circ$. What value of $x$ makes the lines parallel?', '{"answer":35}', '["They must be supplementary."]', '$5x + 5 = 180$, $x = 35$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8dd6d36bb26adb', 'les_97ffb9f3d840ae', 3, 'practice', 'multiple_choice', 2, 'Corresponding angles measure $72^\circ$ and $78^\circ$. What can you conclude?', '{"choices":["The lines are parallel","The lines are not parallel","The lines are perpendicular","Nothing"],"answer":1}', '["If the lines were parallel, the angles would be equal."]', 'If the lines were parallel, corresponding angles would be congruent. They aren''t, so the lines are not parallel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f26f732fa46cca', 'les_97ffb9f3d840ae', 4, 'practice', 'multiple_choice', 2, 'Lines $a$ and $b$ are both perpendicular to line $c$ in the same plane. What is true?', '{"choices":["$a \\perp b$","$a \\parallel b$","$a = c$","Nothing can be concluded"],"answer":1}', '[]', 'Two lines perpendicular to the same line are parallel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f8f8f076b1e5e', 'les_97ffb9f3d840ae', 5, 'review', 'multiple_choice', 3, 'Which condition does NOT prove two lines parallel?', '{"choices":["Alternate interior angles congruent","Corresponding angles congruent","Same-side interior angles congruent","Alternate exterior angles congruent"],"answer":2}', '["Same-side interior angles need a different relationship."]', 'Same-side interior angles must be supplementary. They are congruent only if both are $90^\circ$, which isn''t guaranteed.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2a1d821979eb41', 'subj_math', 'parallel-lines', 'Parallel lines and transversals', 'Angle relationships formed when a transversal crosses two parallel lines.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_97ffb9f3d840ae', (SELECT id FROM concepts WHERE slug = 'parallel-lines'));

-- Lesson: proving-triangles-similar
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_903caa07c60616', 'proving-triangles-similar', 'Proving triangles similar', 'Prove triangles similar with AA, SSS and SAS similarity, and use similar triangles for indirect measurement.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_36b947aefe73bd', 'les_903caa07c60616', 1, 'State and apply the AA, SSS and SAS similarity criteria.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_44bba22c77a8c3', 'les_903caa07c60616', 2, 'Write similarity proofs, including overlapping triangles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5df42a8581ba8e', 'les_903caa07c60616', 3, 'Use similar triangles to measure heights and distances indirectly.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_36b947aefe73bd', 'les_903caa07c60616', 'learn', 1, 'definition', '{"term":"AA similarity","body":"If two angles of one triangle are congruent to two angles of another, the triangles are similar. (The third angles match automatically.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44bba22c77a8c3', 'les_903caa07c60616', 'learn', 2, 'definition', '{"term":"SSS and SAS similarity","body":"SSS~: all three pairs of corresponding sides are proportional. SAS~: two pairs of sides are proportional and the included angles are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5df42a8581ba8e', 'les_903caa07c60616', 'learn', 3, 'text', '{"body":"Why does AA work? Dilate the smaller triangle so one side matches the larger triangle''s corresponding side. Now the two triangles have two congruent angles and the included side congruent, so they''re congruent by ASA. Undo the dilation: the originals were similar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8384b91f433d23', 'les_903caa07c60616', 'learn', 4, 'worked_example', '{"title":"$\\overline{DE} \\parallel \\overline{BC}$ in $\\triangle ABC$, with $D$ on $\\overline{AB}$ and $E$ on $\\overline{AC}$. Show $\\triangle ADE \\sim \\triangle ABC$.","steps":[{"latex":"\\angle A \\cong \\angle A","explanation":"Reflexive."},{"latex":"\\angle ADE \\cong \\angle ABC","explanation":"Corresponding angles (DE ∥ BC)."},{"latex":"\\triangle ADE \\sim \\triangle ABC","explanation":"AA."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_efb7ede8a0a7eb', 'les_903caa07c60616', 'learn', 5, 'worked_example', '{"title":"Are triangles with sides 6, 8, 10 and 9, 12, 15 similar?","steps":[{"latex":"\\tfrac{9}{6} = \\tfrac{12}{8} = \\tfrac{15}{10} = 1.5","explanation":"Compare shortest to shortest, and so on."},{"latex":"\\text{similar by SSS}\\sim","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d010ec3dd0018', 'les_903caa07c60616', 'learn', 6, 'worked_example', '{"title":"A 1.8 m person casts a 2.4 m shadow while a tree casts a 16 m shadow. How tall is the tree?","steps":[{"latex":"\\tfrac{h}{16} = \\tfrac{1.8}{2.4}","explanation":"The sun''s rays make equal angles: AA similar right triangles."},{"latex":"h = 16 \\cdot 0.75 = 12 \\text{ m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49ae43679549c5', 'les_903caa07c60616', 'learn', 7, 'callout', '{"tone":"warning","title":"Order the sides","body":"When testing SSS~, match smallest with smallest, middle with middle and largest with largest. Pairing them in another order can make similar triangles look non-similar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7c6629fd116c2', 'les_903caa07c60616', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Indirect measurement with shadows or mirrors goes back to Thales measuring the Great Pyramid. Cameras, pinhole projectors and the human eye form similar triangles between object and image."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_36b947aefe73bd', 'les_903caa07c60616', 1, 'practice', 'multiple_choice', 1, 'Two triangles each have angles of $35^\circ$ and $80^\circ$. Are they similar?', '{"choices":["Yes, by AA","No","Only if a side matches","Yes, by SSS"],"answer":0}', '[]', 'Two pairs of congruent angles: AA.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44bba22c77a8c3', 'les_903caa07c60616', 2, 'practice', 'multiple_choice', 2, 'Which pair of triangles is similar? (Side lengths given.)', '{"choices":["4, 6, 8 and 6, 9, 12","3, 4, 5 and 4, 5, 6","5, 5, 8 and 10, 10, 12","2, 3, 4 and 4, 6, 9"],"answer":0}', '["Check that all three ratios are equal."]', '$\frac{6}{4} = \frac{9}{6} = \frac{12}{8} = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5df42a8581ba8e', 'les_903caa07c60616', 3, 'practice', 'numeric', 2, 'In $\triangle ABC$, $\overline{DE} \parallel \overline{BC}$ with $AD = 4$, $DB = 6$, $DE = 5$. Find $BC$.', '{"answer":12.5}', '["AB = 10.","$\\frac{BC}{DE} = \\frac{AB}{AD}$."]', '$BC = 5 \cdot \frac{10}{4} = 12.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8384b91f433d23', 'les_903caa07c60616', 4, 'practice', 'numeric', 2, 'A 2 m pole casts a 3 m shadow when a building casts a 45 m shadow. How tall is the building?', '{"answer":30,"unit":"m"}', '[]', '$45 \cdot \frac{2}{3} = 30$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_efb7ede8a0a7eb', 'les_903caa07c60616', 5, 'review', 'multiple_choice', 3, '$\triangle PQR$ has $PQ = 8$, $PR = 12$, $\angle P = 50^\circ$. $\triangle XYZ$ has $XY = 10$, $XZ = 15$, $\angle X = 50^\circ$. Are they similar?', '{"choices":["Yes, SAS~","Yes, SSS~","No","Yes, AA"],"answer":0}', '["$\\frac{10}{8} = \\frac{15}{12}$?"]', 'Both ratios are 1.25 and the included angles are equal: SAS~.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3941da996c7bba', 'subj_math', 'similarity', 'Similarity', 'Figures with the same shape: corresponding angles congruent and corresponding sides proportional.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_903caa07c60616', (SELECT id FROM concepts WHERE slug = 'similarity'));

-- Lesson: rectangles-rhombuses-squares
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_252cd103fb8493', 'rectangles-rhombuses-squares', 'Rectangles, rhombuses and squares', 'Use the special diagonal properties of rectangles, rhombuses and squares, and classify quadrilaterals from their properties or coordinates.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8275391a03edea', 'les_252cd103fb8493', 1, 'Define rectangles, rhombuses and squares as special parallelograms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d64f204ecf6b57', 'les_252cd103fb8493', 2, 'Use diagonal properties: congruent diagonals (rectangle), perpendicular diagonals that bisect the angles (rhombus).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68e00f4eec316c', 'les_252cd103fb8493', 3, 'Classify a parallelogram from given information or coordinates.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8275391a03edea', 'les_252cd103fb8493', 'learn', 1, 'definition', '{"term":"Definitions","body":"A rectangle is a parallelogram with four right angles. A rhombus is a parallelogram with four congruent sides. A square is both a rectangle and a rhombus. Each has every property of a parallelogram."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d64f204ecf6b57', 'les_252cd103fb8493', 'learn', 2, 'definition', '{"term":"Diagonal theorems","body":"A parallelogram is a rectangle if and only if its diagonals are congruent. A parallelogram is a rhombus if and only if its diagonals are perpendicular, and also if and only if each diagonal bisects a pair of opposite angles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68e00f4eec316c', 'les_252cd103fb8493', 'learn', 3, 'text', '{"body":"Why are a rhombus''s diagonals perpendicular? Each vertex at the end of one diagonal is equidistant from the endpoints of the other diagonal (all sides are equal). By the Perpendicular Bisector Theorem, the first diagonal is the perpendicular bisector of the second."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b998333626a6b4', 'les_252cd103fb8493', 'learn', 4, 'worked_example', '{"title":"In rectangle $ABCD$, $AC = 4x - 6$ and $BD = 2x + 10$. Find $AC$.","steps":[{"latex":"4x - 6 = 2x + 10 \\Rightarrow x = 8","explanation":"Diagonals of a rectangle are congruent."},{"latex":"AC = 26","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb569a2b197456', 'les_252cd103fb8493', 'learn', 5, 'worked_example', '{"title":"Rhombus $PQRS$ has diagonals of 10 and 24. Find its side length.","steps":[{"latex":"\\text{half-diagonals: } 5 \\text{ and } 12","explanation":"Diagonals bisect each other at right angles."},{"latex":"s = \\sqrt{5^2 + 12^2} = 13","explanation":"Each side is the hypotenuse of a right triangle."}],"check":"The area of a rhombus is half the product of its diagonals: ½ · 10 · 24 = 120."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c88d0d03d91b4c', 'les_252cd103fb8493', 'learn', 6, 'worked_example', '{"title":"Classify $A(1, 2)$, $B(4, 6)$, $C(8, 3)$, $D(5, -1)$","steps":[{"latex":"AB = BC = CD = DA = 5","explanation":"All sides equal: at least a rhombus."},{"latex":"m_{AB} = \\tfrac{4}{3},\\ m_{BC} = -\\tfrac{3}{4}","explanation":"Product −1: a right angle."},{"latex":"\\text{square}","explanation":"A rhombus with a right angle is a square."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd9de6a843e774', 'les_252cd103fb8493', 'learn', 7, 'callout', '{"tone":"warning","title":"Every square is a rectangle, not vice versa","body":"Think in terms of nested sets: squares ⊂ rectangles ⊂ parallelograms and squares ⊂ rhombuses ⊂ parallelograms. A property true of all rectangles is true of squares too."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c345f4b3419838', 'les_252cd103fb8493', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Builders check that a frame is square by measuring both diagonals: if they''re equal, the parallelogram is a rectangle. Rhombus-shaped linkages and diamond patterns use the perpendicular diagonals."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8275391a03edea', 'les_252cd103fb8493', 1, 'practice', 'multiple_choice', 1, 'Which quadrilateral always has perpendicular diagonals?', '{"choices":["Rectangle","Rhombus","Parallelogram","Trapezoid"],"answer":1}', '[]', 'Rhombus (and therefore square).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d64f204ecf6b57', 'les_252cd103fb8493', 2, 'practice', 'numeric', 2, 'In rectangle $WXYZ$, $WY = 7a - 2$ and $XZ = 4a + 13$. Find $WY$.', '{"answer":33}', '["Diagonals are congruent."]', '$a = 5$, $WY = 33$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68e00f4eec316c', 'les_252cd103fb8493', 3, 'practice', 'numeric', 2, 'A rhombus has diagonals 16 and 30. Find its side length.', '{"answer":17}', '["Half-diagonals 8 and 15."]', '$\sqrt{64 + 225} = 17$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b998333626a6b4', 'les_252cd103fb8493', 4, 'practice', 'numeric', 2, 'In rhombus $ABCD$, $m\angle ABC = 110^\circ$. Diagonal $\overline{BD}$ bisects it. Find $m\angle ABD$.', '{"answer":55,"unit":"°"}', '[]', '$110 \div 2 = 55^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb569a2b197456', 'les_252cd103fb8493', 5, 'review', 'multiple_choice', 3, 'A parallelogram has congruent diagonals that are also perpendicular. What is it?', '{"choices":["Rectangle only","Rhombus only","Square","Kite"],"answer":2}', '["Congruent → rectangle; perpendicular → rhombus."]', 'Both a rectangle and a rhombus: a square.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3e99d69d6e8ab6', 'subj_math', 'special-parallelograms', 'Special parallelograms', 'Rectangles, rhombuses and squares and their diagonal properties.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_252cd103fb8493', (SELECT id FROM concepts WHERE slug = 'special-parallelograms'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_252cd103fb8493', (SELECT id FROM formulas WHERE slug = 'slope'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_252cd103fb8493', (SELECT id FROM formulas WHERE slug = 'distance-formula'), 2);

-- Lesson: reflections
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_aa07aeed128c22', 'reflections', 'Reflections', 'Reflect figures across the axes and the lines y = x and y = −x, describe reflections with coordinate rules, and find lines of symmetry.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_df693f1a77a93a', 'les_aa07aeed128c22', 1, 'Define a reflection using the perpendicular bisector.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a60912e104858', 'les_aa07aeed128c22', 2, 'Use coordinate rules for reflections across the x-axis, y-axis, y = x and y = −x, and across horizontal or vertical lines.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_193b3ac9113a5f', 'les_aa07aeed128c22', 3, 'Identify lines of symmetry and explain how reflections change orientation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df693f1a77a93a', 'les_aa07aeed128c22', 'learn', 1, 'definition', '{"term":"Reflection","body":"A reflection across line $\\ell$ maps each point $P$ to $P''$ so that $\\ell$ is the perpendicular bisector of $\\overline{PP''}$. Points on $\\ell$ stay where they are."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a60912e104858', 'les_aa07aeed128c22', 'learn', 2, 'definition', '{"term":"Coordinate rules","body":"Across the $x$-axis: $(x, y) \\to (x, -y)$. Across the $y$-axis: $(x, y) \\to (-x, y)$. Across $y = x$: $(x, y) \\to (y, x)$. Across $y = -x$: $(x, y) \\to (-y, -x)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_193b3ac9113a5f', 'les_aa07aeed128c22', 'experiment', 3, 'activity', '{"activity":"transformations","title":"Reflect a triangle","params":{"kind":"reflect"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d586e06af3d9e', 'les_aa07aeed128c22', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Choose each line of reflection and compare A′ with A(1, 1). Which line leaves A fixed? (Points on the mirror line don''t move.) Also notice the vertex order: A, B, C runs counterclockwise, but A′, B′, C′ runs clockwise."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6d8b7c2f0c320', 'les_aa07aeed128c22', 'learn', 5, 'worked_example', '{"title":"Reflect $P(3, -2)$ across the line $x = 1$","steps":[{"latex":"3 - 1 = 2","explanation":"P is 2 units right of the mirror line."},{"latex":"P''(1 - 2, -2) = (-1, -2)","explanation":"Go the same distance on the other side; y doesn''t change."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8938106457a207', 'les_aa07aeed128c22', 'learn', 6, 'worked_example', '{"title":"Reflect $\\overline{AB}$ with $A(2, 5)$, $B(-1, 3)$ across $y = x$","steps":[{"latex":"A''(5, 2),\\ B''(3, -1)","explanation":"Swap the coordinates."}],"check":"Check: the midpoint of $AA''$ is $(3.5, 3.5)$, which lies on $y = x$, and $\\overline{AA''}$ has slope $-1$, perpendicular to $y = x$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_309629d5d4998a', 'les_aa07aeed128c22', 'learn', 7, 'text', '{"body":"A reflection is a rigid motion, so lengths and angles are preserved, but it reverses orientation: a clockwise labeling becomes counterclockwise. A figure has line symmetry if some reflection maps it onto itself. A square has 4 lines of symmetry, a rectangle 2, an isosceles triangle 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cbea6734197403', 'les_aa07aeed128c22', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Mirrors, symmetric logos and the left-right symmetry of the human face are reflections. Light reflecting from a flat mirror follows the same perpendicular-bisector rule."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df693f1a77a93a', 'les_aa07aeed128c22', 1, 'practice', 'short_text', 1, 'Reflect $(4, 7)$ across the $x$-axis. Enter as (x,y).', '{"accept":["(4,-7)"]}', '[]', '$(4, -7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a60912e104858', 'les_aa07aeed128c22', 2, 'practice', 'short_text', 1, 'Reflect $(-5, 2)$ across the $y$-axis. Enter as (x,y).', '{"accept":["(5,2)"]}', '[]', '$(5, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_193b3ac9113a5f', 'les_aa07aeed128c22', 3, 'practice', 'short_text', 2, 'Reflect $(6, -1)$ across $y = -x$. Enter as (x,y).', '{"accept":["(1,-6)"]}', '["$(x, y) \\to (-y, -x)$."]', '$(-(-1), -6) = (1, -6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d586e06af3d9e', 'les_aa07aeed128c22', 4, 'practice', 'short_text', 2, 'Reflect $(2, 4)$ across the line $y = 1$. Enter as (x,y).', '{"accept":["(2,-2)"]}', '["The point is 3 above the line."]', '3 below the line: $(2, -2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6d8b7c2f0c320', 'les_aa07aeed128c22', 5, 'practice', 'multiple_choice', 2, 'How many lines of symmetry does a regular hexagon have?', '{"choices":["2","3","6","12"],"answer":2}', '["Lines through opposite vertices and through midpoints of opposite sides."]', '3 through opposite vertices and 3 through opposite side midpoints: 6.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8938106457a207', 'les_aa07aeed128c22', 6, 'review', 'short_text', 3, '$P(1, 3)$ reflects to $P''(7, 3)$. What is the equation of the line of reflection?', '{"accept":["x=4"]}', '["The mirror is the perpendicular bisector of PP′."]', 'The midpoint is $(4, 3)$ and $PP''$ is horizontal, so the mirror line is $x = 4$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2d2b216d5cb495', 'subj_math', 'rigid-motions', 'Rigid motions', 'Transformations that preserve distance and angle measure: translations, reflections and rotations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_aa07aeed128c22', (SELECT id FROM concepts WHERE slug = 'rigid-motions'));

-- Lesson: rotations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_634fab63566c8c', 'rotations', 'Rotations', 'Rotate figures about the origin by 90°, 180° and 270° using coordinate rules, rotate about other points, and identify rotational symmetry.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_abced537ccdddf', 'les_634fab63566c8c', 1, 'Define a rotation by its center, angle and direction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_15244af60c047e', 'les_634fab63566c8c', 2, 'Use coordinate rules for rotations of 90°, 180° and 270° about the origin.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3f0af974c117b3', 'les_634fab63566c8c', 3, 'Rotate about a point other than the origin and identify rotational symmetry.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_abced537ccdddf', 'les_634fab63566c8c', 'learn', 1, 'definition', '{"term":"Rotation","body":"A rotation by angle $\\theta$ about center $O$ maps each point $P$ to $P''$ so that $OP'' = OP$ and $m\\angle POP'' = \\theta$. Positive angles mean counterclockwise unless stated otherwise."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15244af60c047e', 'les_634fab63566c8c', 'learn', 2, 'definition', '{"term":"Rules about the origin (counterclockwise)","body":"$90^\\circ$: $(x, y) \\to (-y, x)$. $180^\\circ$: $(x, y) \\to (-x, -y)$. $270^\\circ$ (same as $90^\\circ$ clockwise): $(x, y) \\to (y, -x)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f0af974c117b3', 'les_634fab63566c8c', 'experiment', 3, 'activity', '{"activity":"transformations","title":"Rotate about the origin","params":{"kind":"rotate"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_264cfbfb4a6019', 'les_634fab63566c8c', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Rotate by $90^\\circ$: $A(1, 1) \\to (-1, 1)$, $B(4, 1) \\to (-1, 4)$. Check them against the rule $(x, y) \\to (-y, x)$. Then try $45^\\circ$: the coordinates are no longer whole numbers, but lengths are still preserved."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6679b9e3e593ce', 'les_634fab63566c8c', 'learn', 5, 'worked_example', '{"title":"Rotate $\\triangle PQR$ with $P(2, 0)$, $Q(5, 1)$, $R(3, 4)$ by $90^\\circ$ counterclockwise about the origin","steps":[{"latex":"(x, y) \\to (-y, x)","explanation":""},{"latex":"P''(0, 2),\\ Q''(-1, 5),\\ R''(-4, 3)","explanation":""}],"check":"Check: $OQ = \\sqrt{26}$ and $OQ'' = \\sqrt{1 + 25} = \\sqrt{26}$; slopes of $OQ$ ($\\frac{1}{5}$) and $OQ''$ ($-5$) multiply to $-1$, so the angle is $90^\\circ$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7632a083895757', 'les_634fab63566c8c', 'learn', 6, 'worked_example', '{"title":"Rotate $A(5, 3)$ by $180^\\circ$ about $C(2, 1)$","steps":[{"latex":"A - C = (3, 2)","explanation":"Translate so C is at the origin."},{"latex":"(3, 2) \\to (-3, -2)","explanation":"Rotate 180° about the origin."},{"latex":"A'' = (2 - 3,\\ 1 - 2) = (-1, -1)","explanation":"Translate back."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21cb19a68e04ad', 'les_634fab63566c8c', 'learn', 7, 'text', '{"body":"A figure has rotational symmetry if a rotation of less than $360^\\circ$ maps it onto itself. A regular $n$-gon has rotational symmetry of order $n$: it maps onto itself after rotations of $\\frac{360^\\circ}{n}$, $2 \\cdot \\frac{360^\\circ}{n}$, and so on. Rotations preserve orientation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_38cd1f7530cf5c', 'les_634fab63566c8c', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gears, wheels, fan blades and many logos have rotational symmetry. Computer graphics rotate objects with the same formulas, using $\\cos\\theta$ and $\\sin\\theta$ for angles that aren''t multiples of $90^\\circ$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_abced537ccdddf', 'les_634fab63566c8c', 1, 'practice', 'short_text', 1, 'Rotate $(3, 4)$ by $180^\circ$ about the origin. Enter as (x,y).', '{"accept":["(-3,-4)"]}', '[]', '$(-3, -4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_15244af60c047e', 'les_634fab63566c8c', 2, 'practice', 'short_text', 2, 'Rotate $(3, 4)$ by $90^\circ$ counterclockwise about the origin. Enter as (x,y).', '{"accept":["(-4,3)"]}', '["$(x, y) \\to (-y, x)$."]', '$(-4, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3f0af974c117b3', 'les_634fab63566c8c', 3, 'practice', 'short_text', 2, 'Rotate $(-2, 5)$ by $90^\circ$ clockwise about the origin. Enter as (x,y).', '{"accept":["(5,2)"]}', '["$90^\\circ$ clockwise is $270^\\circ$ counterclockwise: $(x, y) \\to (y, -x)$."]', '$(5, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_264cfbfb4a6019', 'les_634fab63566c8c', 4, 'practice', 'multiple_choice', 2, 'What is the smallest rotation that maps a regular pentagon onto itself?', '{"choices":["36°","60°","72°","108°"],"answer":2}', '["$360^\\circ \\div 5$."]', '$72^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6679b9e3e593ce', 'les_634fab63566c8c', 5, 'review', 'short_text', 3, 'Rotate $(4, 1)$ by $90^\circ$ counterclockwise about $(1, 1)$. Enter as (x,y).', '{"accept":["(1,4)"]}', '["Translate: (4, 1) − (1, 1) = (3, 0).","Rotate: (0, 3). Translate back."]', '$(0 + 1, 3 + 1) = (1, 4)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2d2b216d5cb495', 'subj_math', 'rigid-motions', 'Rigid motions', 'Transformations that preserve distance and angle measure: translations, reflections and rotations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_634fab63566c8c', (SELECT id FROM concepts WHERE slug = 'rigid-motions'));

-- Lesson: sample-spaces-probability
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7f40c5a3c70e9a', 'sample-spaces-probability', 'Sample spaces and basic probability', 'List sample spaces with lists, tables and tree diagrams, compute theoretical and experimental probabilities, and use complements and the addition rule.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e4d4ae131c2803', 'les_7f40c5a3c70e9a', 1, 'Describe a sample space with a list, table or tree diagram, and use the counting principle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_590a3a4b65da14', 'les_7f40c5a3c70e9a', 2, 'Compute theoretical and experimental probability and compare them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_25f9b49ec2113d', 'les_7f40c5a3c70e9a', 3, 'Use complements and the addition rule for ''or'' events.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4d4ae131c2803', 'les_7f40c5a3c70e9a', 'learn', 1, 'definition', '{"term":"Sample space and events","body":"The sample space is the set of all possible outcomes; an event is a subset of it. When outcomes are equally likely, $P(E) = \\frac{\\text{number of outcomes in } E}{\\text{number of outcomes in the sample space}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_590a3a4b65da14', 'les_7f40c5a3c70e9a', 'learn', 2, 'definition', '{"term":"Fundamental Counting Principle","body":"If one choice can be made in $m$ ways and a second in $n$ ways, the two can be made together in $m \\cdot n$ ways. Rolling two dice gives $6 \\cdot 6 = 36$ outcomes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25f9b49ec2113d', 'les_7f40c5a3c70e9a', 'learn', 3, 'worked_example', '{"title":"Two dice are rolled. Find $P(\\text{sum} = 7)$.","steps":[{"latex":"(1,6),(2,5),(3,4),(4,3),(5,2),(6,1)","explanation":"List the outcomes with sum 7."},{"latex":"P = \\tfrac{6}{36} = \\tfrac{1}{6}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c8b20d508af8f', 'les_7f40c5a3c70e9a', 'learn', 4, 'definition', '{"term":"Complement and addition rule","body":"$P(\\text{not } A) = 1 - P(A)$. $P(A \\text{ or } B) = P(A) + P(B) - P(A \\text{ and } B)$; subtract the overlap so it isn''t counted twice. If $A$ and $B$ can''t both happen (mutually exclusive), the overlap is 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_594b354272bb0e', 'les_7f40c5a3c70e9a', 'learn', 5, 'worked_example', '{"title":"A card is drawn from a standard 52-card deck. Find $P(\\text{heart or king})$.","steps":[{"latex":"\\tfrac{13}{52} + \\tfrac{4}{52} - \\tfrac{1}{52}","explanation":"The king of hearts is in both events."},{"latex":"= \\tfrac{16}{52} = \\tfrac{4}{13}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0625d342acf420', 'les_7f40c5a3c70e9a', 'learn', 6, 'text', '{"body":"Experimental probability comes from trials: $\\frac{\\text{times the event occurred}}{\\text{number of trials}}$. By the law of large numbers, it tends to get close to the theoretical probability as the number of trials grows."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_189d1f8a69a851', 'les_7f40c5a3c70e9a', 'experiment', 7, 'activity', '{"activity":"dice-simulation","title":"Experimental vs theoretical"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b26a86e857637b', 'les_7f40c5a3c70e9a', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"Run a few rolls and then many. How close does the experimental frequency get to the theoretical value? Small samples can be far off."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04bbcd880bd2a5', 'les_7f40c5a3c70e9a', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Weather forecasts, insurance, medical test results and games of chance all report probabilities. Understanding complements makes \"at least one\" questions easy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4d4ae131c2803', 'les_7f40c5a3c70e9a', 1, 'practice', 'numeric', 1, 'A fair coin is flipped 3 times. How many outcomes are in the sample space?', '{"answer":8}', '[]', '$2^3 = 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_590a3a4b65da14', 'les_7f40c5a3c70e9a', 2, 'practice', 'numeric', 1, 'A bag has 4 red, 5 blue and 3 green marbles. What is P(blue)? Enter a fraction or decimal.', '{"answer":0.4166666666666667,"tolerance":0.001}', '[]', '$\frac{5}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_25f9b49ec2113d', 'les_7f40c5a3c70e9a', 3, 'practice', 'numeric', 2, 'Two dice are rolled. What is the probability the sum is 10? Enter a fraction or decimal.', '{"answer":0.08333333333333333,"tolerance":0.001}', '["(4,6), (5,5), (6,4)."]', '$\frac{3}{36} = \frac{1}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c8b20d508af8f', 'les_7f40c5a3c70e9a', 4, 'practice', 'numeric', 2, 'The probability of rain is 0.35. What is the probability of no rain?', '{"answer":0.65}', '[]', '$1 - 0.35 = 0.65$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_594b354272bb0e', 'les_7f40c5a3c70e9a', 5, 'practice', 'numeric', 2, 'From a deck, what is P(face card or red card)? (Face cards: J, Q, K.) Enter a fraction or decimal.', '{"answer":0.6153846153846154,"tolerance":0.001}', '["12 face cards, 26 red, 6 red face cards."]', '$\frac{12 + 26 - 6}{52} = \frac{32}{52} = \frac{8}{13}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0625d342acf420', 'les_7f40c5a3c70e9a', 6, 'review', 'multiple_choice', 3, 'A spinner landed on blue 18 times in 50 spins. The theoretical probability is 1/4. Which is true?', '{"choices":["The spinner must be unfair","The experimental probability is 0.36, which can differ from 0.25 in a small sample","The theoretical probability is wrong","Experimental always equals theoretical"],"answer":1}', '[]', '$18 / 50 = 0.36$. With only 50 spins, a gap from 0.25 can happen by chance; more trials would tell you more.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a88397b662aed6', 'subj_math', 'probability', 'Probability', 'A number from 0 to 1 measuring how likely an event is.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7f40c5a3c70e9a', (SELECT id FROM concepts WHERE slug = 'probability'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7f40c5a3c70e9a', (SELECT id FROM formulas WHERE slug = 'probability-rules'), 1);

-- Lesson: sector-area
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d50c7723c96821', 'sector-area', 'Sector area', 'Find the area of a sector and of a segment of a circle, in degrees and radians, and solve for a missing radius or angle.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9897edbb90b32b', 'les_d50c7723c96821', 1, 'Compute sector area as a fraction of the circle''s area.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a0995b4ba5ff9d', 'les_d50c7723c96821', 2, 'Use the radian form A = ½r²θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_220ea76ffaeb3d', 'les_d50c7723c96821', 3, 'Find the area of a circular segment and solve for a missing radius or angle.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9897edbb90b32b', 'les_d50c7723c96821', 'learn', 1, 'text', '{"body":"A sector is the region bounded by two radii and their arc, like a pizza slice. It''s the same fraction of the circle''s area as its central angle is of $360^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a0995b4ba5ff9d', 'les_d50c7723c96821', 'learn', 2, 'formula', '{"latex":"A = \\frac{\\theta}{360^\\circ} \\cdot \\pi r^2 = \\tfrac{1}{2} r^2 \\theta_{\\text{rad}}","title":"Sector area"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_220ea76ffaeb3d', 'les_d50c7723c96821', 'experiment', 3, 'activity', '{"activity":"circle-angles","title":"Sector area changes with angle and radius","params":{"arc":72,"p":220,"r":6}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4052aa1652297', 'les_d50c7723c96821', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"With a $72^\\circ$ arc (one fifth of the circle) and radius 6, the sector area should be $\\frac{1}{5} \\cdot 36\\pi \\approx 22.62$. Double the radius: does the area double or quadruple?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b9f70bdac4ec72', 'les_d50c7723c96821', 'learn', 5, 'worked_example', '{"title":"Find the area of a $120^\\circ$ sector with radius 9 in.","steps":[{"latex":"\\tfrac{120}{360} \\cdot \\pi(81) = 27\\pi","explanation":""},{"latex":"\\approx 84.82 \\text{ in}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3876b048b2f904', 'les_d50c7723c96821', 'learn', 6, 'worked_example', '{"title":"Find the area of the segment cut off by a $90^\\circ$ central angle in a circle of radius 10.","steps":[{"latex":"\\text{sector} = \\tfrac{1}{4}\\pi(100) = 25\\pi \\approx 78.54","explanation":""},{"latex":"\\text{triangle} = \\tfrac{1}{2}(10)(10) = 50","explanation":"The two radii are perpendicular legs."},{"latex":"\\text{segment} = 25\\pi - 50 \\approx 28.54","explanation":"Sector minus triangle."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fe9f61e47878d', 'les_d50c7723c96821', 'learn', 7, 'worked_example', '{"title":"A sector has area $12\\pi$ and central angle $60^\\circ$. Find the radius.","steps":[{"latex":"\\tfrac{60}{360}\\pi r^2 = 12\\pi \\Rightarrow \\tfrac{r^2}{6} = 12","explanation":""},{"latex":"r^2 = 72 \\Rightarrow r = 6\\sqrt{2} \\approx 8.49","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4377e6f33dd91c', 'les_d50c7723c96821', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sprinkler coverage, windshield-wiper sweep, pizza slices and pie-chart regions are sectors. Farmers with center-pivot irrigation compute watered acreage with sector areas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9897edbb90b32b', 'les_d50c7723c96821', 1, 'practice', 'numeric', 1, 'Find the area of a $45^\circ$ sector with radius 8, to the nearest hundredth.', '{"answer":25.13,"tolerance":0.006}', '["$\\frac{1}{8} \\cdot 64\\pi = 8\\pi$."]', '$8\pi \approx 25.13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a0995b4ba5ff9d', 'les_d50c7723c96821', 2, 'practice', 'numeric', 2, 'A sprinkler sprays 15 m and rotates through $210^\circ$. What area does it water, to the nearest square meter?', '{"answer":412,"unit":"m²","tolerance":0.5}', '["$\\frac{210}{360}\\pi(225)$."]', '$131.25\pi \approx 412.3$, about 412 m².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_220ea76ffaeb3d', 'les_d50c7723c96821', 3, 'practice', 'numeric', 2, 'Find the area of a sector with radius 4 and central angle 1.5 radians.', '{"answer":12}', '["$\\frac{1}{2} r^2 \\theta$."]', '$\frac{1}{2} \cdot 16 \cdot 1.5 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4052aa1652297', 'les_d50c7723c96821', 4, 'practice', 'numeric', 3, 'A sector of a circle with radius 6 has area $15\pi$. What is its central angle in degrees?', '{"answer":150,"unit":"°"}', '["$\\frac{\\theta}{360} \\cdot 36\\pi = 15\\pi$."]', '$\theta = 15 \cdot 10 = 150^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b9f70bdac4ec72', 'les_d50c7723c96821', 5, 'review', 'numeric', 3, 'Find the area of the segment of a circle with radius 6 cut off by a $60^\circ$ central angle, to the nearest hundredth.', '{"answer":3.26,"tolerance":0.006}', '["Sector: 6π. The triangle is equilateral with side 6.","Triangle area $9\\sqrt{3}$."]', '$6\pi - 9\sqrt{3} \approx 18.85 - 15.59 = 3.26$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a6aedb62ecc78a', 'subj_math', 'radian-measure', 'Radian measure', 'Measuring angles by the ratio of arc length to radius; π radians = 180°.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d50c7723c96821', (SELECT id FROM concepts WHERE slug = 'radian-measure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d50c7723c96821', (SELECT id FROM formulas WHERE slug = 'arc-length-sector'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d50c7723c96821', (SELECT id FROM formulas WHERE slug = 'circle-area'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d50c7723c96821', (SELECT id FROM formulas WHERE slug = 'triangle-area'), 3);

-- Lesson: similar-polygons
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cd625e4ebd1043', 'similar-polygons', 'Similar polygons', 'Define similarity with dilations, write similarity statements, find scale factors and missing sides, and relate perimeters and areas of similar figures.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e1f1187d6f538d', 'les_cd625e4ebd1043', 1, 'Define similar figures using a dilation followed by rigid motions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90d8e5bf33e13c', 'les_cd625e4ebd1043', 2, 'Write similarity statements and use proportions to find missing lengths.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a83d4e621f7c4e', 'les_cd625e4ebd1043', 3, 'Use the fact that perimeters scale by k and areas by k².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1f1187d6f538d', 'les_cd625e4ebd1043', 'learn', 1, 'definition', '{"term":"Similar figures","body":"Two figures are similar ($\\sim$) if a dilation followed by rigid motions maps one onto the other. For polygons, that means corresponding angles are congruent and corresponding sides are proportional."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90d8e5bf33e13c', 'les_cd625e4ebd1043', 'learn', 2, 'text', '{"body":"The ratio of corresponding lengths is the scale factor. If $ABCD \\sim EFGH$ with scale factor $\\frac{1}{2}$ from $ABCD$ to $EFGH$, then $EF = \\frac{1}{2}AB$, and so on. The order of letters in the statement tells you which parts correspond."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a83d4e621f7c4e', 'les_cd625e4ebd1043', 'experiment', 3, 'activity', '{"activity":"transformations","title":"Dilation makes a similar figure","params":{"kind":"dilate"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a8691ee85f5bd', 'les_cd625e4ebd1043', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Dilate by 2, then imagine also rotating or reflecting the image. It''s still similar to the original: same angles, sides in ratio 2."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19d3e0a6d65d0a', 'les_cd625e4ebd1043', 'learn', 5, 'worked_example', '{"title":"$\\triangle ABC \\sim \\triangle DEF$, $AB = 6$, $BC = 9$, $DE = 10$. Find $EF$.","steps":[{"latex":"\\frac{DE}{AB} = \\frac{10}{6} = \\frac{5}{3}","explanation":"Scale factor from ABC to DEF."},{"latex":"EF = \\tfrac{5}{3} \\cdot 9 = 15","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_355c164211b9d0', 'les_cd625e4ebd1043', 'learn', 6, 'worked_example', '{"title":"Two similar rectangles have scale factor $3 : 5$. The smaller has area 36 cm². Find the larger area.","steps":[{"latex":"\\left(\\tfrac{5}{3}\\right)^2 = \\tfrac{25}{9}","explanation":"Areas scale by the square of the scale factor."},{"latex":"36 \\cdot \\tfrac{25}{9} = 100 \\text{ cm}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_384005c59cc6cf', 'les_cd625e4ebd1043', 'learn', 7, 'callout', '{"tone":"warning","title":"Same angles isn''t enough for polygons","body":"A square and a 2-by-1 rectangle both have four right angles but aren''t similar: their sides aren''t proportional. (For triangles, angles alone do suffice, as the next lesson shows.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21ed5ed2d84dd5', 'les_cd625e4ebd1043', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Model trains, maps, photo enlargements and architectural drawings are similar to the real objects. Movie screens and TVs with the same aspect ratio are similar rectangles."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1f1187d6f538d', 'les_cd625e4ebd1043', 1, 'practice', 'numeric', 1, 'Two similar triangles have scale factor 4. A side of the smaller is 7. Find the corresponding side of the larger.', '{"answer":28}', '[]', '$4 \cdot 7 = 28$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90d8e5bf33e13c', 'les_cd625e4ebd1043', 2, 'practice', 'numeric', 2, '$PQRS \sim WXYZ$, $PQ = 12$, $WX = 8$, $QR = 15$. Find $XY$.', '{"answer":10}', '["Scale factor 8/12 = 2/3."]', '$\frac{2}{3} \cdot 15 = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a83d4e621f7c4e', 'les_cd625e4ebd1043', 3, 'practice', 'numeric', 2, 'Similar pentagons have perimeters 30 and 45. A side of the smaller is 8. Find the corresponding side of the larger.', '{"answer":12}', '["Perimeters scale by the same factor."]', 'The scale factor is $1.5$, so $8 \cdot 1.5 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a8691ee85f5bd', 'les_cd625e4ebd1043', 4, 'practice', 'numeric', 2, 'Two similar figures have areas 16 and 81. What is the ratio of their corresponding sides? Enter as a decimal (larger ÷ smaller).', '{"answer":2.25}', '["Take the square root of the area ratio."]', '$\sqrt{81/16} = 9/4 = 2.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19d3e0a6d65d0a', 'les_cd625e4ebd1043', 5, 'review', 'multiple_choice', 3, 'Are all equilateral triangles similar?', '{"choices":["Yes","No","Only if the same size","Only if they share a vertex"],"answer":0}', '[]', 'All angles are 60° and sides are proportional (all in ratio $s_1 : s_2$), so yes.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3941da996c7bba', 'subj_math', 'similarity', 'Similarity', 'Figures with the same shape: corresponding angles congruent and corresponding sides proportional.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cd625e4ebd1043', (SELECT id FROM concepts WHERE slug = 'similarity'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cd625e4ebd1043', (SELECT id FROM concepts WHERE slug = 'scale-factor'));

-- Lesson: slopes-parallel-perpendicular-geometry
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7e5c9dd1c7f75a', 'slopes-parallel-perpendicular-geometry', 'Slopes of parallel and perpendicular lines', 'Use slopes to classify sides of figures on the coordinate plane as parallel or perpendicular, and to find equations of lines and the distance from a point to a line.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69962e5c2fe056', 'les_7e5c9dd1c7f75a', 1, 'Use slopes to decide whether segments in a figure are parallel or perpendicular.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3a01837cabfc3d', 'les_7e5c9dd1c7f75a', 2, 'Classify quadrilaterals on the coordinate plane with slopes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0fa4d12ef783c7', 'les_7e5c9dd1c7f75a', 3, 'Write the equation of the perpendicular from a point to a line and find the distance from the point to the line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69962e5c2fe056', 'les_7e5c9dd1c7f75a', 'learn', 1, 'text', '{"body":"In the coordinate plane, slopes turn questions about angles into arithmetic. Non-vertical lines are parallel exactly when their slopes are equal, and perpendicular exactly when their slopes multiply to $-1$. Vertical lines are parallel to each other and perpendicular to horizontal lines."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a01837cabfc3d', 'les_7e5c9dd1c7f75a', 'learn', 2, 'worked_example', '{"title":"Show that $A(0, 0)$, $B(4, 1)$, $C(5, 5)$, $D(1, 4)$ is a parallelogram, and decide whether it''s a rectangle","steps":[{"latex":"m_{AB} = \\tfrac{1}{4},\\ m_{DC} = \\tfrac{1}{4}","explanation":"AB ∥ DC."},{"latex":"m_{BC} = \\tfrac{4}{1} = 4,\\ m_{AD} = 4","explanation":"BC ∥ AD. Both pairs of opposite sides are parallel: a parallelogram."},{"latex":"\\tfrac{1}{4} \\cdot 4 = 1 \\ne -1","explanation":"Adjacent sides aren''t perpendicular, so it isn''t a rectangle."}],"check":"All four sides have length $\\sqrt{17}$, so it is a rhombus."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0fa4d12ef783c7', 'les_7e5c9dd1c7f75a', 'learn', 3, 'worked_example', '{"title":"Find the distance from $P(5, 1)$ to the line $y = 2x$","steps":[{"latex":"y - 1 = -\\tfrac{1}{2}(x - 5)","explanation":"The perpendicular through P has slope −1/2."},{"latex":"2x = -\\tfrac{1}{2}x + \\tfrac{7}{2} \\Rightarrow x = \\tfrac{7}{5},\\ y = \\tfrac{14}{5}","explanation":"Intersect the two lines to find the foot F."},{"latex":"PF = \\sqrt{\\left(5 - \\tfrac{7}{5}\\right)^2 + \\left(1 - \\tfrac{14}{5}\\right)^2} = \\sqrt{\\tfrac{324}{25} + \\tfrac{81}{25}} = \\tfrac{9}{\\sqrt{5}} \\approx 4.02","explanation":""}],"check":"The distance from a point to a line is always measured along the perpendicular, the shortest path."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3314aec692f992', 'les_7e5c9dd1c7f75a', 'experiment', 4, 'activity', '{"activity":"systems-graph","title":"Perpendicular slopes","params":{"m1":2,"b1":0,"m2":-0.5,"b2":3.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b422684c42cbd', 'les_7e5c9dd1c7f75a', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"These are $y = 2x$ and the perpendicular through $(5, 1)$. The intersection is the foot of the perpendicular, $(1.4, 2.8)$. Change slope 2 slightly: does the angle at the intersection still look right?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10e1d37dcef2d4', 'les_7e5c9dd1c7f75a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Mapping software checks whether streets are parallel or perpendicular from coordinates, and computer graphics uses perpendiculars to find the closest point on a path."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69962e5c2fe056', 'les_7e5c9dd1c7f75a', 1, 'practice', 'multiple_choice', 1, 'Which pair of slopes belongs to perpendicular lines?', '{"choices":["$3$ and $3$","$-\\frac{2}{5}$ and $\\frac{5}{2}$","$\\frac{1}{2}$ and $2$","$-4$ and $4$"],"answer":1}', '["Multiply the slopes."]', '$-\frac{2}{5} \cdot \frac{5}{2} = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a01837cabfc3d', 'les_7e5c9dd1c7f75a', 2, 'practice', 'multiple_choice', 2, 'Is the quadrilateral with vertices $(0, 0)$, $(3, 0)$, $(3, 2)$, $(0, 2)$ a rectangle?', '{"choices":["Yes","No, it''s only a parallelogram","No, it''s a trapezoid","No, it''s a kite"],"answer":0}', '["Sides are horizontal and vertical."]', 'Horizontal and vertical sides are perpendicular, and opposite sides are parallel: a rectangle.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0fa4d12ef783c7', 'les_7e5c9dd1c7f75a', 3, 'practice', 'multiple_choice', 2, 'Segment $\overline{PQ}$ joins $(1, 2)$ and $(4, 8)$. Segment $\overline{RS}$ joins $(0, 5)$ and $(6, 2)$. How are they related?', '{"choices":["Parallel","Perpendicular","Neither","The same line"],"answer":1}', '["$m_{PQ} = 2$ and $m_{RS} = -\\frac{1}{2}$."]', '$2 \cdot \left(-\frac{1}{2}\right) = -1$: perpendicular.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3314aec692f992', 'les_7e5c9dd1c7f75a', 4, 'practice', 'short_text', 2, 'Write the line through $(2, -3)$ perpendicular to $y = \tfrac{2}{3}x + 1$, in slope-intercept form.', '{"accept":["y=-3x/2","y=-(3/2)x","y=-1.5x"]}', '["Slope $-\\frac{3}{2}$.","$y + 3 = -\\frac{3}{2}(x - 2)$."]', '$y = -\frac{3}{2}x + 3 - 3 = -\frac{3}{2}x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8b422684c42cbd', 'les_7e5c9dd1c7f75a', 5, 'review', 'multiple_choice', 3, 'What is the distance from $(0, 5)$ to the line $y = 1$?', '{"choices":["1","4","5","6"],"answer":1}', '["The perpendicular to a horizontal line is vertical."]', 'The foot is $(0, 1)$, so the distance is 4.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7e5c9dd1c7f75a', (SELECT id FROM concepts WHERE slug = 'parallel-perpendicular'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_64eaafaca65525', 'subj_math', 'coordinate-geometry', 'Coordinate geometry', 'Studying geometric figures with coordinates and algebra.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7e5c9dd1c7f75a', (SELECT id FROM concepts WHERE slug = 'coordinate-geometry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7e5c9dd1c7f75a', (SELECT id FROM formulas WHERE slug = 'slope'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7e5c9dd1c7f75a', (SELECT id FROM formulas WHERE slug = 'distance-formula'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7e5c9dd1c7f75a', (SELECT id FROM formulas WHERE slug = 'point-slope-form'), 3);

-- Lesson: solving-right-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c68aa600da3c54', 'solving-right-triangles', 'Solving right triangles', 'Use inverse trigonometric functions to find acute angles, and solve right triangles completely from two given parts.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b8051142c5512', 'les_c68aa600da3c54', 1, 'Use inverse sine, cosine and tangent to find an acute angle from a ratio.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08e1342155910f', 'les_c68aa600da3c54', 2, 'Solve a right triangle: find all missing sides and angles from two given parts (including one side).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c09d592a5c931', 'les_c68aa600da3c54', 3, 'Check solutions with the Pythagorean theorem and the angle sum.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b8051142c5512', 'les_c68aa600da3c54', 'learn', 1, 'definition', '{"term":"Inverse trig","body":"If $\\tan A = 0.75$, then $A = \\tan^{-1}(0.75) \\approx 36.87^\\circ$. $\\sin^{-1}$, $\\cos^{-1}$ and $\\tan^{-1}$ undo the ratios and return an angle. The $-1$ is not an exponent: $\\tan^{-1} x \\ne \\frac{1}{\\tan x}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08e1342155910f', 'les_c68aa600da3c54', 'learn', 2, 'text', '{"body":"To solve a right triangle means finding all three sides and both acute angles. You need two pieces of information besides the right angle, and at least one must be a side. Then: use a trig ratio or the Pythagorean theorem for sides, inverse trig for angles, and the fact that the acute angles sum to $90^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c09d592a5c931', 'les_c68aa600da3c54', 'learn', 3, 'worked_example', '{"title":"Solve the right triangle with legs $a = 7$ and $b = 24$","steps":[{"latex":"c = \\sqrt{49 + 576} = 25","explanation":"Hypotenuse."},{"latex":"A = \\tan^{-1}\\!\\left(\\tfrac{7}{24}\\right) \\approx 16.26^\\circ","explanation":"Angle opposite a."},{"latex":"B = 90^\\circ - 16.26^\\circ = 73.74^\\circ","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8492ea4e55278c', 'les_c68aa600da3c54', 'learn', 4, 'worked_example', '{"title":"Solve the right triangle with $A = 38^\\circ$ and hypotenuse $c = 15$","steps":[{"latex":"B = 52^\\circ","explanation":""},{"latex":"a = 15\\sin 38^\\circ \\approx 9.23","explanation":"Opposite A."},{"latex":"b = 15\\cos 38^\\circ \\approx 11.82","explanation":"Adjacent to A."}],"check":"Check: $9.23^2 + 11.82^2 \\approx 85.2 + 139.7 = 224.9 \\approx 15^2 = 225$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc61f682706b9c', 'les_c68aa600da3c54', 'experiment', 5, 'activity', '{"activity":"right-triangle-trig","title":"Match a triangle","params":{"angle":38,"hyp":15}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49642fc978078b', 'les_c68aa600da3c54', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"This is the triangle from the second example. Do the readouts for opposite and adjacent agree with 9.23 and 11.82? Now find the angle that makes the opposite side exactly 7.5 (hint: $\\sin^{-1}(0.5)$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc9eaae6c8b80b', 'les_c68aa600da3c54', 'learn', 7, 'callout', '{"tone":"warning","title":"Use given values when you can","body":"Compute each missing part from the original data rather than from a value you rounded earlier. Rounding errors build up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e451fd3631d74', 'les_c68aa600da3c54', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Navigation (bearings), the pitch of a roof from its rise and run, a ramp''s angle from building codes, and the angle a camera must tilt to frame a building are all solved with inverse trig."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b8051142c5512', 'les_c68aa600da3c54', 1, 'practice', 'numeric', 1, 'Find $A$ to the nearest tenth of a degree if $\sin A = 0.5$.', '{"answer":30,"unit":"°","tolerance":0.06}', '[]', '$\sin^{-1}(0.5) = 30^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08e1342155910f', 'les_c68aa600da3c54', 2, 'practice', 'numeric', 2, 'A right triangle has legs 5 and 12. Find the angle opposite the side of length 5, to the nearest tenth of a degree.', '{"answer":22.6,"unit":"°","tolerance":0.06}', '["$\\tan^{-1}(5/12)$."]', '$\tan^{-1}(0.4167) \approx 22.6^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c09d592a5c931', 'les_c68aa600da3c54', 3, 'practice', 'numeric', 2, 'A right triangle has hypotenuse 20 and a leg of 13. Find the angle adjacent to that leg, to the nearest tenth of a degree.', '{"answer":49.5,"unit":"°","tolerance":0.06}', '["$\\cos^{-1}(13/20)$."]', '$\cos^{-1}(0.65) \approx 49.5^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8492ea4e55278c', 'les_c68aa600da3c54', 4, 'practice', 'numeric', 2, 'A roof rises 4 ft over a horizontal run of 12 ft. What angle does it make with the horizontal, to the nearest tenth?', '{"answer":18.4,"unit":"°","tolerance":0.06}', '["$\\tan^{-1}(4/12)$."]', '$\approx 18.4^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc61f682706b9c', 'les_c68aa600da3c54', 5, 'review', 'numeric', 3, 'In right triangle $ABC$ ($C = 90^\circ$), $B = 64^\circ$ and $b = 18$ (opposite $B$). Find $a$ to the nearest hundredth.', '{"answer":8.78,"tolerance":0.006}', '["$\\tan 64^\\circ = \\frac{18}{a}$."]', '$a = 18 / \tan 64^\circ \approx 18 / 2.0503 \approx 8.78$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_68e5b8ea0a287f', 'subj_math', 'trigonometric-ratios', 'Trigonometric ratios', 'Sine, cosine and tangent: ratios of sides in a right triangle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c68aa600da3c54', (SELECT id FROM concepts WHERE slug = 'trigonometric-ratios'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a18bae3e17b9e8', 'subj_math', 'inverse-trig', 'Inverse trigonometric functions', 'Functions that return an angle from a trigonometric ratio.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c68aa600da3c54', (SELECT id FROM concepts WHERE slug = 'inverse-trig'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c68aa600da3c54', (SELECT id FROM formulas WHERE slug = 'trig-ratios'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c68aa600da3c54', (SELECT id FROM formulas WHERE slug = 'pythagorean-theorem'), 2);

-- Lesson: special-right-triangles
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1902fc327ff81c', 'special-right-triangles', 'Special right triangles', 'Derive and use the side ratios of 45°-45°-90° and 30°-60°-90° triangles to find exact side lengths.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_83644b78efc456', 'les_1902fc327ff81c', 1, 'Derive the side ratios of 45-45-90 and 30-60-90 triangles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35eb0b8413983b', 'les_1902fc327ff81c', 2, 'Find missing sides exactly, in simplest radical form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_17516f0a6e9809', 'les_1902fc327ff81c', 3, 'Apply the ratios to squares, equilateral triangles and hexagons.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83644b78efc456', 'les_1902fc327ff81c', 'learn', 1, 'definition', '{"term":"45°-45°-90° triangle","body":"The legs are congruent and the hypotenuse is $\\sqrt{2}$ times a leg: $x : x : x\\sqrt{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35eb0b8413983b', 'les_1902fc327ff81c', 'learn', 2, 'text', '{"body":"Why: cut a square of side $x$ along a diagonal. Each half is an isosceles right triangle, and the Pythagorean theorem gives the diagonal: $\\sqrt{x^2 + x^2} = \\sqrt{2x^2} = x\\sqrt{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_17516f0a6e9809', 'les_1902fc327ff81c', 'learn', 3, 'definition', '{"term":"30°-60°-90° triangle","body":"The hypotenuse is twice the short leg, and the long leg is $\\sqrt{3}$ times the short leg: $x : x\\sqrt{3} : 2x$. The short leg is opposite $30^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_405000a7b0d341', 'les_1902fc327ff81c', 'learn', 4, 'text', '{"body":"Why: cut an equilateral triangle of side $2x$ with an altitude. Each half has hypotenuse $2x$, short leg $x$ (half the base), and long leg $\\sqrt{(2x)^2 - x^2} = \\sqrt{3x^2} = x\\sqrt{3}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d15bb5229f2aaa', 'les_1902fc327ff81c', 'learn', 5, 'worked_example', '{"title":"A 45-45-90 triangle has hypotenuse 10. Find each leg.","steps":[{"latex":"x\\sqrt{2} = 10 \\Rightarrow x = \\tfrac{10}{\\sqrt{2}}","explanation":""},{"latex":"x = \\tfrac{10\\sqrt{2}}{2} = 5\\sqrt{2} \\approx 7.07","explanation":"Rationalize the denominator."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86c423123adc0d', 'les_1902fc327ff81c', 'learn', 6, 'worked_example', '{"title":"In a 30-60-90 triangle the long leg is 9. Find the short leg and hypotenuse.","steps":[{"latex":"x\\sqrt{3} = 9 \\Rightarrow x = \\tfrac{9}{\\sqrt{3}} = 3\\sqrt{3}","explanation":"Short leg."},{"latex":"2x = 6\\sqrt{3} \\approx 10.39","explanation":"Hypotenuse."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9dec63a24c556f', 'les_1902fc327ff81c', 'learn', 7, 'worked_example', '{"title":"Find the area of an equilateral triangle with side 8.","steps":[{"latex":"h = 4\\sqrt{3}","explanation":"The altitude is the long leg of a 30-60-90 triangle with short leg 4."},{"latex":"A = \\tfrac{1}{2} \\cdot 8 \\cdot 4\\sqrt{3} = 16\\sqrt{3} \\approx 27.71","explanation":"In general $A = \\frac{\\sqrt{3}}{4}s^2$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e35b35dc7173ba', 'les_1902fc327ff81c', 'learn', 8, 'callout', '{"tone":"warning","title":"Which leg is which?","body":"In a 30-60-90 triangle, the short leg is opposite the $30^\\circ$ angle and the long leg opposite $60^\\circ$. Check: the hypotenuse must be the longest side, and $2 > \\sqrt{3} \\approx 1.73 > 1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc609a89f55893', 'les_1902fc327ff81c', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carpenters'' 45° and 30-60 set squares, the diagonal of a square tile, the height of an equilateral roof truss and hexagonal bolt heads all use these ratios."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83644b78efc456', 'les_1902fc327ff81c', 1, 'practice', 'short_text', 1, 'A 45-45-90 triangle has legs of 6. Find the hypotenuse in simplest radical form. Use the format 6sqrt(2).', '{"accept":["6sqrt(2)","6√2","6sqrt2"]}', '[]', '$6\sqrt{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35eb0b8413983b', 'les_1902fc327ff81c', 2, 'practice', 'numeric', 2, 'A 30-60-90 triangle has hypotenuse 14. Find the short leg.', '{"answer":7}', '[]', 'Half the hypotenuse: 7.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_17516f0a6e9809', 'les_1902fc327ff81c', 3, 'practice', 'short_text', 2, 'A 30-60-90 triangle has short leg 5. Find the long leg. Use the format 5sqrt(3).', '{"accept":["5sqrt(3)","5√3","5sqrt3"]}', '[]', '$5\sqrt{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_405000a7b0d341', 'les_1902fc327ff81c', 4, 'practice', 'numeric', 2, 'A square has a diagonal of 12. Find its side length to the nearest hundredth.', '{"answer":8.49,"tolerance":0.006}', '["$s\\sqrt{2} = 12$."]', '$s = 6\sqrt{2} \approx 8.49$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d15bb5229f2aaa', 'les_1902fc327ff81c', 5, 'practice', 'numeric', 3, 'Find the area of an equilateral triangle with side 10, to the nearest tenth.', '{"answer":43.3,"tolerance":0.06}', '["$\\frac{\\sqrt{3}}{4} \\cdot 100$."]', '$25\sqrt{3} \approx 43.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86c423123adc0d', 'les_1902fc327ff81c', 6, 'review', 'multiple_choice', 3, 'A ladder makes a $60^\circ$ angle with the ground and reaches 6 m up the wall. How long is the ladder?', '{"choices":["$3$ m","$2\\sqrt{3}$ m","$4\\sqrt{3}$ m","$12$ m"],"answer":2}', '["The height is the long leg (opposite 60°)."]', '$x\sqrt{3} = 6$ gives $x = 2\sqrt{3}$, and the ladder (hypotenuse) is $4\sqrt{3} \approx 6.93$ m.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1902fc327ff81c', 'subj_math', 'special-right-triangles', 'Special right triangles', '45-45-90 and 30-60-90 triangles with fixed side ratios.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1902fc327ff81c', (SELECT id FROM concepts WHERE slug = 'special-right-triangles'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1902fc327ff81c', (SELECT id FROM formulas WHERE slug = 'special-right-triangles'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1902fc327ff81c', (SELECT id FROM formulas WHERE slug = 'pythagorean-theorem'), 2);

-- Lesson: sss-sas-congruence
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a9df8cc3e02f6a', 'sss-sas-congruence', 'SSS and SAS congruence', 'Use corresponding parts and congruence statements, and prove triangles congruent with the Side-Side-Side and Side-Angle-Side criteria.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_645b64fd93208d', 'les_a9df8cc3e02f6a', 1, 'Write congruence statements with corresponding vertices in order.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_16f77242bd5292', 'les_a9df8cc3e02f6a', 2, 'Prove triangles congruent using SSS and SAS, including shared sides and vertical angles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_04d72d8956d5c4', 'les_a9df8cc3e02f6a', 3, 'Explain why SSA is not a valid congruence criterion.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_645b64fd93208d', 'les_a9df8cc3e02f6a', 'learn', 1, 'definition', '{"term":"Congruent triangles","body":"$\\triangle ABC \\cong \\triangle DEF$ means a rigid motion maps $A \\to D$, $B \\to E$, $C \\to F$. Then all six pairs of corresponding parts are congruent: $\\overline{AB} \\cong \\overline{DE}$, $\\angle A \\cong \\angle D$, and so on. The order of letters matters."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16f77242bd5292', 'les_a9df8cc3e02f6a', 'learn', 2, 'text', '{"body":"You don''t need all six pairs to know two triangles are congruent. Certain combinations of three force the triangle to be rigid. Try building a triangle from three fixed straws: there''s only one shape possible. That''s SSS."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04d72d8956d5c4', 'les_a9df8cc3e02f6a', 'learn', 3, 'definition', '{"term":"SSS","body":"If three sides of one triangle are congruent to three sides of another, the triangles are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_971e93cddbc454', 'les_a9df8cc3e02f6a', 'learn', 4, 'definition', '{"term":"SAS","body":"If two sides and the included angle (the angle between them) of one triangle are congruent to those of another, the triangles are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cda2ed87f4f3a0', 'les_a9df8cc3e02f6a', 'learn', 5, 'worked_example', '{"title":"Given $\\overline{AB} \\cong \\overline{CB}$ and $D$ is the midpoint of $\\overline{AC}$. Prove $\\triangle ABD \\cong \\triangle CBD$.","steps":[{"latex":"1.\\ \\overline{AB} \\cong \\overline{CB}","explanation":"Given."},{"latex":"2.\\ \\overline{AD} \\cong \\overline{CD}","explanation":"Definition of midpoint."},{"latex":"3.\\ \\overline{BD} \\cong \\overline{BD}","explanation":"Reflexive property (shared side)."},{"latex":"4.\\ \\triangle ABD \\cong \\triangle CBD","explanation":"SSS."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_701c94f096a68c', 'les_a9df8cc3e02f6a', 'learn', 6, 'worked_example', '{"title":"Segments $\\overline{AE}$ and $\\overline{BD}$ bisect each other at $C$. Prove $\\triangle ACB \\cong \\triangle ECD$.","steps":[{"latex":"1.\\ \\overline{AC} \\cong \\overline{EC},\\ \\overline{BC} \\cong \\overline{DC}","explanation":"Definition of segment bisector."},{"latex":"2.\\ \\angle ACB \\cong \\angle ECD","explanation":"Vertical angles are congruent."},{"latex":"3.\\ \\triangle ACB \\cong \\triangle ECD","explanation":"SAS (the angle is between the two sides)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c886c9faf80c6', 'les_a9df8cc3e02f6a', 'learn', 7, 'callout', '{"tone":"warning","title":"No SSA (or ASS)","body":"Two sides and a non-included angle don''t guarantee congruence. With sides 5 and 7 and a $30^\\circ$ angle opposite the 5, two different triangles are possible, because the side of length 5 can swing to two positions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_133c5501d5807b', 'les_a9df8cc3e02f6a', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Triangular bracing makes frames rigid precisely because of SSS: a triangle with fixed side lengths can''t change shape, while a rectangle can collapse into a parallelogram."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_645b64fd93208d', 'les_a9df8cc3e02f6a', 1, 'practice', 'multiple_choice', 1, 'If $\triangle PQR \cong \triangle XYZ$, which angle is congruent to $\angle Q$?', '{"choices":["$\\angle X$","$\\angle Y$","$\\angle Z$","$\\angle R$"],"answer":1}', '["Match letter positions."]', '$Q$ is second, so it corresponds to $Y$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16f77242bd5292', 'les_a9df8cc3e02f6a', 2, 'practice', 'multiple_choice', 2, 'Which information proves $\triangle ABC \cong \triangle DEF$ by SAS?', '{"choices":["$AB = DE$, $BC = EF$, $\\angle A \\cong \\angle D$","$AB = DE$, $BC = EF$, $\\angle B \\cong \\angle E$","$\\angle A \\cong \\angle D$, $\\angle B \\cong \\angle E$, $AB = DE$","$AB = DE$, $AC = DF$, $\\angle B \\cong \\angle E$"],"answer":1}', '["The angle must be between the two sides."]', '$\angle B$ is included between $\overline{AB}$ and $\overline{BC}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04d72d8956d5c4', 'les_a9df8cc3e02f6a', 3, 'practice', 'multiple_choice', 2, 'Two triangles share a side, and their other two pairs of sides are congruent. Which criterion applies?', '{"choices":["SAS","SSS","ASA","None"],"answer":1}', '[]', 'The shared side is congruent to itself (reflexive), giving three pairs of congruent sides: SSS.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_971e93cddbc454', 'les_a9df8cc3e02f6a', 4, 'practice', 'multiple_choice', 2, 'Which is not a valid congruence criterion?', '{"choices":["SSS","SAS","SSA","ASA"],"answer":2}', '[]', 'SSA can produce two different triangles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cda2ed87f4f3a0', 'les_a9df8cc3e02f6a', 5, 'review', 'multiple_choice', 3, 'In the bisecting-segments example, which pair of parts is congruent as a result of the proof but was not used in it?', '{"choices":["$\\overline{AB} \\cong \\overline{ED}$","$\\overline{AC} \\cong \\overline{EC}$","$\\angle ACB \\cong \\angle ECD$","$\\overline{BC} \\cong \\overline{DC}$"],"answer":0}', '["Corresponding parts of congruent triangles are congruent."]', 'Once the triangles are congruent, $\overline{AB} \cong \overline{ED}$ follows; it was not used to prove it.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4d1c853f740b75', 'subj_math', 'triangle-congruence', 'Triangle congruence', 'Criteria (SSS, SAS, ASA, AAS, HL) that guarantee two triangles are congruent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a9df8cc3e02f6a', (SELECT id FROM concepts WHERE slug = 'triangle-congruence'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b7599fc065b0a0', 'subj_math', 'congruence', 'Congruence', 'Figures are congruent if a sequence of rigid motions maps one onto the other.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a9df8cc3e02f6a', (SELECT id FROM concepts WHERE slug = 'congruence'));

-- Lesson: surface-area-solids
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9f8f7f4afcc93e', 'surface-area-solids', 'Surface area of prisms, cylinders, pyramids and cones', 'Use nets to find lateral and total surface areas of prisms, cylinders, pyramids, cones and spheres, using slant height for pyramids and cones.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ded7315858409a', 'les_9f8f7f4afcc93e', 1, 'Use nets to explain surface area formulas.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9671b63555a488', 'les_9f8f7f4afcc93e', 2, 'Find lateral and total surface area of prisms, cylinders, regular pyramids and cones.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_07529336eae031', 'les_9f8f7f4afcc93e', 3, 'Find slant height with the Pythagorean theorem, and compute the surface area of a sphere.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ded7315858409a', 'les_9f8f7f4afcc93e', 'learn', 1, 'definition', '{"term":"Surface area","body":"The total area of all the surfaces of a solid. Lateral area leaves out the bases. A net, the solid unfolded flat, shows every face."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9671b63555a488', 'les_9f8f7f4afcc93e', 'learn', 2, 'text', '{"body":"Prism: $SA = 2B + Ph$ (two bases plus a rectangle with width the base perimeter $P$). Cylinder: $SA = 2\\pi r^2 + 2\\pi rh$ (the side unrolls into a rectangle $2\\pi r$ wide). Regular pyramid: $SA = B + \\frac{1}{2}P\\ell$. Cone: $SA = \\pi r^2 + \\pi r\\ell$, where $\\ell$ is the slant height. Sphere: $SA = 4\\pi r^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_07529336eae031', 'les_9f8f7f4afcc93e', 'experiment', 3, 'activity', '{"activity":"area-volume","title":"Prism and cylinder surface area","params":{"shape":"cylinder"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd06febb2ae551', 'les_9f8f7f4afcc93e', 'learn', 4, 'worked_example', '{"title":"Find the surface area of a cylinder with radius 3 cm and height 10 cm.","steps":[{"latex":"2\\pi(3)^2 + 2\\pi(3)(10) = 18\\pi + 60\\pi = 78\\pi","explanation":""},{"latex":"\\approx 245.04 \\text{ cm}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_817be17ccd8906', 'les_9f8f7f4afcc93e', 'learn', 5, 'worked_example', '{"title":"A square pyramid has base edge 10 and height 12. Find its surface area.","steps":[{"latex":"\\ell = \\sqrt{12^2 + 5^2} = 13","explanation":"Slant height: from the apex to the midpoint of a base edge."},{"latex":"SA = 10^2 + \\tfrac{1}{2}(40)(13) = 100 + 260 = 360","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ebdbe66d5daf2', 'les_9f8f7f4afcc93e', 'learn', 6, 'worked_example', '{"title":"A cone has radius 6 and height 8. Find its surface area.","steps":[{"latex":"\\ell = \\sqrt{8^2 + 6^2} = 10","explanation":""},{"latex":"SA = \\pi(36) + \\pi(6)(10) = 96\\pi \\approx 301.59","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe7305724f2bdd', 'les_9f8f7f4afcc93e', 'learn', 7, 'callout', '{"tone":"warning","title":"Height vs slant height","body":"For pyramids and cones, surface area uses the slant height $\\ell$ (along the face), while volume uses the perpendicular height $h$. They are related by the Pythagorean theorem."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44d79e9fa68973', 'les_9f8f7f4afcc93e', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Packaging design (how much cardboard a box needs), painting a silo, wrapping a gift and making a paper cone all depend on surface area."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ded7315858409a', 'les_9f8f7f4afcc93e', 1, 'practice', 'numeric', 1, 'Find the surface area of a 3 by 4 by 5 rectangular prism.', '{"answer":94}', '["$2(12 + 15 + 20)$."]', '$2(47) = 94$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9671b63555a488', 'les_9f8f7f4afcc93e', 2, 'practice', 'numeric', 2, 'Find the surface area of a sphere with radius 5, to the nearest tenth.', '{"answer":314.2,"tolerance":0.06}', '["$4\\pi r^2$."]', '$100\pi \approx 314.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_07529336eae031', 'les_9f8f7f4afcc93e', 3, 'practice', 'numeric', 2, 'A cone has radius 5 and slant height 13. Find its lateral area, to the nearest tenth.', '{"answer":204.2,"tolerance":0.06}', '["$\\pi r\\ell$."]', '$65\pi \approx 204.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd06febb2ae551', 'les_9f8f7f4afcc93e', 4, 'practice', 'numeric', 2, 'A square pyramid has base edge 6 and slant height 5. Find its total surface area.', '{"answer":96}', '["$36 + \\frac{1}{2}(24)(5)$."]', '$36 + 60 = 96$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_817be17ccd8906', 'les_9f8f7f4afcc93e', 5, 'review', 'numeric', 3, 'A cylinder has radius 4 and total surface area $80\pi$. Find its height.', '{"answer":6}', '["$32\\pi + 8\\pi h = 80\\pi$."]', '$8h = 48$, $h = 6$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3cfb8e36a4e051', 'subj_math', 'surface-area', 'Surface area', 'The total area of all faces or curved surfaces of a solid.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9f8f7f4afcc93e', (SELECT id FROM concepts WHERE slug = 'surface-area'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9f8f7f4afcc93e', (SELECT id FROM formulas WHERE slug = 'pyramid-cone-sphere'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9f8f7f4afcc93e', (SELECT id FROM formulas WHERE slug = 'circle-area'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9f8f7f4afcc93e', (SELECT id FROM formulas WHERE slug = 'pythagorean-theorem'), 3);

-- Lesson: tangents-chords
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c6db6646d85fbb', 'tangents-chords', 'Tangents and chords', 'Use the tangent-radius theorem, equal tangent segments from an external point, intersecting chords, and secant and tangent segment products.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_203fa393d9faba', 'les_c6db6646d85fbb', 1, 'Use the fact that a tangent is perpendicular to the radius at the point of tangency.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b681c99fab3a70', 'les_c6db6646d85fbb', 2, 'Use the fact that tangent segments from an external point are congruent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_50e1176e75b91d', 'les_c6db6646d85fbb', 3, 'Apply the segment-product theorems for intersecting chords, secants and tangents.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_203fa393d9faba', 'les_c6db6646d85fbb', 'learn', 1, 'definition', '{"term":"Tangent","body":"A line in the plane of a circle that touches it at exactly one point, the point of tangency. A tangent is perpendicular to the radius drawn to the point of tangency, and a line perpendicular to a radius at its endpoint on the circle is a tangent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b681c99fab3a70', 'les_c6db6646d85fbb', 'learn', 2, 'worked_example', '{"title":"From external point $P$, a tangent touches circle $O$ (radius 5) at $T$, and $PO = 13$. Find $PT$.","steps":[{"latex":"\\overline{OT} \\perp \\overline{PT}","explanation":"Tangent ⟂ radius."},{"latex":"PT = \\sqrt{13^2 - 5^2} = 12","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50e1176e75b91d', 'les_c6db6646d85fbb', 'learn', 3, 'definition', '{"term":"Two tangents from a point","body":"If two segments from the same external point are tangent to a circle, they are congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3e3a79a9f66dd', 'les_c6db6646d85fbb', 'learn', 4, 'definition', '{"term":"Segment products","body":"Intersecting chords: if chords $\\overline{AB}$ and $\\overline{CD}$ meet at $E$, then $AE \\cdot EB = CE \\cdot ED$. Secants from an external point: (outside part)(whole) is the same for both. Tangent and secant: $(\\text{tangent})^2 = (\\text{outside part})(\\text{whole secant})$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0636eb5f8170f7', 'les_c6db6646d85fbb', 'learn', 5, 'worked_example', '{"title":"Chords meet at $E$ with $AE = 4$, $EB = 9$ and $CE = 6$. Find $ED$.","steps":[{"latex":"4 \\cdot 9 = 6 \\cdot ED","explanation":""},{"latex":"ED = 6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4dec49f91053b', 'les_c6db6646d85fbb', 'learn', 6, 'worked_example', '{"title":"From point $P$, a tangent of length $x$ and a secant with outside part 4 and whole length 16 are drawn. Find $x$.","steps":[{"latex":"x^2 = 4 \\cdot 16 = 64","explanation":""},{"latex":"x = 8","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02f2385c4b61e0', 'les_c6db6646d85fbb', 'learn', 7, 'callout', '{"tone":"warning","title":"Use the whole secant","body":"In the secant formulas, multiply the outside part by the entire secant (outside part plus the chord inside), not by the inside part alone."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72578b852bdc49', 'les_c6db6646d85fbb', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"A belt around two pulleys runs along tangent lines. The distance to the horizon from height $h$ above Earth (radius $R$) comes from the tangent-radius right triangle: $d = \\sqrt{(R + h)^2 - R^2}$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_203fa393d9faba', 'les_c6db6646d85fbb', 1, 'practice', 'numeric', 1, 'A tangent from $P$ touches circle $O$ at $T$. $OT = 8$ and $PT = 15$. Find $PO$.', '{"answer":17}', '["Right angle at T."]', '$\sqrt{64 + 225} = 17$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b681c99fab3a70', 'les_c6db6646d85fbb', 2, 'practice', 'numeric', 2, 'Two tangent segments from the same point have lengths $3x + 1$ and $5x - 7$. Find the length.', '{"answer":13}', '[]', '$x = 4$, length 13.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50e1176e75b91d', 'les_c6db6646d85fbb', 3, 'practice', 'numeric', 2, 'Chords meet inside a circle. One is split into 5 and 8; the other into 4 and $x$. Find $x$.', '{"answer":10}', '[]', '$40 = 4x$, $x = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3e3a79a9f66dd', 'les_c6db6646d85fbb', 4, 'practice', 'numeric', 2, 'Two secants from point $P$: the first has outside part 3 and total length 12; the second has outside part 4. Find the second''s total length.', '{"answer":9}', '["$3 \\cdot 12 = 4 \\cdot w$."]', '$w = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0636eb5f8170f7', 'les_c6db6646d85fbb', 5, 'review', 'multiple_choice', 3, 'A line is perpendicular to a radius at a point inside the circle (not on it). Is it a tangent?', '{"choices":["Yes","No, it crosses the circle at two points","Only if it''s a diameter","Only for small circles"],"answer":1}', '[]', 'The perpendicular must be at the radius''s endpoint on the circle. At an interior point, the line is a chord''s line and meets the circle twice.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_021a201c0027d2', 'subj_math', 'circles', 'Circles', 'Sets of points at a fixed distance from a center; arcs, chords and angles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c6db6646d85fbb', (SELECT id FROM concepts WHERE slug = 'circles'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c6db6646d85fbb', (SELECT id FROM formulas WHERE slug = 'pythagorean-theorem'), 1);

-- Lesson: translations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_31c20e73fa2924', 'translations', 'Translations', 'Describe and perform translations with coordinate rules and vectors, and recognize that translations are rigid motions.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90271579c6a6ba', 'les_31c20e73fa2924', 1, 'Define a transformation, preimage and image, and a rigid motion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3dcd90e5fbf49c', 'les_31c20e73fa2924', 2, 'Translate figures with the rule (x, y) → (x + a, y + b) and with a vector.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5e7e13c8e82e01', 'les_31c20e73fa2924', 3, 'Write a translation rule from a preimage and its image.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90271579c6a6ba', 'les_31c20e73fa2924', 'learn', 1, 'definition', '{"term":"Transformation","body":"A rule that moves every point of a figure (the preimage) to a new location (the image). Image points are named with primes: $A \\to A''$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3dcd90e5fbf49c', 'les_31c20e73fa2924', 'learn', 2, 'definition', '{"term":"Rigid motion","body":"A transformation that preserves lengths and angle measures. The image is congruent to the preimage. Translations, reflections and rotations are rigid motions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e7e13c8e82e01', 'les_31c20e73fa2924', 'learn', 3, 'definition', '{"term":"Translation","body":"Slides every point the same distance in the same direction. The rule $(x, y) \\to (x + a, y + b)$ moves $a$ units horizontally and $b$ units vertically; the vector $\\langle a, b \\rangle$ describes the same slide."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac0ae8eabd5ab5', 'les_31c20e73fa2924', 'experiment', 4, 'activity', '{"activity":"transformations","title":"Slide a triangle","params":{"kind":"translate"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d66ea130abc14', 'les_31c20e73fa2924', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Change the shifts and watch A′, B′, C′. The ratio A′B′ ÷ AB never changes from 1. Find the shift that sends A(1, 1) to the origin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6618ff36b7b25', 'les_31c20e73fa2924', 'learn', 6, 'worked_example', '{"title":"Translate $\\triangle ABC$ with $A(-2, 1)$, $B(1, 4)$, $C(3, -1)$ by $\\langle 4, -3 \\rangle$","steps":[{"latex":"A''(2, -2),\\ B''(5, 1),\\ C''(7, -4)","explanation":"Add 4 to each x and −3 to each y."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa7c917b05106f', 'les_31c20e73fa2924', 'learn', 7, 'worked_example', '{"title":"$P(3, -5)$ maps to $P''(-1, 2)$. Write the rule.","steps":[{"latex":"a = -1 - 3 = -4,\\ b = 2 - (-5) = 7","explanation":"Image minus preimage."},{"latex":"(x, y) \\to (x - 4,\\ y + 7)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_09ee3eb0fe6655', 'les_31c20e73fa2924', 'learn', 8, 'text', '{"body":"Because a translation moves every point by the same vector, segments joining preimage points to their images are all parallel and congruent. A translation also keeps orientation: if the vertices of the preimage go clockwise, so do the image''s."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6bc49e6304e85', 'les_31c20e73fa2924', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Animation and video games move sprites with translation vectors every frame. Wallpaper and tile patterns repeat a motif by translation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90271579c6a6ba', 'les_31c20e73fa2924', 1, 'practice', 'short_text', 1, 'Translate $(4, -2)$ by $(x, y) \to (x - 3, y + 5)$. Enter as (x,y).', '{"accept":["(1,3)"]}', '[]', '$(4 - 3, -2 + 5) = (1, 3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3dcd90e5fbf49c', 'les_31c20e73fa2924', 2, 'practice', 'short_text', 2, '$A(-6, 2)$ maps to $A''(1, -4)$. Write the translation vector as <a,b>.', '{"accept":["<7,-6>","⟨7,-6⟩","(7,-6)"]}', '["Subtract preimage from image."]', '$\langle 1 - (-6), -4 - 2 \rangle = \langle 7, -6 \rangle$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5e7e13c8e82e01', 'les_31c20e73fa2924', 3, 'practice', 'short_text', 2, 'Under the same translation, where does $B(0, 0)$ go? Enter as (x,y).', '{"accept":["(7,-6)"]}', '[]', '$(7, -6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac0ae8eabd5ab5', 'les_31c20e73fa2924', 4, 'practice', 'multiple_choice', 2, 'Which property is NOT preserved by every translation?', '{"choices":["Side lengths","Angle measures","Position on the plane","Orientation"],"answer":2}', '[]', 'A translation moves the figure, so its position changes; lengths, angles and orientation stay the same.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2d66ea130abc14', 'les_31c20e73fa2924', 5, 'review', 'short_text', 3, 'A translation maps $(2, 5)$ to $(-1, 9)$. Where does it map $(-3, -3)$? Enter as (x,y).', '{"accept":["(-6,1)"]}', '["The vector is ⟨−3, 4⟩."]', '$(-3 - 3, -3 + 4) = (-6, 1)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2d2b216d5cb495', 'subj_math', 'rigid-motions', 'Rigid motions', 'Transformations that preserve distance and angle measure: translations, reflections and rotations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_31c20e73fa2924', (SELECT id FROM concepts WHERE slug = 'rigid-motions'));

-- Lesson: trapezoids-kites
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6930b628646b54', 'trapezoids-kites', 'Trapezoids and kites', 'Use properties of isosceles trapezoids, the Trapezoid Midsegment Theorem and the properties of kites to find unknown lengths and angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e0b7fcbcf13a35', 'les_6930b628646b54', 1, 'Identify bases, legs and base angles of a trapezoid and properties of isosceles trapezoids.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0e968d2eb7107d', 'les_6930b628646b54', 2, 'Apply the Trapezoid Midsegment Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5fde250dcb824a', 'les_6930b628646b54', 3, 'Use the perpendicular diagonals and congruent opposite angles of a kite.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0b7fcbcf13a35', 'les_6930b628646b54', 'learn', 1, 'definition', '{"term":"Trapezoid","body":"A quadrilateral with exactly one pair of parallel sides, called the bases. The other two sides are the legs. An isosceles trapezoid has congruent legs."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e968d2eb7107d', 'les_6930b628646b54', 'learn', 2, 'definition', '{"term":"Isosceles trapezoid properties","body":"Each pair of base angles is congruent, and the diagonals are congruent. Angles on the same leg are supplementary (they''re same-side interior angles between the parallel bases), as in every trapezoid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fde250dcb824a', 'les_6930b628646b54', 'learn', 3, 'definition', '{"term":"Trapezoid Midsegment Theorem","body":"The segment joining the midpoints of the legs is parallel to the bases and its length is the average of the bases: $\\text{midsegment} = \\frac{b_1 + b_2}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_264ba7c92c2551', 'les_6930b628646b54', 'learn', 4, 'worked_example', '{"title":"A trapezoid has bases 14 and 22. Find the midsegment. If the midsegment of another trapezoid is 17 and one base is 12, find the other.","steps":[{"latex":"\\tfrac{14 + 22}{2} = 18","explanation":""},{"latex":"\\tfrac{12 + b}{2} = 17 \\Rightarrow b = 22","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_328cebdd6021f8', 'les_6930b628646b54', 'learn', 5, 'worked_example', '{"title":"In isosceles trapezoid $ABCD$ with bases $\\overline{AD}$ and $\\overline{BC}$, $m\\angle A = 64^\\circ$. Find the other angles.","steps":[{"latex":"m\\angle D = 64^\\circ","explanation":"Base angles of an isosceles trapezoid."},{"latex":"m\\angle B = m\\angle C = 116^\\circ","explanation":"Supplementary to 64° along each leg."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e12ab693bb2d2', 'les_6930b628646b54', 'learn', 6, 'definition', '{"term":"Kite","body":"A quadrilateral with two pairs of consecutive congruent sides, and no pair of opposite sides congruent. Its diagonals are perpendicular, and exactly one pair of opposite angles (the ones between the non-congruent sides) is congruent."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d08a73c8c86ce', 'les_6930b628646b54', 'learn', 7, 'worked_example', '{"title":"A kite has diagonals that meet at $E$. One diagonal is split into $EA = EC = 6$; the other has $EB = 8$ and $ED = 4.5$. Find the side lengths.","steps":[{"latex":"AB = \\sqrt{6^2 + 8^2} = 10","explanation":"The diagonals are perpendicular."},{"latex":"AD = \\sqrt{6^2 + 4.5^2} = 7.5","explanation":"So the kite''s sides are 10, 10, 7.5, 7.5."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a5ed09082b052', 'les_6930b628646b54', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Bridge supports, handbag shapes and the sides of a lampshade viewed head-on are trapezoids; the midsegment rule finds the width of a shelf placed halfway up a tapered bookcase. Kites (the toy) have perpendicular spars because of the kite''s diagonal property."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e0b7fcbcf13a35', 'les_6930b628646b54', 1, 'practice', 'numeric', 1, 'A trapezoid has bases 9 and 15. Find the length of its midsegment.', '{"answer":12}', '[]', '$(9 + 15) / 2 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e968d2eb7107d', 'les_6930b628646b54', 2, 'practice', 'numeric', 2, 'The midsegment of a trapezoid is 20 and one base is 26. Find the other base.', '{"answer":14}', '[]', '$2 \cdot 20 - 26 = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5fde250dcb824a', 'les_6930b628646b54', 3, 'practice', 'numeric', 2, 'In an isosceles trapezoid, one base angle measures $72^\circ$. Find the measure of each of the obtuse angles.', '{"answer":108,"unit":"°"}', '[]', '$180 - 72 = 108^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_264ba7c92c2551', 'les_6930b628646b54', 4, 'practice', 'numeric', 2, 'In kite $WXYZ$, $\angle X$ and $\angle Z$ are the congruent opposite angles, $m\angle W = 70^\circ$ and $m\angle Y = 110^\circ$. Find $m\angle X$.', '{"answer":90,"unit":"°"}', '["The four angles sum to 360°."]', '$(360 - 70 - 110) \div 2 = 90^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_328cebdd6021f8', 'les_6930b628646b54', 5, 'review', 'multiple_choice', 3, 'Which statement is true for every kite?', '{"choices":["Diagonals bisect each other","Diagonals are perpendicular","Diagonals are congruent","Opposite sides are parallel"],"answer":1}', '[]', 'A kite''s diagonals are perpendicular; only one of them bisects the other.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6930b628646b54', 'subj_math', 'trapezoids-kites', 'Trapezoids and kites', 'Quadrilaterals with exactly one pair of parallel sides, and those with two pairs of consecutive congruent sides.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6930b628646b54', (SELECT id FROM concepts WHERE slug = 'trapezoids-kites'));

-- Lesson: triangle-angle-sum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_30f05ac752c5fd', 'triangle-angle-sum', 'Triangle angle sum and exterior angles', 'Prove that a triangle''s angles sum to 180°, use the Exterior Angle Theorem, and classify triangles by sides and angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_20b057d4c3d521', 'les_30f05ac752c5fd', 1, 'Classify triangles by their sides and by their angles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_841100d51e2875', 'les_30f05ac752c5fd', 2, 'Prove and apply the Triangle Angle Sum Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_79c214246c01ea', 'les_30f05ac752c5fd', 3, 'Prove and apply the Exterior Angle Theorem.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_20b057d4c3d521', 'les_30f05ac752c5fd', 'learn', 1, 'definition', '{"term":"Classifying triangles","body":"By sides: scalene (no congruent sides), isosceles (at least two), equilateral (all three). By angles: acute (all angles acute), right (one right angle), obtuse (one obtuse angle), equiangular (all angles equal)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_841100d51e2875', 'les_30f05ac752c5fd', 'learn', 2, 'definition', '{"term":"Triangle Angle Sum Theorem","body":"The interior angles of a triangle sum to $180^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_79c214246c01ea', 'les_30f05ac752c5fd', 'learn', 3, 'text', '{"body":"Proof: through vertex $C$ of $\\triangle ABC$, draw the line parallel to $\\overline{AB}$ (the Parallel Postulate says exactly one exists). The three angles at $C$ along that line form a straight angle, $180^\\circ$. The two outer ones are alternate interior angles with $\\angle A$ and $\\angle B$, so they''re congruent to them. So $m\\angle A + m\\angle C + m\\angle B = 180^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a4e20b9559ef0', 'les_30f05ac752c5fd', 'learn', 4, 'definition', '{"term":"Exterior Angle Theorem","body":"An exterior angle of a triangle equals the sum of the two remote (non-adjacent) interior angles: $m\\angle 4 = m\\angle 1 + m\\angle 2$. It follows because $\\angle 4$ and $\\angle 3$ form a linear pair, and $\\angle 3$ plus $\\angle 1 + \\angle 2$ also total $180^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d904cb901947d2', 'les_30f05ac752c5fd', 'experiment', 5, 'activity', '{"activity":"triangle-explorer","title":"Drag the vertices","params":{"show":"angles"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5752ea445ed77b', 'les_30f05ac752c5fd', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Drag any vertex. The angle sum stays $180^\\circ$ and the exterior angle at C always equals $\\angle A + \\angle B$. Can you make a triangle with two obtuse angles? Why not?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc7dbec94b780f', 'les_30f05ac752c5fd', 'learn', 7, 'worked_example', '{"title":"The angles of a triangle are $(2x)^\\circ$, $(3x + 5)^\\circ$ and $(4x - 14)^\\circ$. Find them.","steps":[{"latex":"2x + 3x + 5 + 4x - 14 = 180","explanation":""},{"latex":"9x - 9 = 180 \\Rightarrow x = 21","explanation":""},{"latex":"42^\\circ,\\ 68^\\circ,\\ 70^\\circ","explanation":"Check: 42 + 68 + 70 = 180 ✓."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d11371c90de9ad', 'les_30f05ac752c5fd', 'learn', 8, 'worked_example', '{"title":"An exterior angle measures $(5x - 10)^\\circ$, and the remote interior angles are $(2x + 4)^\\circ$ and $40^\\circ$. Find $x$.","steps":[{"latex":"5x - 10 = 2x + 4 + 40","explanation":"Exterior Angle Theorem."},{"latex":"3x = 54 \\Rightarrow x = 18","explanation":"The exterior angle is 80°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fde6c8f98e0f2', 'les_30f05ac752c5fd', 'learn', 9, 'callout', '{"tone":"note","title":"Corollaries","body":"The acute angles of a right triangle are complementary. A triangle can have at most one right or obtuse angle. Each angle of an equiangular triangle is $60^\\circ$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6fad9b7f584dd3', 'les_30f05ac752c5fd', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Roof trusses, bridge frames and navigation by triangulation rely on these angle facts: knowing two angles always gives you the third."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_20b057d4c3d521', 'les_30f05ac752c5fd', 1, 'practice', 'numeric', 1, 'Two angles of a triangle measure $47^\circ$ and $78^\circ$. Find the third.', '{"answer":55,"unit":"°"}', '[]', '$180 - 47 - 78 = 55^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_841100d51e2875', 'les_30f05ac752c5fd', 2, 'practice', 'numeric', 1, 'One acute angle of a right triangle is $34^\circ$. Find the other.', '{"answer":56,"unit":"°"}', '[]', '$90 - 34 = 56^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_79c214246c01ea', 'les_30f05ac752c5fd', 3, 'practice', 'numeric', 2, 'The remote interior angles of an exterior angle are $52^\circ$ and $61^\circ$. Find the exterior angle.', '{"answer":113,"unit":"°"}', '[]', '$52 + 61 = 113^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7a4e20b9559ef0', 'les_30f05ac752c5fd', 4, 'practice', 'numeric', 2, 'A triangle''s angles are in the ratio $2 : 3 : 4$. Find the largest angle.', '{"answer":80,"unit":"°"}', '["$2x + 3x + 4x = 180$."]', '$x = 20$, so the angles are $40^\circ$, $60^\circ$, $80^\circ$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d904cb901947d2', 'les_30f05ac752c5fd', 5, 'practice', 'multiple_choice', 2, 'A triangle has angles $30^\circ$, $60^\circ$, $90^\circ$ and sides of three different lengths. Classify it.', '{"choices":["Acute scalene","Right scalene","Right isosceles","Obtuse scalene"],"answer":1}', '[]', 'One right angle and no congruent sides: right scalene.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5752ea445ed77b', 'les_30f05ac752c5fd', 6, 'review', 'numeric', 3, 'An exterior angle of a triangle is $(4x + 2)^\circ$. Its remote interior angles are $(x + 20)^\circ$ and $(2x + 7)^\circ$. Find the exterior angle.', '{"answer":102,"unit":"°"}', '["$4x + 2 = 3x + 27$."]', '$x = 25$, so the exterior angle is $4(25) + 2 = 102^\circ$. Check: the remote angles are $45^\circ$ and $57^\circ$, which sum to $102^\circ$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a2be333685753f', 'subj_math', 'triangle-angles', 'Triangle angles', 'Interior angles of a triangle sum to 180°; an exterior angle equals the sum of the remote interior angles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_30f05ac752c5fd', (SELECT id FROM concepts WHERE slug = 'triangle-angles'));

-- Lesson: triangle-inequalities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7ef4da5ac51f25', 'triangle-inequalities', 'Triangle inequalities', 'Use the Triangle Inequality Theorem to test side lengths and find the possible range of a third side, and relate the sizes of sides to the sizes of opposite angles.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1f71e196d6e056', 'les_7ef4da5ac51f25', 1, 'Decide whether three lengths can form a triangle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_60f715a50fe716', 'les_7ef4da5ac51f25', 2, 'Find the range of possible lengths for the third side.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_89ba2fa7213645', 'les_7ef4da5ac51f25', 3, 'Order the sides and angles of a triangle: the longest side is opposite the largest angle.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f71e196d6e056', 'les_7ef4da5ac51f25', 'learn', 1, 'definition', '{"term":"Triangle Inequality Theorem","body":"The sum of the lengths of any two sides of a triangle is greater than the length of the third side: $a + b > c$, $a + c > b$, $b + c > a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60f715a50fe716', 'les_7ef4da5ac51f25', 'learn', 2, 'text', '{"body":"Picture two short sticks hinged at one end, trying to span a long gap. If their combined length is less than the gap, or exactly equal to it, they can''t rise to form a triangle; they lie flat. It''s enough to check that the two shorter sides add up to more than the longest."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89ba2fa7213645', 'les_7ef4da5ac51f25', 'learn', 3, 'worked_example', '{"title":"Can 4, 7 and 12 be side lengths? What about 5, 8, 11?","steps":[{"latex":"4 + 7 = 11 < 12","explanation":"No triangle."},{"latex":"5 + 8 = 13 > 11","explanation":"Yes, a triangle."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04ddb71b490709', 'les_7ef4da5ac51f25', 'learn', 4, 'worked_example', '{"title":"Two sides are 9 and 15. What lengths are possible for the third side $x$?","steps":[{"latex":"x < 9 + 15 = 24","explanation":""},{"latex":"x > 15 - 9 = 6","explanation":""},{"latex":"6 < x < 24","explanation":"The third side is between the difference and the sum."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06459c61182cf3', 'les_7ef4da5ac51f25', 'learn', 5, 'definition', '{"term":"Sides and opposite angles","body":"In a triangle, a longer side is opposite a larger angle, and a larger angle is opposite a longer side. So the longest side is across from the largest angle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb834a360701bd', 'les_7ef4da5ac51f25', 'experiment', 6, 'activity', '{"activity":"triangle-explorer","title":"Compare sides and opposite angles","params":{"show":"angles"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3546d78adb4bb1', 'les_7ef4da5ac51f25', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"Drag C until $\\angle C$ is the largest angle. Is AB (opposite C) the longest side? Now try to drag C onto line AB: the simulation won''t let the triangle flatten, because then the two sides would just add up to the third."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25cab6bc9e1666', 'les_7ef4da5ac51f25', 'learn', 8, 'worked_example', '{"title":"In $\\triangle PQR$, $m\\angle P = 50^\\circ$, $m\\angle Q = 72^\\circ$. Order the sides from shortest to longest.","steps":[{"latex":"m\\angle R = 58^\\circ","explanation":""},{"latex":"50 < 58 < 72","explanation":"Angles in order: P, R, Q."},{"latex":"QR < PQ < PR","explanation":"Opposite sides: QR across from P, PQ across from R, PR across from Q."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2f0e6c477e1d28', 'les_7ef4da5ac51f25', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"The triangle inequality says a detour through a third point is never shorter than going straight, which is why GPS routing and network design use it to prune impossible shortcuts."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f71e196d6e056', 'les_7ef4da5ac51f25', 1, 'practice', 'multiple_choice', 1, 'Which set of lengths can form a triangle?', '{"choices":["2, 3, 6","3, 4, 7","5, 6, 10","1, 1, 3"],"answer":2}', '["Check the two shorter sides against the longest."]', '$5 + 6 = 11 > 10$. The others fail: $5 < 6$, $7 = 7$, $2 < 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60f715a50fe716', 'les_7ef4da5ac51f25', 2, 'practice', 'short_text', 2, 'Two sides of a triangle are 6 and 13. Give the range of the third side x as a<x<b.', '{"accept":["7<x<19"]}', '["Difference < x < sum."]', '$7 < x < 19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89ba2fa7213645', 'les_7ef4da5ac51f25', 3, 'practice', 'multiple_choice', 2, 'In $\triangle ABC$, $AB = 8$, $BC = 11$, $AC = 5$. Which angle is largest?', '{"choices":["$\\angle A$","$\\angle B$","$\\angle C$","They''re equal"],"answer":0}', '["The largest angle is opposite the longest side."]', '$BC = 11$ is longest and is opposite $\angle A$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04ddb71b490709', 'les_7ef4da5ac51f25', 4, 'practice', 'multiple_choice', 2, 'In $\triangle XYZ$, $m\angle X = 40^\circ$ and $m\angle Y = 85^\circ$. Which side is shortest?', '{"choices":["$\\overline{XY}$","$\\overline{YZ}$","$\\overline{XZ}$","Can''t tell"],"answer":1}', '["The smallest angle is ∠X (40°); ∠Z is 55°."]', 'The shortest side is opposite the smallest angle, $\angle X$: that''s $\overline{YZ}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06459c61182cf3', 'les_7ef4da5ac51f25', 5, 'review', 'short_text', 3, 'Two sides of an isosceles triangle are 4 and 9. What is the length of the third side?', '{"accept":["9"]}', '["Try 4 and 9 as the repeated side."]', 'If the sides were 4, 4, 9, then $4 + 4 < 9$, impossible. So the sides are 4, 9, 9 and the third side is 9.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_025669f043ddf1', 'subj_math', 'triangle-inequality', 'Triangle inequality', 'The sum of any two sides of a triangle is greater than the third side.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7ef4da5ac51f25', (SELECT id FROM concepts WHERE slug = 'triangle-inequality'));

-- Lesson: trig-ratios
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ce103b0d7be6b4', 'trig-ratios', 'Sine, cosine and tangent ratios', 'Define sine, cosine and tangent as ratios in a right triangle, explain why they depend only on the angle, and use them to find missing sides.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_80e5a2a34bbd80', 'les_ce103b0d7be6b4', 1, 'Identify the opposite, adjacent and hypotenuse relative to an acute angle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_60faf27d9729b6', 'les_ce103b0d7be6b4', 2, 'Define sin, cos and tan and explain why they depend only on the angle (similarity).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a5ac6c5cfb79a9', 'les_ce103b0d7be6b4', 3, 'Use trig ratios to find missing side lengths, and relate sine and cosine of complementary angles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80e5a2a34bbd80', 'les_ce103b0d7be6b4', 'learn', 1, 'text', '{"body":"All right triangles with the same acute angle $\\theta$ are similar (AA). So the ratio of any two of their sides is the same no matter how big the triangle is. Those fixed ratios get names."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60faf27d9729b6', 'les_ce103b0d7be6b4', 'learn', 2, 'formula', '{"latex":"\\sin\\theta = \\frac{\\text{opp}}{\\text{hyp}}, \\quad \\cos\\theta = \\frac{\\text{adj}}{\\text{hyp}}, \\quad \\tan\\theta = \\frac{\\text{opp}}{\\text{adj}}","title":"Trigonometric ratios","note":"SOH-CAH-TOA is a common memory aid."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5ac6c5cfb79a9', 'les_ce103b0d7be6b4', 'experiment', 3, 'activity', '{"activity":"right-triangle-trig","title":"Ratios depend only on the angle","params":{"angle":35,"hyp":10}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26f642128f42a5', 'les_ce103b0d7be6b4', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Keep θ at 35° and change the hypotenuse: the sides change but sin, cos and tan don''t. Now set θ = 30°: sin is exactly 0.5. Set θ = 45°: tan is 1. Why, from the special right triangles?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_affd555fa0ffe9', 'les_ce103b0d7be6b4', 'learn', 5, 'worked_example', '{"title":"In right $\\triangle ABC$ with right angle $C$, $AC = 8$, $BC = 15$, $AB = 17$. Find $\\sin A$, $\\cos A$, $\\tan A$.","steps":[{"latex":"\\sin A = \\tfrac{BC}{AB} = \\tfrac{15}{17}","explanation":"BC is opposite A."},{"latex":"\\cos A = \\tfrac{AC}{AB} = \\tfrac{8}{17}","explanation":"AC is adjacent to A."},{"latex":"\\tan A = \\tfrac{15}{8}","explanation":""}],"check":"Notice $\\sin B = \\frac{8}{17} = \\cos A$: the sine of an angle equals the cosine of its complement."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ae2e5256ccc24d', 'les_ce103b0d7be6b4', 'learn', 6, 'worked_example', '{"title":"A ramp makes a $12^\\circ$ angle with the ground and is 5 m long. How high does it rise?","steps":[{"latex":"\\sin 12^\\circ = \\tfrac{h}{5}","explanation":"The height is opposite the angle; the ramp is the hypotenuse."},{"latex":"h = 5 \\sin 12^\\circ \\approx 5(0.2079) \\approx 1.04 \\text{ m}","explanation":"Calculator in degree mode."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa62c29f1d7974', 'les_ce103b0d7be6b4', 'learn', 7, 'worked_example', '{"title":"In a right triangle, an angle is $40^\\circ$ and its adjacent leg is 20. Find the hypotenuse.","steps":[{"latex":"\\cos 40^\\circ = \\tfrac{20}{c}","explanation":""},{"latex":"c = \\tfrac{20}{\\cos 40^\\circ} \\approx \\tfrac{20}{0.7660} \\approx 26.11","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_224d63f39a26be', 'les_ce103b0d7be6b4', 'learn', 8, 'definition', '{"term":"Complementary angles","body":"$\\sin\\theta = \\cos(90^\\circ - \\theta)$ and $\\cos\\theta = \\sin(90^\\circ - \\theta)$. The side opposite one acute angle is adjacent to the other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6cfabcfa62c2a', 'les_ce103b0d7be6b4', 'learn', 9, 'callout', '{"tone":"warning","title":"Degree mode","body":"Make sure your calculator is in degree mode. In radian mode, $\\sin 30$ gives about $-0.988$ instead of 0.5."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28eb0e7c616af3', 'les_ce103b0d7be6b4', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"Road grades, wheelchair-ramp codes, roof pitch, GPS and robotics all use these ratios. Engineers specify ramps by angle and compute heights with sine."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_80e5a2a34bbd80', 'les_ce103b0d7be6b4', 1, 'practice', 'short_text', 1, 'In a right triangle with legs 3 and 4 and hypotenuse 5, what is $\sin\theta$ for the angle opposite the side of length 3? Enter a fraction.', '{"accept":["3/5","0.6"]}', '[]', '$\frac{3}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60faf27d9729b6', 'les_ce103b0d7be6b4', 2, 'practice', 'numeric', 2, 'Find $x$ to the nearest hundredth: $\tan 28^\circ = \frac{x}{10}$.', '{"answer":5.32,"tolerance":0.006}', '["$x = 10\\tan 28^\\circ$."]', '$10(0.5317) \approx 5.32$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a5ac6c5cfb79a9', 'les_ce103b0d7be6b4', 3, 'practice', 'numeric', 2, 'A 12 ft ladder leans against a wall at a $70^\circ$ angle with the ground. How high up the wall does it reach? Round to the nearest tenth.', '{"answer":11.3,"unit":"ft","tolerance":0.06}', '["$12\\sin 70^\\circ$."]', '$12(0.9397) \approx 11.3$ ft.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26f642128f42a5', 'les_ce103b0d7be6b4', 4, 'practice', 'numeric', 2, 'In a right triangle, an acute angle is $25^\circ$ and the opposite leg is 7. Find the hypotenuse to the nearest tenth.', '{"answer":16.6,"tolerance":0.06}', '["$\\sin 25^\\circ = \\frac{7}{c}$."]', '$c = 7 / 0.4226 \approx 16.6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_affd555fa0ffe9', 'les_ce103b0d7be6b4', 5, 'practice', 'multiple_choice', 2, 'If $\sin A = 0.6$ in a right triangle with acute angles $A$ and $B$, what is $\cos B$?', '{"choices":["0.4","0.6","0.8","Cannot tell"],"answer":1}', '["A and B are complementary."]', '$\cos B = \sin(90^\circ - B) = \sin A = 0.6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ae2e5256ccc24d', 'les_ce103b0d7be6b4', 6, 'review', 'multiple_choice', 3, 'Why is $\tan 45^\circ = 1$?', '{"choices":["Because 45 is half of 90","In a 45-45-90 triangle the legs are equal, so opp/adj = 1","Because sin 45° = 1","It''s a definition"],"answer":1}', '[]', 'The opposite and adjacent legs are congruent.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_68e5b8ea0a287f', 'subj_math', 'trigonometric-ratios', 'Trigonometric ratios', 'Sine, cosine and tangent: ratios of sides in a right triangle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ce103b0d7be6b4', (SELECT id FROM concepts WHERE slug = 'trigonometric-ratios'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ce103b0d7be6b4', (SELECT id FROM formulas WHERE slug = 'trig-ratios'), 1);

-- Lesson: two-column-proofs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9a7112785ca078', 'two-column-proofs', 'Writing two-column proofs', 'Organize a geometric argument as statements with reasons, using properties of equality and congruence, definitions, postulates and theorems.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b994d0d68ffa5', 'les_9a7112785ca078', 1, 'Use the reflexive, symmetric, transitive and substitution properties as reasons.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_25ba575bc8812d', 'les_9a7112785ca078', 2, 'Write two-column proofs about segments and angles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1ef11b568a542c', 'les_9a7112785ca078', 3, 'Prove simple theorems such as the Congruent Supplements Theorem.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b994d0d68ffa5', 'les_9a7112785ca078', 'learn', 1, 'text', '{"body":"A proof is a chain of statements in which each one follows from earlier ones. In a two-column proof the left column lists statements and the right column gives a reason for each: \"Given,\" a definition, a property, a postulate or a theorem already proved."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25ba575bc8812d', 'les_9a7112785ca078', 'learn', 2, 'definition', '{"term":"Properties of congruence","body":"Reflexive: $\\overline{AB} \\cong \\overline{AB}$. Symmetric: if $\\angle A \\cong \\angle B$, then $\\angle B \\cong \\angle A$. Transitive: if $\\overline{AB} \\cong \\overline{CD}$ and $\\overline{CD} \\cong \\overline{EF}$, then $\\overline{AB} \\cong \\overline{EF}$. The same properties hold for equality, along with substitution and the addition, subtraction, multiplication and division properties."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ef11b568a542c', 'les_9a7112785ca078', 'learn', 3, 'worked_example', '{"title":"Given: $AB = CD$, with points in order $A, B, C, D$ on a line. Prove: $AC = BD$.","steps":[{"latex":"1.\\ AB = CD","explanation":"Given."},{"latex":"2.\\ AB + BC = CD + BC","explanation":"Addition property of equality."},{"latex":"3.\\ AB + BC = AC,\\ BC + CD = BD","explanation":"Segment Addition Postulate."},{"latex":"4.\\ AC = BD","explanation":"Substitution (steps 2 and 3)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57eb957c762e6e', 'les_9a7112785ca078', 'learn', 4, 'worked_example', '{"title":"Congruent Supplements Theorem. Given: $\\angle 1$ and $\\angle 2$ are supplementary, $\\angle 3$ and $\\angle 2$ are supplementary. Prove: $\\angle 1 \\cong \\angle 3$.","steps":[{"latex":"1.\\ m\\angle 1 + m\\angle 2 = 180^\\circ,\\ m\\angle 3 + m\\angle 2 = 180^\\circ","explanation":"Definition of supplementary angles."},{"latex":"2.\\ m\\angle 1 + m\\angle 2 = m\\angle 3 + m\\angle 2","explanation":"Substitution (or transitive property)."},{"latex":"3.\\ m\\angle 1 = m\\angle 3","explanation":"Subtraction property of equality."},{"latex":"4.\\ \\angle 1 \\cong \\angle 3","explanation":"Definition of congruent angles."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84d13ee12332a5', 'les_9a7112785ca078', 'learn', 5, 'callout', '{"tone":"tip","title":"Plan before you write","body":"Start from what you want to prove and ask, \"What would I need to know right before this?\" Work backwards to the givens, then write the proof forwards."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0296ec4c38def5', 'les_9a7112785ca078', 'learn', 6, 'callout', '{"tone":"warning","title":"Equal vs congruent","body":"Measures are equal ($AB = CD$, $m\\angle A = m\\angle B$); figures are congruent ($\\overline{AB} \\cong \\overline{CD}$). Switching between them needs the definition of congruence as a reason."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d2a683e95f5cd', 'les_9a7112785ca078', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Structured proofs train the same skill as writing a convincing argument in an essay, debugging code step by step, or checking a contract: every claim needs support."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b994d0d68ffa5', 'les_9a7112785ca078', 1, 'practice', 'multiple_choice', 1, 'Which property justifies $\angle P \cong \angle P$?', '{"choices":["Symmetric","Reflexive","Transitive","Substitution"],"answer":1}', '[]', 'Anything is congruent to itself: the reflexive property.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_25ba575bc8812d', 'les_9a7112785ca078', 2, 'practice', 'multiple_choice', 2, 'If $\overline{AB} \cong \overline{CD}$ and $\overline{CD} \cong \overline{EF}$, then $\overline{AB} \cong \overline{EF}$. Which property is this?', '{"choices":["Reflexive","Symmetric","Transitive","Addition"],"answer":2}', '[]', 'The transitive property.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ef11b568a542c', 'les_9a7112785ca078', 3, 'practice', 'multiple_choice', 2, 'Which reason justifies "$2x = 14$, so $x = 7$"?', '{"choices":["Multiplication property","Division property of equality","Distributive property","Substitution"],"answer":1}', '[]', 'Both sides were divided by 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57eb957c762e6e', 'les_9a7112785ca078', 4, 'practice', 'multiple_choice', 2, 'In a proof, which statement could follow "$M$ is the midpoint of $\overline{AB}$" with reason "Definition of midpoint"?', '{"choices":["$AM = AB$","$\\overline{AM} \\cong \\overline{MB}$","$M$ is on line $AB$ only","$AM = 2MB$"],"answer":1}', '[]', 'A midpoint divides a segment into two congruent segments.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_84d13ee12332a5', 'les_9a7112785ca078', 5, 'review', 'multiple_choice', 3, 'What theorem lets you conclude $\angle 1 \cong \angle 3$ if both are complementary to $\angle 2$?', '{"choices":["Vertical Angles Theorem","Congruent Complements Theorem","Linear Pair Postulate","Angle Addition Postulate"],"answer":1}', '[]', 'Angles complementary to the same angle are congruent.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9a7112785ca078', (SELECT id FROM concepts WHERE slug = 'algebraic-proof'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0ec7ceb9331d7a', 'subj_math', 'geometric-proof', 'Geometric proof', 'Justifying geometric statements with definitions, postulates and theorems.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9a7112785ca078', (SELECT id FROM concepts WHERE slug = 'geometric-proof'));

-- Lesson: volume-of-solids
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_82759af4af1f8c', 'volume-of-solids', 'Volume of prisms, cylinders, pyramids, cones and spheres', 'Use Cavalieri''s principle and the volume formulas for prisms, cylinders, pyramids, cones and spheres, including composite solids and scaling.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_29067b2121daea', 'les_82759af4af1f8c', 1, 'Explain V = Bh with Cavalieri''s principle, including oblique solids.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a0f05d2796bef', 'les_82759af4af1f8c', 2, 'Find volumes of pyramids and cones (one third of the matching prism or cylinder) and spheres.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e72086d02c17d', 'les_82759af4af1f8c', 3, 'Find volumes of composite solids and use k³ scaling for similar solids.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_29067b2121daea', 'les_82759af4af1f8c', 'learn', 1, 'definition', '{"term":"Cavalieri''s principle","body":"If two solids have the same height and every horizontal cross-section has the same area, they have the same volume. That''s why an oblique (slanted) prism or cylinder still has $V = Bh$, with $h$ the perpendicular height, like a stack of coins pushed sideways."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a0f05d2796bef', 'les_82759af4af1f8c', 'learn', 2, 'text', '{"body":"A pyramid has exactly one third the volume of the prism with the same base and height: $V = \\frac{1}{3}Bh$. Likewise a cone is $\\frac{1}{3}\\pi r^2 h$. (Fill a cone with water: it takes three cones to fill the matching cylinder.) A sphere has $V = \\frac{4}{3}\\pi r^3$, which is two thirds of the cylinder that just contains it, a result Archimedes was proudest of."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e72086d02c17d', 'les_82759af4af1f8c', 'experiment', 3, 'activity', '{"activity":"area-volume","title":"Volume of a prism and a cylinder","params":{"shape":"prism"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c82fc5337a6ef4', 'les_82759af4af1f8c', 'learn', 4, 'worked_example', '{"title":"Find the volume of a cone with radius 3 and height 7.","steps":[{"latex":"V = \\tfrac{1}{3}\\pi(9)(7) = 21\\pi \\approx 65.97","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_77f62e50bb3969', 'les_82759af4af1f8c', 'learn', 5, 'worked_example', '{"title":"Find the volume of a sphere with diameter 12.","steps":[{"latex":"r = 6","explanation":""},{"latex":"V = \\tfrac{4}{3}\\pi(216) = 288\\pi \\approx 904.78","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e47b1e54a42979', 'les_82759af4af1f8c', 'learn', 6, 'worked_example', '{"title":"An ice cream cone (radius 3 cm, height 10 cm) is topped by a hemisphere of ice cream. Find the total volume.","steps":[{"latex":"\\text{cone} = \\tfrac{1}{3}\\pi(9)(10) = 30\\pi","explanation":""},{"latex":"\\text{hemisphere} = \\tfrac{1}{2} \\cdot \\tfrac{4}{3}\\pi(27) = 18\\pi","explanation":""},{"latex":"48\\pi \\approx 150.80 \\text{ cm}^3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ace3d71b9118ee', 'les_82759af4af1f8c', 'learn', 7, 'callout', '{"tone":"warning","title":"Volume scales by k³","body":"If two solids are similar with scale factor $k$, their volumes are in the ratio $k^3$. A model at scale 1 : 10 holds $\\frac{1}{1000}$ as much."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_582a1563cf9d31', 'les_82759af4af1f8c', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Concrete for a column, grain in a conical pile, air in a basketball, and how much a funnel holds are volume problems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_29067b2121daea', 'les_82759af4af1f8c', 1, 'practice', 'numeric', 1, 'Find the volume of a square pyramid with base edge 6 and height 10.', '{"answer":120}', '["$\\frac{1}{3}(36)(10)$."]', '$120$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a0f05d2796bef', 'les_82759af4af1f8c', 2, 'practice', 'numeric', 2, 'Find the volume of a sphere with radius 3, to the nearest tenth.', '{"answer":113.1,"tolerance":0.06}', '["$\\frac{4}{3}\\pi(27) = 36\\pi$."]', '$36\pi \approx 113.1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e72086d02c17d', 'les_82759af4af1f8c', 3, 'practice', 'numeric', 2, 'A cone and a cylinder have the same radius and height. The cylinder holds 90 mL. How much does the cone hold?', '{"answer":30,"unit":"mL"}', '[]', 'One third: 30 mL.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c82fc5337a6ef4', 'les_82759af4af1f8c', 4, 'practice', 'numeric', 2, 'Two similar cylinders have heights 4 and 12. The smaller has volume 20. Find the larger volume.', '{"answer":540}', '["$k = 3$, so multiply by $k^3$."]', '$20 \cdot 27 = 540$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_77f62e50bb3969', 'les_82759af4af1f8c', 5, 'review', 'numeric', 3, 'A cylinder of radius 2 and height 9 has a cone of the same base and height carved out of it. Find the remaining volume, to the nearest tenth.', '{"answer":75.4,"tolerance":0.06}', '["Cylinder $36\\pi$, cone $12\\pi$."]', '$24\pi \approx 75.4$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_82759af4af1f8c', (SELECT id FROM concepts WHERE slug = 'volume'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_82759af4af1f8c', (SELECT id FROM formulas WHERE slug = 'prism-cylinder-volume'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_82759af4af1f8c', (SELECT id FROM formulas WHERE slug = 'pyramid-cone-sphere'), 2);

